// ── range values in index position ─────────────────────────────

/// B-2026-08-18-3 — `let r = 1..3; v[r]` panicked with an internal
/// `unreachable!()`: "index expression at 4:13: obj=Value::Array,
/// index=Value::Iterator". The index path read its bounds SYNTACTICALLY off an
/// `ExprKind::Range`, so a range arriving through a binding never entered it,
/// and an internal-error backtrace was the answer to a program `karac check`
/// had just passed.
///
/// The typechecker was right throughout — `1..3` is `Range[i64]`, `v[r]` is
/// `Slice[i64]`, and a non-contiguous iterator index is rejected with a span —
/// so the fix belonged in the evaluator, not in a new rejection.
#[test]
fn test_index_by_a_let_bound_range() {
    // The row's repro, and the inline spelling it must agree with.
    assert_eq!(
        run(
            "fn main() { let v = [10, 20, 30, 40]; let r = 1..3; let s = v[r]; println(s.len()); }"
        ),
        "2\n"
    );
    assert_eq!(
        run("fn main() { let v = [10, 20, 30, 40]; let s = v[1..3]; println(s.len()); }"),
        "2\n"
    );
    // The slice is the right WINDOW, not merely the right length.
    assert_eq!(
        run("fn main() { let v = [10, 20, 30, 40]; let r = 1..3; let s = v[r]; println(s[0]); println(s[1]); }"),
        "20\n30\n"
    );
    // Inclusive, and empty.
    assert_eq!(
        run("fn main() { let v = [10, 20, 30, 40]; let r = 1..=2; let s = v[r]; println(s.len()); println(s[1]); }"),
        "2\n30\n"
    );
    assert_eq!(
        run(
            "fn main() { let v = [10, 20, 30, 40]; let r = 2..2; let s = v[r]; println(s.len()); }"
        ),
        "0\n"
    );
}

/// A range is a VALUE, so its bounds are fixed where it is bound — the rule
/// B-2026-08-17-29 settled for the loop position, holding here too. Mutating
/// the source binding afterwards must not move the window.
#[test]
fn test_let_bound_range_index_captures_its_bounds() {
    assert_eq!(
        run(
            "fn main() { let v = [10, 20, 30, 40]; let mut a = 1; let r = a..3; a = 0;\n\
             let s = v[r]; println(s.len()); println(s[0]); }"
        ),
        "2\n20\n"
    );
}

// ── `?.` (optional chaining) ───────────────────────────────────

/// B-2026-08-17-28 — design.md line 782: "`user.address?.city?.name`
/// short-circuits to `None` if any level is absent." Three separate defects
/// stood between that sentence and the interpreter, all rooted in `?.` never
/// FLATTENING its projection.
///
/// The chain is the test, because the chain is what flattening is for: a
/// second `?.` can only project from a payload, so if the first produced
/// `Option[Option[City]]` the rest of the spec's example cannot work.
#[test]
fn test_optional_chain_flattens_and_short_circuits() {
    let decls = "struct City { name: String, zip: i64 }\n\
                 struct Address { city: Option[City], zip: i64 }\n\
                 struct User { address: Option[Address] }\n";
    let build = |addr: &str| {
        format!(
            "{decls}fn main() {{ let u = User {{ address: {addr} }};\n\
             match u.address?.city?.name {{ Some(n) => {{ println(n); }} None => {{ println(\"none\"); }} }} }}"
        )
    };
    // Every level present: the spec's own example. Used to print "none".
    assert_eq!(
        run(&build(
            "Some(Address { city: Some(City { name: \"Paris\", zip: 7 }), zip: 3 })"
        )),
        "Paris\n"
    );
    // Absent at the INNER level, and at the OUTER level: both short-circuit.
    assert_eq!(
        run(&build("Some(Address { city: None, zip: 3 })")),
        "none\n"
    );
    assert_eq!(run(&build("None")), "none\n");
}

/// The single-level chain in both member shapes. A struct-typed member is the
/// one that ICE'd: the Some-arm binding held `Some(City)` rather than `City`,
/// so reading a field off it tripped `eval_field_access`'s `unreachable!`.
#[test]
fn test_optional_chain_single_level_binds_the_payload_not_a_wrapper() {
    let decls = "struct City { name: String, zip: i64 }\n\
                 struct Address { city: Option[City], zip: i64 }\n\
                 fn mk() -> Option[Address] { return Some(Address { city: Some(City { name: \"Paris\", zip: 7 }), zip: 3 }); }\n";
    // An `Option`-typed member FLATTENS — `c` is a `City`, so `c.name` reads.
    assert_eq!(
        run(&format!(
            "{decls}fn main() {{ match mk()?.city {{ Some(c) => {{ println(c.name); }} None => {{ println(\"none\"); }} }} }}"
        )),
        "Paris\n"
    );
    // A NON-`Option` member wraps, which is the case that always worked and
    // must keep working — the flattening rule has to leave it alone.
    assert_eq!(
        run(&format!(
            "{decls}fn main() {{ match mk()?.zip {{ Some(z) => {{ println(z); }} None => {{ println(\"none\"); }} }} }}"
        )),
        "3\n"
    );
}

/// The method form, which the row did not name: `args` was discarded and the
/// member looked up as a FIELD, so `c?.label()` found nothing and produced
/// `Unit` — surfacing later as a bogus "operator 'Add' is not defined for
/// 'String' and 'Unit'" on a program `karac check` had passed.
#[test]
fn test_optional_chain_method_form_calls_the_method() {
    let src = "struct City { name: String, zip: i64 }\n\
               impl City { fn label(ref self) -> String { return self.name; } }\n\
               fn mk(present: bool) -> Option[City] {\n\
                   if present { return Some(City { name: \"Paris\", zip: 7 }); }\n\
                   return None;\n\
               }\n";
    assert_eq!(
        run(&format!(
            "{src}fn main() {{ match mk(true)?.label() {{ Some(s) => {{ println(s); }} None => {{ println(\"none\"); }} }} }}"
        )),
        "Paris\n"
    );
    // and it still short-circuits rather than calling the method on nothing
    assert_eq!(
        run(&format!(
            "{src}fn main() {{ match mk(false)?.label() {{ Some(s) => {{ println(s); }} None => {{ println(\"none\"); }} }} }}"
        )),
        "none\n"
    );
}

// ── `??` (nil coalescing) ──────────────────────────────────────

/// B-2026-08-17-27 — the interpreter's `??` was wrong on three of its four
/// legs. It recognized only a unit `None`, returning the operand UNCHANGED for
/// everything else: `Some(7) ?? -1` gave `Some(7)` where design.md line 782
/// says the wrapper is stripped, and `Err("bad") ?? -1` propagated the error
/// instead of taking the fallback. Only `None` was right.
///
/// All four legs, both wrappers, scalar and heap payloads.
#[test]
fn test_nil_coalesce_strips_the_wrapper_on_every_leg() {
    let prelude = "fn find(k: i64) -> Option[i64] { if k == 7 { return Some(7); } return None; }\n\
                   fn name(k: i64) -> Option[String] { if k == 1 { return Some(\"hit\"); } return None; }\n\
                   fn res(k: i64) -> Result[i64, String] { if k == 1 { return Ok(12); } return Err(\"bad\"); }\n\
                   fn sres(k: i64) -> Result[String, String] { if k == 1 { return Ok(\"fine\"); } return Err(\"bad\"); }\n";
    for (expr, want) in [
        ("find(7) ?? -1", "7\n"),  // Option/Some — used to print `Some(7)`
        ("find(3) ?? -1", "-1\n"), // Option/None — the one leg that was right
        ("res(1) ?? -1", "12\n"),  // Result/Ok   — used to print `Ok(12)`
        ("res(2) ?? -1", "-1\n"),  // Result/Err  — used to print `Err(bad)`
        ("name(1) ?? \"miss\"", "hit\n"),
        ("name(2) ?? \"miss\"", "miss\n"),
        ("sres(1) ?? \"fell\"", "fine\n"),
        ("sres(2) ?? \"fell\"", "fell\n"),
    ] {
        assert_eq!(
            run(&format!("{prelude}fn main() {{ println({expr}); }}")),
            want,
            "`{expr}`"
        );
    }
}

/// The stripped payload must be a usable `T`, not merely one that prints
/// right. This is the shape the row reported dying on: with the wrapper left
/// in place, `+ 1` hit "operator 'Add' is not defined for operands of type
/// 'EnumVariant' and 'Int'" at runtime, on a program `karac check` had passed.
#[test]
fn test_nil_coalesce_result_is_the_bare_payload() {
    assert_eq!(
        run(
            "fn find(k: i64) -> Option[i64] { if k == 7 { return Some(7); } return None; }\n\
             fn main() { println((find(7) ?? -1) + 1); println((find(3) ?? -1) + 1); }"
        ),
        "8\n0\n"
    );
}

// ── Integer Overflow ───────────────────────────────────────────

#[test]
fn test_integer_overflow_traps() {
    let errors = runtime_errors("fn main() { let x = 9223372036854775807 + 1; }");
    assert!(
        errors.iter().any(|e| e.message.contains("overflow")),
        "expected an overflow runtime error, got {:?}",
        errors
    );
}

#[test]
fn test_illtyped_binop_records_runtime_error_not_panic() {
    // B-2026-06-12-4: `String * Int` is a hard typecheck error, but `karac run`
    // executes despite typecheck errors (it demotes them to warnings). The
    // interpreter's binary-op fallthrough used to `unreachable!()`-panic on the
    // illegal operand that slipped through; it must now surface a graceful
    // runtime error instead. (Reaching this test at all — rather than aborting
    // the process — is the regression guard.)
    let errors = runtime_errors(r#"fn main() { let x = "ab" * 3; }"#);
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("not defined for operands")
                && e.message.contains("String")),
        "expected a graceful 'operator not defined' runtime error for String * Int, got {:?}",
        errors
    );
}

#[test]
fn test_illtyped_unary_records_runtime_error_not_panic() {
    // Sibling of the binop case (B-2026-06-12-4): unary `-` on a String is a
    // hard typecheck error; under `karac run` it reaches the interpreter, whose
    // unary fallthrough must record a runtime error rather than `unreachable!()`.
    let errors = runtime_errors(r#"fn main() { let x = -"ab"; }"#);
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("not defined for an operand")
                && e.message.contains("String")),
        "expected a graceful 'operator not defined' runtime error for -String, got {:?}",
        errors
    );
}

