// Unified drop+defer cleanup stack — design.md § Drop ordering within a branch.

#[test]
fn test_defer_registers_when_reached_not_at_block_start() {
    // The `defer` after the early `return` is never registered, so
    // its body must not fire. Pre-walk collection (the old bug)
    // would have run "late" anyway because the defer was hoisted to
    // block start.
    assert_eq!(
        run("fn early(go: bool) {\n\
                 print(\"a\");\n\
                 if go { return; }\n\
                 defer { print(\"late\"); }\n\
                 print(\"b\");\n\
             }\n\
             fn main() {\n\
                 early(true);\n\
                 print(\"|\");\n\
                 early(false);\n\
             }"),
        "a|ablate"
    );
}

#[test]
fn test_defer_runs_on_early_return() {
    // A defer registered before the early return must fire — the
    // pre-walk impl had a bug where the `?` in eval_stmt_cf
    // short-circuited past the cleanup drain.
    assert_eq!(
        run("fn body() {\n\
                 defer { print(\"d\"); }\n\
                 print(\"a\");\n\
                 return;\n\
                 print(\"unreached\");\n\
             }\n\
             fn main() { body(); }"),
        "ad"
    );
}

#[test]
fn test_errdefer_fires_on_err_return() {
    // Param-less errdefer fires on Err return; defer always fires.
    assert_eq!(
        run("fn body() -> Result[i64, String] {\n\
                 defer { print(\"d\"); }\n\
                 errdefer { print(\"e\"); }\n\
                 return Err(\"boom\");\n\
             }\n\
             fn main() { let _ = body(); }"),
        "ed"
    );
}

#[test]
fn test_errdefer_skipped_on_normal_return() {
    // errdefer must NOT fire on Ok; defer always fires.
    assert_eq!(
        run("fn body() -> Result[i64, String] {\n\
                 defer { print(\"d\"); }\n\
                 errdefer { print(\"e\"); }\n\
                 return Ok(1);\n\
             }\n\
             fn main() { let _ = body(); }"),
        "d"
    );
}

#[test]
fn test_errdefer_with_binding_sees_err_payload() {
    // errdefer(e) binds `e` to the Err payload during the errdefer phase.
    assert_eq!(
        run("fn body() -> Result[i64, String] {\n\
                 errdefer(e) { print(e); }\n\
                 return Err(\"oops\");\n\
             }\n\
             fn main() { let _ = body(); }"),
        "oops"
    );
}

#[test]
fn test_errdefer_runs_before_defer_on_error_path() {
    // Phase 1 (errdefer) drains LIFO, then phase 2 (drop+defer) drains LIFO.
    assert_eq!(
        run("fn body() -> Result[i64, String] {\n\
                 defer { print(\"d1\"); }\n\
                 errdefer { print(\"e1\"); }\n\
                 defer { print(\"d2\"); }\n\
                 errdefer { print(\"e2\"); }\n\
                 return Err(\"x\");\n\
             }\n\
             fn main() { let _ = body(); }"),
        "e2e1d2d1"
    );
}

#[test]
fn test_unified_stack_program_order_lifo() {
    // The drop+defer stack interleaves bindings and defers in
    // program order; LIFO drain means later items pop first.
    // Drop slots are no-ops today, but defer ordering relative to
    // them must respect program order. The test pins the defer-vs-defer
    // ordering across interleaved `let` statements.
    assert_eq!(
        run("fn main() {\n\
                 let _x = 1;\n\
                 defer { print(\"d1\"); }\n\
                 let _y = 2;\n\
                 defer { print(\"d2\"); }\n\
             }"),
        "d2d1"
    );
}

#[test]
fn test_par_cancellation_does_not_propagate_as_scope_error() {
    // Sub-step 4: a `par` sibling that observed cancel mid-execution
    // raises ControlFlow::Cancelled. `eval_par_block` must silence
    // that on the result side — the originating branch's real `Err`
    // is the scope's return value under fail-fast. Threading races
    // are tolerated by checking the OUTCOME (real Err propagates)
    // rather than asserting on whether observation actually fired.
    assert_eq!(
        run("fn attempt() -> Result[i64, String] {\n\
                 par {\n\
                     {\n\
                         let _a = 0;\n\
                         let _b = 0;\n\
                         let _c = 0;\n\
                         let _d = 0;\n\
                         let _e = 0;\n\
                         let _f = 0;\n\
                         let _g = 0;\n\
                         let _h = 0;\n\
                     }\n\
                     {\n\
                         return Err(\"r-fail\");\n\
                     }\n\
                 };\n\
                 Ok(0)\n\
             }\n\
             fn main() {\n\
                 match attempt() {\n\
                     Ok(_) => print(\"ok\"),\n\
                     Err(e) => print(e),\n\
                 }\n\
             }"),
        "r-fail"
    );
}

// ── Sub-step 3: NLL drop placement ─────────────────────────────

fn drops_in(source: &str) -> Vec<String> {
    let (_out, drops) = run_program_with_drops(source);
    drops
}

// ── Prereq.4 user-`impl Drop` dispatch — interpreter parity ──
//
// Mirrors codegen's Prereq.3 wiring: when a binding's `CleanupAction::Drop`
// drains at NLL endpoint OR scope exit, the user-defined `<Type>.drop`
// body fires before the trace records the name. Codegen invokes
// `karac_drop_<Type>` (which calls `<Type>.drop` then field cleanup);
// the interpreter directly invokes `<Type>.drop` from the drain.

#[test]
fn test_user_drop_body_fires_at_nll_endpoint() {
    // Foo's last use is `let n = f.x` (stmt 2). The user drop fires
    // at NLL endpoint — immediately after that statement, before the
    // subsequent println — so the output sequence is:
    //   stmt 1: println(0)          → "0\n"
    //   stmt 2: let n = f.x         → no output
    //           [NLL drop fires]    → "42\n"
    //   stmt 3: println(99)         → "99\n"
    let (output, drops) = run_program_with_drops(
        "struct Foo { x: i64 }\n\
         impl Drop for Foo {\n\
             fn drop(mut ref self) {\n\
                 println(self.x);\n\
             }\n\
         }\n\
         fn main() {\n\
             let f = Foo { x: 42 };\n\
             println(0);\n\
             let n = f.x;\n\
             println(99);\n\
         }",
    );
    assert_eq!(
        output,
        vec!["0\n".to_string(), "42\n".to_string(), "99\n".to_string()],
        "expected NLL drop ordering (println(0), drop body 42, println(99)); got {:?}",
        output
    );
    // drop_trace still records both bindings — the mechanism that
    // codegen / interpreter use to know WHEN a drop fires is
    // unchanged; Prereq.4 only adds the side effect of running the
    // user body at the same point. `n` drops too (also a binding
    // and `let _ = ...` would suppress; here we keep the binding so
    // both drops fire). Both are due at the same statement (`let n =
    // f.x` is f's last use AND n's declaration-with-no-later-use), so
    // they fire LIFO — `n` (introduced later) before `f` — per the
    // design.md § 867 single-stack rule (B-2026-07-21-1).
    assert_eq!(drops, vec!["n".to_string(), "f".to_string()]);
}

#[test]
fn test_user_drop_body_does_not_fire_when_no_impl_drop() {
    let (output, drops) = run_program_with_drops(
        "struct Foo { x: i64 }\n\
         fn main() {\n\
             let f = Foo { x: 42 };\n\
             println(0);\n\
         }",
    );
    // No `impl Drop` for Foo → no body to fire. Output contains only
    // main's explicit println. drop_trace still records "f" — the
    // NLL placement mechanism is independent of whether a user body
    // exists.
    assert_eq!(output, vec!["0\n".to_string()]);
    assert_eq!(drops, vec!["f".to_string()]);
}

#[test]
fn test_user_drop_body_can_read_struct_fields() {
    // Sanity-check that `self.field` access works inside the drop
    // body. `Foo.drop` reads two fields and prints their sum.
    let (output, _drops) = run_program_with_drops(
        "struct Foo { a: i64, b: i64 }\n\
         impl Drop for Foo {\n\
             fn drop(mut ref self) {\n\
                 println(self.a + self.b);\n\
             }\n\
         }\n\
         fn main() {\n\
             let f = Foo { a: 10, b: 32 };\n\
         }",
    );
    // f's NLL endpoint is right after `let f = ...` (no later use),
    // so the drop body fires immediately, printing 42 (=10+32).
    assert_eq!(output, vec!["42\n".to_string()]);
}

// ── B-2026-07-01-8 enum-Drop + fresh-temp-arg parity (interpreter) ──

#[test]
fn test_user_drop_fires_for_value_enum_binding() {
    // Pre-fix the interpreter NEVER ran a user `impl Drop` for a value
    // ENUM binding in any position (`drop_target` resolved only
    // Value::Struct) — `karac run` was silent where `karac build`
    // printed one drop per value. NLL endpoint: `s` is unused after the
    // let, so the body fires immediately after it.
    let (output, _drops) = run_program_with_drops(
        "enum Sig { A(i64), B }\n\
         impl Drop for Sig {\n\
             fn drop(mut ref self) {\n\
                 println(7);\n\
             }\n\
         }\n\
         fn main() {\n\
             let s = Sig.A(1);\n\
             println(0);\n\
         }",
    );
    assert_eq!(
        output,
        vec!["7\n".to_string(), "0\n".to_string()],
        "expected the enum binding's user drop body to fire (NLL: right after the unused let); got {:?}",
        output
    );
}

#[test]
fn test_user_drop_fires_for_fresh_temp_struct_arg() {
    // `consume(Guard { id: 7 })` — no caller binding, so no
    // CleanupAction::Drop existed; the user body never fired under the
    // interpreter (codegen fixed the same shape as B-2026-07-01-6). The
    // temp's drop runs right after the call returns.
    let (output, _drops) = run_program_with_drops(
        "struct Guard { id: i64 }\n\
         impl Drop for Guard {\n\
             fn drop(mut ref self) {\n\
                 println(self.id);\n\
             }\n\
         }\n\
         fn consume(g: Guard) {\n\
             println(0);\n\
         }\n\
         fn main() {\n\
             consume(Guard { id: 7 });\n\
             println(99);\n\
         }",
    );
    assert_eq!(
        output,
        vec!["0\n".to_string(), "7\n".to_string(), "99\n".to_string()],
        "expected the fresh struct temp arg's drop after the call; got {:?}",
        output
    );
}

#[test]
fn test_user_drop_fires_for_fresh_temp_enum_arg() {
    // The enum twin: tuple-variant ctor (`consume(Sig.A(1))`) and unit
    // variant (`consume(Sig.B)`) temps each fire once after their call.
    let (output, _drops) = run_program_with_drops(
        "enum Sig { A(i64), B }\n\
         impl Drop for Sig {\n\
             fn drop(mut ref self) {\n\
                 println(1);\n\
             }\n\
         }\n\
         fn consume(s: Sig) {\n\
             println(0);\n\
         }\n\
         fn main() {\n\
             consume(Sig.A(7));\n\
             consume(Sig.B);\n\
             println(99);\n\
         }",
    );
    assert_eq!(
        output,
        vec![
            "0\n".to_string(),
            "1\n".to_string(),
            "0\n".to_string(),
            "1\n".to_string(),
            "99\n".to_string()
        ],
        "expected one drop per fresh enum temp arg; got {:?}",
        output
    );
}

#[test]
fn test_user_drop_enum_move_fires_once() {
    // Move suppression parity for enums: a let-rebind (`let b = a;`) and
    // a tail return each transfer the drop obligation — exactly ONE body
    // firing per value (the suppressors previously matched only
    // Value::Struct, which would have double-fired once enum bindings
    // started dropping).
    let (output, _drops) = run_program_with_drops(
        "enum Sig { A(i64), B }\n\
         impl Drop for Sig {\n\
             fn drop(mut ref self) {\n\
                 println(1);\n\
             }\n\
         }\n\
         fn make() -> Sig {\n\
             let s = Sig.A(1);\n\
             s\n\
         }\n\
         fn main() {\n\
             let a = make();\n\
             let b = a;\n\
             println(0);\n\
         }",
    );
    let drop_count = output.iter().filter(|l| l.as_str() == "1\n").count();
    assert_eq!(
        drop_count, 1,
        "expected exactly one drop firing across tail-return + rebind moves; got {:?}",
        output
    );
}

// ── B-2026-07-01-3 narrow-element container arithmetic widths ──

#[test]
fn test_column_narrow_element_binop_overflow_traps() {
    // Pre-fix the interpreter evaluated `Column[i32] + 1` at i64 width and
    // silently produced 2147483648 where codegen trapped `integer
    // overflow` — `narrow_oob` now peels `Column[T]`/`Tensor[T, S]`
    // recorded types down to the element before the width check.
    let errors = runtime_errors(
        "fn main() {\n\
             let c: Column[i32] = Column.from_vec([2147483647]);\n\
             let d = c + 1;\n\
             match d[0] { Some(x) => { println(x); }, None => { println(0); } }\n\
         }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("integer overflow")),
        "expected the i32 element-width overflow trap; got {:?}",
        errors
    );
}

// ── Arrow IPC interchange (phase-11 Arrow IPC slice 1, interp MVP) ──
// `Column.to_arrow_ipc()` serializes to the Apache Arrow IPC stream format
// (spec-compliant bytes via arrow-rs); `Column.from_arrow_ipc(bytes)` parses
// them back. Round-trip preserves length, the null pattern, and values.
#[test]
fn test_column_arrow_ipc_roundtrip_i64() {
    let out = run_no_errors(
        "fn main() {\n\
             let mut c: Column[i64] = Column.new();\n\
             c.push(10); c.push(20); c.push_null(); c.push(40);\n\
             let bytes = c.to_arrow_ipc();\n\
             let d: Column[i64] = Column.from_arrow_ipc(bytes);\n\
             println(d.len());\n\
             println(d.null_count());\n\
             println(d.sum());\n\
         }",
    );
    // len 4, one null, sum of valid (10+20+40) = 70.
    assert_eq!(out, "4\n1\n70\n");
}

