// ── B-2026-06-30-15 value_compare Array arm (nested Vec sort) ──

#[test]
fn test_nested_vec_sort_orders_lexicographically() {
    // Pre-fix, two `Value::Array`s fell to value_compare's discriminant
    // fallback (always Equal), so `Vec[Vec[i64]].sort()` was a silent
    // NO-OP under the interpreter — probes just showed insertion order.
    let output = run_program(
        "fn main() {\n\
             let mut outer: Vec[Vec[i64]] = Vec.new();\n\
             outer.push(Vec[3, 1]);\n\
             outer.push(Vec[2]);\n\
             outer.push(Vec[2, 9]);\n\
             outer.sort();\n\
             let mut i = 0;\n\
             while i < outer.len() {\n\
                 println(outer[i][0]);\n\
                 println(outer[i].len());\n\
                 i = i + 1;\n\
             };\n\
         }",
    );
    assert_eq!(
        output,
        vec![
            "2\n".to_string(),
            "1\n".to_string(),
            "2\n".to_string(),
            "2\n".to_string(),
            "3\n".to_string(),
            "2\n".to_string()
        ],
        "expected ascending lexicographic order [2] < [2,9] < [3,1]; got {:?}",
        output
    );
}

// ── B-2026-07-03-6 value_compare Struct / EnumVariant arms ──

#[test]
fn test_struct_and_enum_ordering_no_dataloss_and_sorts() {
    // Pre-fix, two `Value::Struct` (or two `Value::EnumVariant`) fell to
    // value_compare's discriminant fallback (always Equal), so
    // `SortedSet[Struct]` / `SortedMap[Struct, _]` COLLAPSED distinct keys to
    // one (silent data loss) and `Vec[Struct].sort()` was a NO-OP. Verify the
    // count is preserved (no collapse) and the sort orders by fields.
    let output = run("#[derive(Eq, Ord)]\n\
         struct P { a: i64, b: i64 }\n\
         #[derive(Eq, Ord)]\n\
         enum E { Lo, Mid, Hi }\n\
         fn main() {\n\
             let mut ss: SortedSet[P] = SortedSet.new();\n\
             ss.insert(P { a: 2, b: 1 });\n\
             ss.insert(P { a: 1, b: 9 });\n\
             ss.insert(P { a: 1, b: 2 });\n\
             println(f\"{ss.len()}\");\n\
             println(f\"{ss.contains(P { a: 1, b: 9 })}\");\n\
             println(f\"{ss.contains(P { a: 5, b: 5 })}\");\n\
             let mut sm: SortedMap[P, i64] = SortedMap.new();\n\
             let _ = sm.insert(P { a: 1, b: 1 }, 10);\n\
             let _ = sm.insert(P { a: 2, b: 2 }, 20);\n\
             let _ = sm.insert(P { a: 3, b: 3 }, 30);\n\
             println(f\"{sm.len()}\");\n\
             let mut es: SortedSet[E] = SortedSet.new();\n\
             es.insert(E.Hi);\n\
             es.insert(E.Lo);\n\
             es.insert(E.Mid);\n\
             println(f\"{es.len()}\");\n\
             let mut v: Vec[P] = Vec.new();\n\
             v.push(P { a: 2, b: 0 });\n\
             v.push(P { a: 1, b: 9 });\n\
             v.push(P { a: 1, b: 2 });\n\
             v.sort();\n\
             let mut i = 0;\n\
             while i < v.len() { let p = v[i]; println(f\"{p.a},{p.b}\"); i = i + 1; };\n\
         }");
    // SortedSet len 3 (no collapse), membership correct; SortedMap len 3;
    // enum SortedSet len 3; Vec sorted by (a, b): (1,2) (1,9) (2,0).
    assert_eq!(output, "3\ntrue\nfalse\n3\n3\n1,2\n1,9\n2,0\n");
}

// ── B-2026-07-03-12: derived-Ord DECLARATION order, not alphabetical ──

#[test]
fn test_struct_enum_ordering_is_declaration_order_not_alphabetical() {
    // B-2026-07-03-6 fixed the data loss but ordered struct fields / enum
    // variants ALPHABETICALLY. This locks the derived-`Ord` DECLARATION order
    // recovered from the per-thread `type_order` registry:
    //   - struct `Rect { width, height }` sorts by `width` FIRST — alphabetical
    //     would compare `height` first and flip the two rows.
    //   - enum `Priority { Low, Med, High }` sorts `Low < Med < High` — the
    //     "more visible" case: alphabetical would give `High < Low < Med`.
    // Both the `Vec.sort()` path (value_compare direct) and the SortedSet
    // path (OrdValue::cmp deep inside BTreeMap, no interpreter handle) must
    // agree, so the test exercises both.
    let output = run_no_errors(
        "#[derive(Eq, Ord)]\n\
         struct Rect { width: i64, height: i64 }\n\
         #[derive(Eq, Ord)]\n\
         enum Priority { Low, Med, High }\n\
         fn rank(p: Priority) -> i64 {\n\
             match p { Priority.Low => 0, Priority.Med => 1, Priority.High => 2 }\n\
         }\n\
         fn main() {\n\
             let mut v: Vec[Rect] = Vec.new();\n\
             v.push(Rect { width: 2, height: 1 });\n\
             v.push(Rect { width: 1, height: 9 });\n\
             v.sort();\n\
             let mut i = 0;\n\
             while i < v.len() { let r = v[i]; println(f\"{r.width},{r.height}\"); i = i + 1; };\n\
             let mut ss: SortedSet[Priority] = SortedSet.new();\n\
             ss.insert(Priority.High);\n\
             ss.insert(Priority.Low);\n\
             ss.insert(Priority.Med);\n\
             for p in ss { println(f\"{rank(p)}\"); };\n\
         }",
    );
    // Struct sorted by width (declaration order): (1,9) then (2,1).
    // Enum SortedSet iterates in declaration order: Low(0) Med(1) High(2).
    assert_eq!(output, "1,9\n2,1\n0\n1\n2\n");
}

// ── B-2026-07-03-7: `<` `<=` `>` `>=` on derived-Ord struct/enum ──

#[test]
fn test_ordered_operators_on_derived_ord_struct_and_enum() {
    // Pre-fix these operators were a hard type error on struct/enum operands
    // (no interp/codegen lowering). Now they lower through `value_compare`
    // (declaration order), so `karac run` and `karac build` agree.
    let output = run_no_errors(
        "#[derive(Eq, Ord)]\n\
         struct P { a: i64, b: i64 }\n\
         #[derive(Eq, Ord)]\n\
         enum Pri { Low, Med, High }\n\
         fn main() {\n\
             let x = P { a: 1, b: 2 };\n\
             let y = P { a: 1, b: 3 };\n\
             println(f\"{x < y}\");\n\
             println(f\"{y > x}\");\n\
             println(f\"{x <= x}\");\n\
             println(f\"{y < x}\");\n\
             println(f\"{Pri.Low < Pri.High}\");\n\
             println(f\"{Pri.High < Pri.Low}\");\n\
         }",
    );
    // a==a so P compares by b: 2<3; Low(0)<High(2).
    assert_eq!(output, "true\ntrue\ntrue\nfalse\ntrue\nfalse\n");
}

// ── B-2026-07-01-7 fn-returned Drop temps + passthrough guard ──

#[test]
fn test_user_drop_fires_for_fn_returned_temp_arg_and_discard() {
    // `consume(make())` (fn-returned temp arg) and a bare `make();`
    // (discarded statement position) each fire the user body exactly
    // once; a `mint(ctor)` whose callee returns a FRESH value keeps BOTH
    // drops (arg temp + result binding) — the passthrough guard is
    // per-callee syntactic analysis, not type-based.
    let (output, _drops) = run_program_with_drops(
        "struct Guard { id: i64 }\n\
         impl Drop for Guard {\n\
             fn drop(mut ref self) {\n\
                 println(self.id);\n\
             }\n\
         }\n\
         fn make() -> Guard { Guard { id: 7 } }\n\
         fn consume(g: Guard) { println(100); }\n\
         fn mint(g: Guard) -> Guard { Guard { id: g.id + 1 } }\n\
         fn main() {\n\
             consume(make());\n\
             make();\n\
             let x = mint(Guard { id: 20 });\n\
             println(x.id);\n\
         }",
    );
    assert_eq!(
        output,
        vec![
            "100\n".to_string(),
            "7\n".to_string(),
            "7\n".to_string(),
            "20\n".to_string(),
            "21\n".to_string(),
            "21\n".to_string()
        ],
        "expected consume-arg fire, discard fire, mint arg+result fires; got {:?}",
        output
    );
}

#[test]
fn test_user_drop_passthrough_arg_fires_once() {
    // `let x = pass(Guard { id: 7 })` where `pass` returns its param —
    // the arg-temp registration is SKIPPED (fn_returns_param guard) and
    // only x's binding drop fires. Pre-guard this double-fired.
    let (output, _drops) = run_program_with_drops(
        "struct Guard { id: i64 }\n\
         impl Drop for Guard {\n\
             fn drop(mut ref self) {\n\
                 println(self.id);\n\
             }\n\
         }\n\
         fn pass(g: Guard) -> Guard { g }\n\
         fn main() {\n\
             let x = pass(Guard { id: 7 });\n\
             println(x.id);\n\
         }",
    );
    let fires = output.iter().filter(|l| l.as_str() == "7\n").count();
    // x.id prints one "7"; exactly one MORE from the single drop.
    assert_eq!(
        fires, 2,
        "expected exactly one drop firing for the passed-through value; got {:?}",
        output
    );
}

// ── phase-7 L938 user-`impl Drop` for SHARED structs (interpreter) ──
//
// A `shared struct` is `Value::SharedStruct(Arc<…>)`; the user body
// fires when the LAST live reference drops (Arc strong-count → 1 at the
// drain point), mirroring codegen's refcount→0. `drop_target` peeks the
// count without cloning so the test is exact.

#[test]
fn test_shared_struct_structural_equality() {
    // `shared struct` `==`/`!=` is structural (design.md § Equality Semantics):
    // it compares the inner fields, not Arc identity. Two separately-built P's
    // with equal fields are ==; differing a field makes them !=.
    let out = run("#[derive(Eq, PartialEq)]\n\
         shared struct P { x: i64, y: i64 }\n\
         fn main() {\n\
             let a = P { x: 1, y: 2 };\n\
             let b = P { x: 1, y: 2 };\n\
             let c = P { x: 9, y: 2 };\n\
             if a == b { println(\"eq\"); }\n\
             if a != c { println(\"ne\"); }\n\
         }");
    assert_eq!(out, "eq\nne\n");
}

#[test]
fn test_ref_eq_shared_struct_identity() {
    // `ref_eq` is REFERENCE identity (design.md § Equality Semantics): true iff
    // two shared handles point at the same allocation. `b = a` aliases the Arc
    // (true); a separately-built `c` with equal fields is a distinct alloc
    // (false) even though `==` would call it structurally equal. Parity with
    // codegen::test_e2e_ref_eq_shared_identity.
    let out = run("shared struct N { v: i64 }\n\
         fn main() {\n\
             let a = N { v: 1 };\n\
             let b = a;\n\
             let c = N { v: 1 };\n\
             println(ref_eq(a, b));\n\
             println(ref_eq(a, c));\n\
         }");
    assert_eq!(out, "true\nfalse\n");
}

#[test]
fn test_ref_eq_non_shared_is_type_error() {
    fn errs(src: &str) -> Vec<String> {
        let parsed = karac::parse(src);
        let resolved = karac::resolve(&parsed.program);
        let typed = karac::typecheck(&parsed.program, &resolved);
        typed.errors.iter().map(|e| e.message.clone()).collect()
    }
    // Owned struct / primitive: reference identity is not meaningful — error,
    // pointing at `==`.
    assert!(errs("struct P { v: i64 }\nfn main() { let a = P { v: 1 }; let b = P { v: 1 }; println(ref_eq(a, b)); }")
        .iter()
        .any(|e| e.contains("not a `shared` type")));
    assert!(errs("fn main() { println(ref_eq(1, 2)); }")
        .iter()
        .any(|e| e.contains("not a `shared` type")));
}

#[test]
fn test_user_drop_shared_struct_fires_once() {
    let (output, _drops) = run_program_with_drops(
        "shared struct Res { id: i64 }\n\
         impl Drop for Res {\n\
             fn drop(mut ref self) {\n\
                 println(self.id);\n\
             }\n\
         }\n\
         fn main() {\n\
             let r = Res { id: 7 };\n\
         }",
    );
    // Sole reference, no later use → fires once, reading self.id.
    assert_eq!(output, vec!["7\n".to_string()]);
}

#[test]
fn test_user_drop_shared_struct_alias_fires_once_at_last_ref() {
    // phase-7 L940: `let r2 = r` is an Arc clone — two holders of one
    // inner. The body must fire EXACTLY once, when the last holder's slot
    // drains (env-release-on-drain decrements the strong-count as each
    // holder drains, so the final one reaches 1). Output is the read
    // `println(r2.id)` ("7") plus exactly one drop-body "7"; a third "7"
    // would be a double-drop, zero extra would be the pre-L940 under-fire.
    let (output, _drops) = run_program_with_drops(
        "shared struct Res { id: i64 }\n\
         impl Drop for Res {\n\
             fn drop(mut ref self) {\n\
                 println(self.id);\n\
             }\n\
         }\n\
         fn main() {\n\
             let r = Res { id: 7 };\n\
             let r2 = r;\n\
             println(r2.id);\n\
         }",
    );
    let fires = output.iter().filter(|l| l.trim() == "7").count();
    assert_eq!(
        fires, 2,
        "expected the read (one `7`) + exactly one drop-body `7`; got {output:?}"
    );
}

// NOTE: recursive / field-held shared structs (`Node { next: Some(child) }`)
// still do NOT fire the user body on the interpreter path — an inner ref
// held inside another shared struct's field is never an env binding, so it
// never reaches a `CleanupAction::Drop` drain and env-release-on-drain
// can't see it. Closing that needs an Arc-drop hook (a `SharedStructInner`
// Drop impl that calls back into the interpreter). Codegen fires these
// correctly (refcount→0; see the recursive-chain codegen + ASAN tests).
// Tracked under the phase-7 "Drop ordering reconciliation across backends"
// item (L940), recursive sub-item.

// ── Move-suppression for user-Drop bindings (let-rebind) ──
//
// `let g = f;` where `f` has a user `impl Drop` moves the value
// into `g`. Without move-suppression both bindings' Drop actions
// would fire at scope exit, calling the user body twice on what is
// logically the same value (double-close fds, etc.). The interpreter
// helper `suppress_let_rebind_user_drop` removes the source's
// CleanupAction::Drop from the current cleanup frame before
// `push_drops_for_stmt` pushes the destination's. Non-user-Drop
// bindings still get their drop_trace records (the suppression is
// gated on `program.drop_method_keys`).

#[test]
fn test_user_drop_move_suppression_let_rebind() {
    let (output, drops) = run_program_with_drops(
        "struct R { tag: i64 }\n\
         impl Drop for R {\n\
             fn drop(mut ref self) { println(self.tag); }\n\
         }\n\
         fn main() {\n\
             let f = R { tag: 7 };\n\
             let g = f;\n\
             println(g.tag);\n\
         }",
    );
    // The user body should fire exactly ONCE — for `g`, not also for
    // `f`. Output sequence:
    //   stmt 0: let f = R { tag: 7 }  → no output, but the `value`
    //           expression is a struct literal so the user body
    //           would normally fire at f's NLL endpoint (which is
    //           THIS statement under interpreter NLL semantics)
    //           UNLESS move-suppression catches the next-stmt
    //           move-out first. Today the suppression runs at the
    //           NEXT statement's let-binding, AFTER `f`'s push +
    //           fire — so `f`'s drop body actually fires here.
    //           Documenting the observed behavior: this works for
    //           let-rebind only when `f` is used AFTER let-binding
    //           OR when the source binding's NLL endpoint is the
    //           statement that moves it.
    //   stmt 1: let g = f → before pushing g's Drop, suppress
    //           f's. But f's was already pushed AND fired at NLL
    //           endpoint of stmt 0. So suppression here is a no-op
    //           when the source already fired.
    //
    // To get the move-suppression to actually suppress, `f` must
    // still have its Drop slot in the cleanup vec when stmt 1 runs.
    // That requires `f` to be live past stmt 0 — which it IS,
    // because stmt 1 USES `f`. So `f`'s NLL endpoint is stmt 1, not
    // stmt 0. Drop slot survives stmt 0's fire_due_drops; at the
    // start of stmt 1's let-binding processing, suppress runs and
    // removes f's slot; then g's slot is pushed; then
    // fire_due_drops fires anything whose NLL endpoint is stmt 1
    // — but f's slot is gone, and g's last-use is later (stmt 2),
    // so neither fires here. At stmt 2's NLL endpoint, g fires.
    //
    // Expected: println(g.tag) → "7\n" then g's drop → "7\n".
    // f's drop body is suppressed — never appears.
    assert_eq!(
        output,
        vec!["7\n".to_string(), "7\n".to_string()],
        "expected one println(g.tag) + one g.drop (NOT also f.drop); got {:?}",
        output
    );
    // drop_trace records only `g` — `f`'s Drop slot was removed by
    // suppression before fire_due_drops could push the trace.
    assert_eq!(
        drops,
        vec!["g".to_string()],
        "expected drop_trace to contain only `g` (source `f` move-suppressed); got {:?}",
        drops
    );
}

// B-2026-07-29-38: an AGGREGATE-LITERAL field initializer is a move position
// too — `ownership_oracle`'s `Role::Move` set lists "aggregate-literal field"
// alongside the direct rebind, and the ownership checker already reports
// `value 'r' moved here` for it. Only the bare-rebind arm was suppressed, so
// `let h = Holder { r: r };` left `r`'s Drop slot in place and the NLL last-use
// placement fired it AT THE MOVE.
//
// That is a soundness bug, not a cosmetic one: `TcpListener` / `TcpStream` /
// `WebSocket` carry a synthesized `impl Drop` calling
// `karac_runtime_tcp_close(self.fd)`, so moving a listener into a struct field
// CLOSED ITS FD before the listener was used — the cause of the
// `coro_e2e::coroutine_method_handler_services_connection` hang (the port was
// printed, then nothing was listening).
#[test]
fn test_user_drop_no_premature_fire_when_moved_into_struct_literal() {
    let (output, _drops) = run_program_with_drops(
        "struct R { tag: i64 }\n\
         impl Drop for R {\n\
             fn drop(mut ref self) { println(99); }\n\
         }\n\
         struct Holder { r: R }\n\
         fn main() {\n\
             let r = R { tag: 7 };\n\
             let h = Holder { r: r };\n\
             println(h.r.tag);\n\
             println(40);\n\
         }",
    );
    // The move must NOT drop `r`. Before the fix the first line was "99\n" —
    // the drop firing at the move, ahead of any field read.
    assert!(
        !output.is_empty() && output[0] == "7\n",
        "the struct-literal move must not fire `r`'s drop before the field is \
         read; got {output:?}"
    );
    assert!(
        !output.contains(&"99\n".to_string())
            || output.iter().position(|l| l == "99\n").unwrap() > 0,
        "`r`'s drop must not precede the field read; got {output:?}"
    );
}

#[test]
fn test_user_drop_move_suppression_does_not_affect_non_drop_types() {
    // Plain `let y = x;` for a non-struct value (no user Drop) keeps
    // the existing drop_trace behaviour — both `x` and `y` get
    // recorded. Move-suppression is gated on `drop_method_keys`
    // containing the source's type, which is empty for primitives.
    let (_output, drops) = run_program_with_drops(
        "fn main() {\n\
             let x = 1;\n\
             let y = x;\n\
             println(y);\n\
         }",
    );
    // Both x and y appear in drop_trace per the existing NLL placement
    // (x's last use is `let y = x`, so it fires after stmt 1; y's
    // last use is println, fires after stmt 2).
    assert_eq!(
        drops,
        vec!["x".to_string(), "y".to_string()],
        "non-Drop bindings should still get drop_trace records; got {:?}",
        drops
    );
}

// ── Move-suppression for return-by-value of user-Drop bindings ──
//
// `fn make() -> T { let l = T::new(); l }` — `l`'s value moves out
// as the function's return value. The interpreter's
// `suppress_tail_expr_user_drop` (called before evaluating
// `block.final_expr`) removes `l`'s Drop slot from cleanup so its
// user-body doesn't fire when the function's `run_cleanup` runs;
// the caller fires its drop on the same logical value at its own
// scope exit. The companion `suppress_return_stmt_user_drop`
// handles explicit `return expr;` statements.

#[test]
fn test_user_drop_return_by_value_trailing_expression() {
    let (output, drops) = run_program_with_drops(
        "struct R { tag: i64 }\n\
         impl Drop for R {\n\
             fn drop(mut ref self) { println(self.tag); }\n\
         }\n\
         fn make() -> R {\n\
             let l = R { tag: 7 };\n\
             l\n\
         }\n\
         fn main() {\n\
             let r = make();\n\
             println(r.tag);\n\
         }",
    );
    // The user body fires EXACTLY ONCE — when `r` drops in `main`'s
    // scope exit. Not also in `make` (where `l` would otherwise fire
    // before returning, dropping the value the caller is about to
    // receive). Expected output:
    //   println(r.tag) → "7\n"
    //   r's user drop body → "7\n"
    // If the suppression were broken, we'd see "7\n", "7\n", "7\n"
    // (the suppressed-but-still-firing `l.drop` in `make` would add
    // an extra 7).
    assert_eq!(
        output,
        vec!["7\n".to_string(), "7\n".to_string()],
        "expected exactly two `7\\n` lines (println + one drop); got {:?}",
        output
    );
    // drop_trace shows only `r` — `l` was suppressed in `make`'s
    // cleanup (so its trace push never happened).
    assert_eq!(
        drops,
        vec!["r".to_string()],
        "expected drop_trace to contain only `r` (l move-suppressed in make); got {:?}",
        drops
    );
}

#[test]
fn test_user_drop_return_by_value_explicit_return() {
    let (output, drops) = run_program_with_drops(
        "struct R { tag: i64 }\n\
         impl Drop for R {\n\
             fn drop(mut ref self) { println(self.tag); }\n\
         }\n\
         fn make() -> R {\n\
             let l = R { tag: 7 };\n\
             return l;\n\
         }\n\
         fn main() {\n\
             let r = make();\n\
             println(r.tag);\n\
         }",
    );
    // Same expectation as the trailing-expression case — explicit
    // `return l;` is handled by `suppress_return_stmt_user_drop`.
    assert_eq!(
        output,
        vec!["7\n".to_string(), "7\n".to_string()],
        "explicit return: expected exactly two `7\\n` lines; got {:?}",
        output
    );
    assert_eq!(
        drops,
        vec!["r".to_string()],
        "explicit return: expected drop_trace [\"r\"]; got {:?}",
        drops
    );
}

// ── Prereq.5 user-`impl Drop` dispatch — edge cases ──
//
// Multiple-binding ordering, Drop / defer interleave, and the documented
// gaps that remain (move-suppression, RC integration, recursive drop-glue
// — see phase-7-codegen.md for follow-on tracker entries).

#[test]
fn test_user_drop_lifo_at_scope_exit_when_both_used_to_last_stmt() {
    // Both bindings are used at the last statement, so neither has
    // an NLL endpoint before scope exit; both drain at scope exit
    // via run_cleanup, which iterates cleanup-stack actions LIFO
    // (`cleanup.iter().rev()` at eval_stmt.rs). Last-declared
    // (B) drops first, then A.
    let (output, drops) = run_program_with_drops(
        "struct A { tag: i64 }\n\
         struct B { tag: i64 }\n\
         impl Drop for A {\n\
             fn drop(mut ref self) { println(self.tag); }\n\
         }\n\
         impl Drop for B {\n\
             fn drop(mut ref self) { println(self.tag); }\n\
         }\n\
         fn main() {\n\
             let a = A { tag: 1 };\n\
             let b = B { tag: 2 };\n\
             println(a.tag + b.tag);\n\
         }",
    );
    // Both a and b have last-use at stmt 2 (the println), so both fire
    // at that NLL endpoint — in LIFO (reverse-introduction) order per
    // the design.md § 867 single-stack rule: b (declared second) drops
    // first, then a. This is the B-2026-07-21-1 reconciliation: the
    // interpreter's fire_due_drops now walks back-to-front, and
    // codegen's `fire_due_user_drops` emits the identical order (the
    // old front-to-back FIFO here, and codegen's old scope-exit-only
    // drain, were the two halves of the divergence).
    assert_eq!(
        output,
        vec!["3\n".to_string(), "2\n".to_string(), "1\n".to_string()],
        "expected sum-print then both user-drop bodies (b then a, same-statement LIFO); got {:?}",
        output
    );
    // drop_trace records both bindings in the order they fired.
    assert_eq!(
        drops,
        vec!["b".to_string(), "a".to_string()],
        "drop_trace should record both bindings in LIFO fire order"
    );
}

#[test]
fn test_user_drop_interleaves_with_defer_at_scope_exit() {
    // Defer block and user-Drop binding share the same cleanup
    // stack; LIFO drain at scope exit interleaves them by
    // declaration order. The defer (declared after the binding)
    // runs before the binding's drop.
    let (output, _drops) = run_program_with_drops(
        "struct R { tag: i64 }\n\
         impl Drop for R {\n\
             fn drop(mut ref self) { println(self.tag); }\n\
         }\n\
         fn main() {\n\
             let r = R { tag: 7 };\n\
             defer { println(99); }\n\
             println(r.tag);\n\
         }",
    );
    // Sequence:
    //   stmt 0: bind r
    //   stmt 1: defer { println(99) }
    //   stmt 2: println(r.tag) → \"7\\n\". r's last use is stmt 2.
    //   NLL drop of r fires after stmt 2 → \"7\\n\" (from drop body).
    //   Scope exit: defer fires → \"99\\n\".
    //
    // The user-Drop runs at NLL endpoint (before defer at scope
    // exit) because of NLL placement. To get LIFO defer-then-drop
    // ordering, r would need to be live through scope exit. The
    // observed order pins NLL semantics' effect on user-Drop.
    assert_eq!(
        output,
        vec!["7\n".to_string(), "7\n".to_string(), "99\n".to_string()],
        "expected println(r.tag), drop body 7, defer 99 in that order; got {:?}",
        output
    );
}

#[test]
fn test_nll_drop_fires_after_last_use_not_at_scope_exit() {
    // Per design.md § Drop ordering within a branch: NLL drops fire
    // at the binding's last-use program point, not at scope exit.
    // `x` is read on line 3; subsequent statements never reference it.
    // Drop(x) must fire after stmt 3, before the later prints — and
    // before Drop(y) which dies later.
    let drops = drops_in(
        "fn main() {\n\
             let x = 1;\n\
             let y = 2;\n\
             println(x);\n\
             println(y);\n\
             println(99);\n\
         }",
    );
    assert_eq!(drops, vec!["x", "y"]);
}

#[test]
fn test_nll_drop_orders_by_last_use_not_declaration_order() {
    // Declaration order: a, b, c. Last-use order: c (idx 1), a (idx 2),
    // b (idx 3). Drops fire in last-use order, NOT declaration LIFO.
    let drops = drops_in(
        "fn main() {\n\
             let a = 1;\n\
             let b = 2;\n\
             let c = 3;\n\
             println(c);\n\
             println(a);\n\
             println(b);\n\
         }",
    );
    assert_eq!(drops, vec!["c", "a", "b"]);
}

#[test]
fn test_nll_unread_binding_drops_at_its_let() {
    // A binding never read after its declaration drops immediately
    // (last_use == its own let-stmt index). Subsequent let-and-drop
    // chains the same way.
    let drops = drops_in(
        "fn main() {\n\
             let _a = 1;\n\
             let _b = 2;\n\
             let _c = 3;\n\
         }",
    );
    assert_eq!(drops, vec!["_a", "_b", "_c"]);
}

#[test]
fn test_nll_binding_used_in_final_expr_drops_at_scope_exit() {
    // A binding referenced by `final_expr` stays live until the
    // expression evaluates; its Drop drains via the unified LIFO at
    // scope exit (sentinel: `last_use == stmts.len()`).
    let drops = drops_in(
        "fn main() {\n\
             let result = {\n\
                 let x = 7;\n\
                 x + 1\n\
             };\n\
             println(result);\n\
         }",
    );
    // `x` drops at the inner block's scope exit; `result` is the
    // outer-block binding and drops at outer scope exit. Both reach
    // the LIFO drain because they're referenced after the let.
    assert_eq!(drops, vec!["x", "result"]);
}

#[test]
fn test_nll_defer_referencing_binding_extends_live_range() {
    // Per design.md § Drop ordering within a branch: a defer body
    // that references a binding extends the binding's live range to
    // scope exit. The defer fires first under LIFO, with the binding
    // still alive; Drop fires after.
    let drops = drops_in(
        "fn main() {\n\
             let x = 7;\n\
             defer { println(x); }\n\
             println(\"middle\");\n\
         }",
    );
    // `x` is referenced in the defer body, so its last_use is the
    // sentinel. Drop(x) drains at scope exit, after the defer body.
    assert_eq!(drops, vec!["x"]);
}

#[test]
fn test_nll_drop_ordering_with_defer_interleave() {
    // Bindings whose direct last-use is mid-block fire NLL early,
    // *before* any defer (registered later) drains at scope exit.
    // The unified LIFO ordering only kicks in for slots still in
    // `cleanup` at scope exit.
    let drops = drops_in(
        "fn main() {\n\
             let a = 1;\n\
             println(a);\n\
             defer { println(\"d\"); }\n\
             let b = 2;\n\
             println(b);\n\
         }",
    );
    // a's last use is stmt 1 → fires NLL after println(a).
    // b's last use is stmt 4 → fires NLL after println(b).
    // The defer body still drains at scope exit; it carries no
    // binding-name that would land on drop_trace.
    assert_eq!(drops, vec!["a", "b"]);
}

// ── Shared struct interior mutability ───────────────────────────

#[test]
fn test_shared_struct_aliasing_propagates_mutation() {
    // Per design.md § Part 5: Shared Types — `shared struct` values
    // have reference semantics. `let b = a` clones the Arc; mutations
    // through `b.field` are visible at `a.field` because both bindings
    // point to the same allocation.
    assert_eq!(
        run("shared struct Counter { mut value: i64 }\n\
             fn main() {\n\
                 let a = Counter { value: 1 };\n\
                 let b = a;\n\
                 b.value = 42;\n\
                 println(a.value);\n\
             }"),
        "42\n"
    );
}

#[test]
fn test_shared_struct_field_write_through_struct_field_projection() {
    // Regression (Tangle dogfooding, undo/redo): a `shared struct` reached
    // through a *plain struct field* projection (`holder.cell.value = x`) must
    // write through the shared Arc. `set_field` previously bailed for any
    // receiver that was not a bare identifier / `self`, silently dropping the
    // write — undo/redo over shared state read stale values.
    assert_eq!(
        run("shared struct Cell { mut value: i64 }\n\
             struct Holder { cell: Cell }\n\
             fn main() {\n\
                 let c = Cell { value: 1 };\n\
                 let h = Holder { cell: c };\n\
                 h.cell.value = 99;\n\
                 println(c.value);\n\
             }"),
        "99\n"
    );
}

#[test]
fn test_shared_struct_field_write_through_index_projection() {
    // Same regression via a *container element* projection (`v[0].value = x`):
    // the Vec element is a clone of the same Arc, so the write is visible at
    // the original handle.
    assert_eq!(
        run("shared struct Cell { mut value: i64 }\n\
             fn main() {\n\
                 let c = Cell { value: 1 };\n\
                 let mut v = Vec.new();\n\
                 v.push(c);\n\
                 v[0].value = 42;\n\
                 println(c.value);\n\
             }"),
        "42\n"
    );
}

#[test]
fn test_plain_nested_struct_field_write() {
    // Regression: assigning to a *plain* (value-type) struct field through a
    // projection (`o.inner.x = v`, depth >= 2) was silently dropped — the
    // statement dispatch and `set_field` only handled bare-identifier targets,
    // so the write no-op'd. Now the parent copy is updated and written back up
    // the place chain. (Pre-existing; surfaced by Tangle dogfooding.)
    assert_eq!(
        run("struct Inner { x: i64 }\n\
             struct Outer { inner: Inner }\n\
             fn main() {\n\
                 let mut o = Outer { inner: Inner { x: 1 } };\n\
                 o.inner.x = 99;\n\
                 println(o.inner.x);\n\
             }"),
        "99\n"
    );
}

#[test]
fn test_plain_nested_struct_field_write_three_levels() {
    // Write-back composes to arbitrary depth.
    assert_eq!(
        run("struct A { x: i64 }\n\
             struct B { a: A }\n\
             struct C { b: B }\n\
             fn main() {\n\
                 let mut c = C { b: B { a: A { x: 1 } } };\n\
                 c.b.a.x = 42;\n\
                 println(c.b.a.x);\n\
             }"),
        "42\n"
    );
}

#[test]
fn test_plain_struct_field_write_through_vec_element() {
    // `v[i].field = x` on plain-struct elements: update the element copy and
    // write it back into the Vec's shared storage; siblings untouched.
    assert_eq!(
        run("struct Item { v: i64 }\n\
             fn main() {\n\
                 let mut items = Vec.new();\n\
                 items.push(Item { v: 10 });\n\
                 items.push(Item { v: 20 });\n\
                 items[1].v = 99;\n\
                 println(items[0].v);\n\
                 println(items[1].v);\n\
             }"),
        "10\n99\n"
    );
}

#[test]
fn test_compound_assign_on_field_and_nested() {
    // Compound assignment (`+=`) previously only handled bare-identifier
    // targets; field and nested-field targets were silently dropped. Now it
    // routes through the same place-assignment path.
    assert_eq!(
        run("struct Inner { x: i64 }\n\
             struct Outer { mut count: i64, inner: Inner }\n\
             fn main() {\n\
                 let mut o = Outer { count: 0, inner: Inner { x: 5 } };\n\
                 o.count += 10;\n\
                 o.inner.x += 100;\n\
                 println(o.count);\n\
                 println(o.inner.x);\n\
             }"),
        "10\n105\n"
    );
}

#[test]
fn test_shared_struct_per_field_independence() {
    // Per design.md § Part 5: \"mutating `node.left` does not conflict
    // with reading `node.right`\". Per-field tracking is the entire
    // point of the spec choosing per-field over struct-wide.
    assert_eq!(
        run("shared struct Node { mut left: i64, mut right: i64 }\n\
             fn main() {\n\
                 let n = Node { left: 1, right: 2 };\n\
                 n.left = 10;\n\
                 println(n.left + n.right);\n\
             }"),
        "12\n"
    );
}

#[test]
fn test_shared_struct_immutable_field_persists() {
    // An immutable field set at construction is visible across all
    // holders and is never mutated afterwards.
    assert_eq!(
        run("shared struct Node { id: i64, mut value: i64 }\n\
             fn main() {\n\
                 let n = Node { id: 7, value: 0 };\n\
                 let m = n;\n\
                 m.value = 99;\n\
                 println(n.id);\n\
                 println(m.value);\n\
             }"),
        "7\n99\n"
    );
}

#[test]
fn test_shared_struct_mutation_through_method() {
    // Method dispatch on `shared struct` binds `self` to a SharedStruct
    // value (Arc clone). `self.field = x` inside the method writes
    // through the shared allocation.
    assert_eq!(
        run("shared struct Counter { mut value: i64 }\n\
             impl Counter {\n\
                 fn bump(ref self) { self.value = self.value + 1; }\n\
             }\n\
             fn main() {\n\
                 let c = Counter { value: 0 };\n\
                 c.bump();\n\
                 c.bump();\n\
                 c.bump();\n\
                 println(c.value);\n\
             }"),
        "3\n"
    );
}

#[test]
fn test_shared_struct_aliased_through_method_argument() {
    // Passing a `shared struct` to a function that mutates through it
    // is visible at the caller — same Arc allocation.
    assert_eq!(
        run("shared struct Box { mut value: i64 }\n\
             fn bump(b: ref Box) { b.value = b.value + 100; }\n\
             fn main() {\n\
                 let x = Box { value: 5 };\n\
                 bump(x);\n\
                 bump(x);\n\
                 println(x.value);\n\
             }"),
        "205\n"
    );
}

#[test]
fn test_shared_struct_per_field_independence_across_methods() {
    // Pins the canonical spec example from design.md:8186 —
    // \"mutating `node.left` does not conflict with reading `node.right`\".
    // Independent methods touching different fields never see a
    // borrow-conflict panic.
    assert_eq!(
        run("shared struct Node { mut left: i64, mut right: i64 }\n\
             impl Node {\n\
                 fn write_left(ref self, x: i64) { self.left = x; }\n\
                 fn read_right(ref self) -> i64 { self.right }\n\
             }\n\
             fn main() {\n\
                 let n = Node { left: 0, right: 7 };\n\
                 n.write_left(99);\n\
                 println(n.read_right());\n\
                 println(n.left);\n\
             }"),
        "7\n99\n"
    );
}

// ── Weak references on shared struct fields ────────────────────

#[test]
fn test_weak_container_element_upgrades_like_a_weak_field() {
    // B-2026-08-08-14 — the interpreter modelled `weak` per struct FIELD
    // (dedicated maps on `SharedStructInner`, upgraded at the field-read site)
    // and had no home for a weak CONTAINER element, so a `Vec[weak T]` push
    // stored an ordinary STRONG handle. Two consequences: a cycle through the
    // container was uncollectable here, and the element read handed a bare
    // struct to a `match` expecting `Option[T]` — reported as "non-exhaustive
    // match ... the typechecker should have rejected this", which blamed the
    // wrong phase for a gap that was the interpreter's own.
    //
    // Both rows must agree with codegen, which is what
    // `test_e2e_vec_of_weak_read_back_upgrades_and_leaves_the_target_intact`
    // pins on the other side. The second row is the one that makes it a WEAK
    // ref rather than an awkward strong one: the target dies with the helper's
    // frame, so the read must report `None`.
    assert_eq!(
        run("shared struct N { mut v: i64 }\n             fn main() {\n                 let a: N = N { v: 41i64 };\n                 let mut w: Vec[weak N] = Vec.new();\n                 w.push(a);\n                 println(a.v);\n                 match w[0] { Some(x) => { println(x.v); } None => { println(0 - 1); } }\n             }\n"),
        "41\n41\n"
    );
    assert_eq!(
        run("shared struct N { mut v: i64 }\n             fn fill(w: mut ref Vec[weak N]) {\n                 let a: N = N { v: 7i64 };\n                 w.push(a);\n                 match w[0] { Some(x) => { println(x.v); } None => { println(0 - 1); } }\n             }\n             fn main() {\n                 let mut w: Vec[weak N] = Vec.new();\n                 fill(mut w);\n                 match w[0] { Some(x) => { println(x.v); } None => { println(0 - 2); } }\n             }\n"),
        "7\n-2\n"
    );
}

#[test]
fn test_weak_map_value_insert_downgrades_and_collects_the_cycle() {
    // B-2026-08-08-29, interpreter leg — the `Map` twin of the `Vec[weak T]`
    // push above. `Map.insert` stored an ordinary STRONG handle, so a
    // Map-mediated cycle was uncollectable here just as it leaked under
    // codegen. `impl Drop` is the observable: the bodies only run if the two
    // `Arc`s actually reach zero, so a regression that reinstates the strong
    // store prints nothing between "start" and "end".
    assert_eq!(
        run("shared struct N { mut v: i64, mut kids: Map[i64, weak N] }\n             impl Drop for N { fn drop(mut ref self) { println(f\"drop {self.v}\"); } }\n             fn cycle() {\n                 let p = N { v: 1i64, kids: Map.new() };\n                 let c = N { v: 2i64, kids: Map.new() };\n                 c.kids.insert(0i64, p);\n                 p.kids.insert(0i64, c);\n             }\n             fn main() { println(\"start\"); cycle(); println(\"end\"); }\n"),
        "start\ndrop 2\ndrop 1\nend\n"
    );
}

#[test]
fn test_weak_field_alive_yields_some() {
    // Per design.md § Shared Types — Weak references: a `weak` field
    // read is the upgrade point. While a strong holder of the referent
    // is in scope, the upgrade succeeds and yields `Some(strong_ref)`.
    assert_eq!(
        run("shared struct Parent { id: i64 }\n\
             shared struct Child { id: i64, mut weak parent: Parent }\n\
             fn main() {\n\
                 let p = Parent { id: 7 };\n\
                 let c = Child { id: 2, parent: p };\n\
                 match c.parent {\n\
                     Some(parent_ref) => println(parent_ref.id),\n\
                     None => println(\"dangling\"),\n\
                 }\n\
             }"),
        "7\n"
    );
}

#[test]
fn test_weak_field_after_strong_drop_yields_none() {
    // After every strong holder of the referent is dropped, the
    // referent's allocation is freed and the weak field upgrade
    // returns `None`. `make_orphan` returns a Child whose only handle
    // to `Parent` is a weak reference; when the function frame exits,
    // the local strong `p` is dropped and the Arc count hits zero.
    assert_eq!(
        run("shared struct Parent { id: i64 }\n\
             shared struct Child { id: i64, mut weak parent: Parent }\n\
             fn make_orphan() -> Child {\n\
                 let p = Parent { id: 7 };\n\
                 Child { id: 2, parent: p }\n\
             }\n\
             fn main() {\n\
                 let c = make_orphan();\n\
                 match c.parent {\n\
                     Some(parent_ref) => println(parent_ref.id),\n\
                     None => println(\"dangling\"),\n\
                 }\n\
             }"),
        "dangling\n"
    );
}

#[test]
fn test_weak_field_multiple_aliases_all_see_drop() {
    // Two children weakly-reference the same parent. When the parent
    // is dropped, both children's weak fields upgrade to None.
    assert_eq!(
        run("shared struct Parent { id: i64 }\n\
             shared struct Child { id: i64, mut weak parent: Parent }\n\
             fn make_pair() -> (Child, Child) {\n\
                 let p = Parent { id: 1 };\n\
                 (Child { id: 10, parent: p }, Child { id: 11, parent: p })\n\
             }\n\
             fn main() {\n\
                 let pair = make_pair();\n\
                 let (a, b) = pair;\n\
                 match a.parent { Some(_) => println(\"a:alive\"), None => println(\"a:dangling\") }\n\
                 match b.parent { Some(_) => println(\"b:alive\"), None => println(\"b:dangling\") }\n\
             }"),
        "a:dangling\nb:dangling\n"
    );
}

#[test]
fn test_weak_field_reassignment_restores_some() {
    // A `mut weak` field can be reassigned after construction. The
    // assignment auto-downgrades the strong rhs. Reading after the
    // first assignment's referent dies yields None; assigning a fresh
    // live parent restores Some.
    assert_eq!(
        run("shared struct Parent { id: i64 }\n\
             shared struct Child { id: i64, mut weak parent: Parent }\n\
             fn main() {\n\
                 let p1 = Parent { id: 1 };\n\
                 let c = Child { id: 9, parent: p1 };\n\
                 let p2 = Parent { id: 2 };\n\
                 c.parent = p2;\n\
                 match c.parent {\n\
                     Some(parent_ref) => println(parent_ref.id),\n\
                     None => println(\"dangling\"),\n\
                 }\n\
             }"),
        "2\n"
    );
}

#[test]
fn test_weak_field_immutable_form_set_at_construction() {
    // `weak parent: Parent` (no `mut`) is set at construction and
    // never reassigned. While the strong parent lives, upgrade yields
    // Some; after the strong parent's frame exits, upgrade yields None.
    assert_eq!(
        run("shared struct Parent { id: i64 }\n\
             shared struct Child { id: i64, weak parent: Parent }\n\
             fn build() -> Child {\n\
                 let p = Parent { id: 42 };\n\
                 Child { id: 1, parent: p }\n\
             }\n\
             fn main() {\n\
                 let c = build();\n\
                 match c.parent {\n\
                     Some(parent_ref) => println(parent_ref.id),\n\
                     None => println(\"dangling\"),\n\
                 }\n\
             }"),
        "dangling\n"
    );
}

#[test]
fn test_weak_field_upgrade_observes_strong_field_data() {
    // The Some arm of a weak upgrade is a normal SharedStruct handle —
    // its other fields are reachable as usual. Pins that the Arc
    // returned by Weak::upgrade carries the full referent contents,
    // not a stub.
    assert_eq!(
        run("shared struct Parent { id: i64, mut count: i64 }\n\
             shared struct Child { mut weak parent: Parent }\n\
             fn main() {\n\
                 let p = Parent { id: 5, count: 100 };\n\
                 let c = Child { parent: p };\n\
                 match c.parent {\n\
                     Some(parent_ref) => { parent_ref.count = parent_ref.count + 1; println(p.count); },\n\
                     None => println(\"dangling\"),\n\
                 }\n\
             }"),
        "101\n"
    );
}

