// ── Fallible-allocation `try_*` companions (phase-8-stdlib-floor item 2) ──
// The interpreter never OOMs, so every companion returns `Ok`; these pin the
// happy-path behaviour (operation took effect, result wrapped in `Ok`).

#[test]
fn test_try_push_wraps_ok_and_mutates() {
    let output = run("fn main() {\n\
             let mut v: Vec[i64] = Vec.new();\n\
             match v.try_push(5_i64) {\n\
                 Ok(_) => println(\"ok\"),\n\
                 Err(e) => println(\"err\"),\n\
             }\n\
             v.try_push(6_i64);\n\
             println(v.len());\n\
             println(v[0]);\n\
             println(v[1]);\n\
         }");
    assert_eq!(output, "ok\n2\n5\n6\n");
}

#[test]
fn test_try_clone_vec_wraps_ok() {
    let output = run("fn main() {\n\
             let v: Vec[i64] = [1_i64, 2_i64, 3_i64];\n\
             match v.try_clone() {\n\
                 Ok(c) => println(c.len()),\n\
                 Err(e) => println(\"err\"),\n\
             }\n\
         }");
    assert_eq!(output, "3\n");
}

#[test]
fn test_try_extend_from_slice_wraps_ok() {
    let output = run("fn main() {\n\
             let mut v: Vec[i64] = [1_i64];\n\
             let src: Vec[i64] = [2_i64, 3_i64];\n\
             match v.try_extend_from_slice(src) {\n\
                 Ok(_) => println(\"ok\"),\n\
                 Err(e) => println(\"err\"),\n\
             }\n\
             println(v.len());\n\
         }");
    assert_eq!(output, "ok\n3\n");
}

#[test]
fn test_try_extend_alias_wraps_ok() {
    // `try_extend` is the spelling design.md § Fallible Allocation's table
    // uses (`extend(iter)` / `try_extend(iter)`); it denotes the same
    // operation as `try_extend_from_slice`, exactly as the panicking `extend`
    // aliases `extend_from_slice`. Asserted against the sibling spelling in
    // the SAME program so the two cannot silently drift apart.
    // B-2026-08-25-20.
    let output = run("fn main() {\n\
             let mut a: Vec[i64] = [1_i64];\n\
             let mut b: Vec[i64] = [1_i64];\n\
             let src: Vec[i64] = [2_i64, 3_i64];\n\
             match a.try_extend(src) {\n\
                 Ok(_) => println(\"ok\"),\n\
                 Err(e) => println(\"err\"),\n\
             }\n\
             match b.try_extend_from_slice(src) {\n\
                 Ok(_) => println(\"ok\"),\n\
                 Err(e) => println(\"err\"),\n\
             }\n\
             println(a.len());\n\
             println(b.len());\n\
             println(a[2]);\n\
             println(b[2]);\n\
         }");
    assert_eq!(output, "ok\nok\n3\n3\n3\n3\n");
}

