#[test]
fn test_closure_bare_mutating_capture_propagates() {
    // B-2026-07-11-23 — a BARE closure that mutates a captured local captures
    // it by `mut ref` (design.md Rule 2), so writes propagate to the outer
    // binding across invocations. Previously the interpreter snapshot-copied
    // the capture and the mutation was lost (printed 0).
    let output = run_no_errors(
        r#"
fn main() {
    let mut c: i64 = 0;
    let f = |x: i64| { c = c + x; };
    f(3i64);
    f(4i64);
    println(f"{c}");
}
"#,
    );
    assert_eq!(output, "7\n");
}

#[test]
fn test_closure_capture_mutation_in_fold_no_run_build_divergence() {
    // B-2026-07-11-23 — a capture-mutating closure in a `fold` terminal. Codegen
    // INLINES the body (mutation propagates = correct); the interpreter used to
    // invoke it over a snapshot (mutation lost = 0), a run-vs-build divergence.
    // With Rule 2 capture inference the interpreter now agrees: count == 3.
    let output = run_no_errors(
        r#"
fn main() {
    let v: Vec[i64] = [1, 2, 3];
    let mut count = 0i64;
    let s = v.iter().fold(0i64, |a: i64, x: i64| { count = count + 1i64; a + x });
    println(f"{s}");
    println(f"{count}");
}
"#,
    );
    assert_eq!(output, "6\n3\n");
}

#[test]
fn test_closure_readonly_capture_unaffected() {
    // A bare closure that only READS a capture keeps by-value (snapshot)
    // semantics — the Rule 2 inference wraps ONLY mutated captures, so a
    // read-only capture is untouched.
    let output = run_no_errors(
        r#"
fn main() {
    let base: i64 = 10;
    let add = |x: i64| { base + x };
    println(add(5i64).to_string());
}
"#,
    );
    assert_eq!(output, "15\n");
}

#[test]
fn test_iter_reduce_terminal() {
    // B-2026-07-11-19 — the `reduce(f) -> Option[A]` terminal. Folds with the
    // first element as the seed; `None` on an empty source. Covers a sum
    // reduce, a max reduce, an empty source (None), and a `map().reduce`.
    let output = run_no_errors(
        r#"
fn main() {
    let v: Vec[i64] = [1, 2, 3, 4];
    match v.iter().reduce(|a: i64, x: i64| a + x) { Some(s) => { println(s.to_string()); } None => { println("none"); } }
    match v.iter().reduce(|a: i64, x: i64| if a > x { a } else { x }) { Some(s) => { println(s.to_string()); } None => { println("none"); } }
    let e: Vec[i64] = [];
    match e.iter().reduce(|a: i64, x: i64| a + x) { Some(s) => { println(s.to_string()); } None => { println("none"); } }
    match v.iter().map(|x: i64| x * 2i64).reduce(|a: i64, x: i64| a + x) { Some(s) => { println(s.to_string()); } None => { println("none"); } }
}
"#,
    );
    // 10, 4, none, 20
    assert_eq!(output, "10\n4\nnone\n20\n");
}

#[test]
fn test_iter_for_each_terminal() {
    // B-2026-07-11-19 / -23 — the side-effecting `for_each` terminal, unblocked
    // by mut-ref closure capture (its natural use mutates a captured
    // accumulator). Covers a bare for_each, a map().for_each, a
    // filter().for_each, and a range for_each.
    let output = run_no_errors(
        r#"
fn main() {
    let v: Vec[i64] = [1, 2, 3, 4];
    let mut total = 0i64;
    v.iter().for_each(|x: i64| { total = total + x; });
    println(f"{total}");
    v.iter().map(|x: i64| x * 2i64).for_each(|x: i64| { total = total + x; });
    println(f"{total}");
    let mut ev = 0i64;
    v.iter().filter(|x: i64| x % 2i64 == 0i64).for_each(|x: i64| { ev = ev + x; });
    println(f"{ev}");
    let mut rng = 0i64;
    (1i64..5i64).for_each(|x: i64| { rng = rng + x; });
    println(f"{rng}");
}
"#,
    );
    // 10, 30 (10+20), 6 (2+4), 10 (1+2+3+4)
    assert_eq!(output, "10\n30\n6\n10\n");
}

#[test]
fn test_option_result_map() {
    // B-2026-07-12-11 — `Option[T].map(f)` / `Result[T, E].map(f)` were
    // unimplemented in both runtimes despite typechecking. The interpreter now
    // applies `f` to a present payload (`Some`/`Ok`) and re-wraps, passing an
    // absent receiver (`None`/`Err`) through. Covers a fn-reference and an
    // annotated closure, a type-changing map (i64 -> bool), and a chain.
    let output = run_no_errors(
        r#"
fn dbl(n: i64) -> i64 { n * 2i64 }
fn main() {
    let a: Option[i64] = Some(5i64);
    println(f"{a.map(dbl).unwrap_or(0i64 - 1i64)}");
    let n: Option[i64] = None;
    println(f"{n.map(dbl).unwrap_or(0i64 - 1i64)}");
    let ok: Result[i64, String] = Ok(21i64);
    println(f"{ok.map(dbl).unwrap_or(0i64 - 1i64)}");
    let er: Result[i64, String] = Err(f"boom");
    println(f"{er.map(dbl).unwrap_or(0i64 - 99i64)}");
    println(f"{a.map(dbl).map(|x: i64| x + 1i64).unwrap_or(0i64 - 1i64)}");
    let m = a.map(|x: i64| x > 3i64);
    match m { Some(b) => { println(f"{b}"); } None => { println("none"); } }
}
"#,
    );
    assert_eq!(output, "10\n-1\n42\n-99\n11\ntrue\n");
}

#[test]
fn test_option_result_combinators() {
    // B-2026-07-14-6 — the standard Option/Result combinator family, previously
    // rejected at typecheck with no runtime dispatch. Non-closure batch:
    // `ok`/`err`/`or`/`and`/`ok_or`/`flatten`. Closure batch: `unwrap_or_else`/
    // `map_or`/`map_or_else`/`map_err`/`and_then`/`or_else`/`filter`. The
    // interpreter is the oracle for the parity that codegen is verified against.
    let output = run_no_errors(
        r#"
fn main() {
    let r: Result[i64, i64] = Ok(5i64);
    println(f"{r.ok().unwrap_or(0i64)}");
    let e: Result[i64, i64] = Err(7i64);
    println(f"{e.err().unwrap_or(0i64)}");
    let n: Option[i64] = None;
    println(f"{n.or(Some(9i64)).unwrap_or(0i64)}");
    let s: Option[i64] = Some(9i64);
    println(f"{s.and(Some(3i64)).unwrap_or(0i64)}");
    let s2: Option[i64] = Some(9i64);
    println(f"{s2.ok_or(99i64).unwrap()}");
    let oo: Option[Option[i64]] = Some(Some(42i64));
    println(f"{oo.flatten().unwrap_or(0i64)}");
    let n2: Option[i64] = None;
    println(f"{n2.unwrap_or_else(|| 42i64)}");
    let s3: Option[i64] = Some(5i64);
    println(f"{s3.map_or(0i64, |x: i64| x + 1i64)}");
    let s4: Option[i64] = Some(5i64);
    println(f"{s4.map_or_else(|| 0i64, |x: i64| x * 2i64)}");
    let er: Result[i64, i64] = Err(3i64);
    println(f"{er.map_err(|x: i64| x * 10i64).unwrap_err()}");
    let s5: Option[i64] = Some(5i64);
    println(f"{s5.and_then(|x: i64| Some(x + 1i64)).unwrap_or(0i64)}");
    let n3: Option[i64] = None;
    println(f"{n3.or_else(|| Some(9i64)).unwrap_or(0i64)}");
    let s6: Option[i64] = Some(5i64);
    println(f"{s6.filter(|x: i64| x > 3i64).unwrap_or(0i64)}");
    let s7: Option[i64] = Some(2i64);
    println(f"{s7.filter(|x: i64| x > 3i64).unwrap_or(0i64 - 1i64)}");
    let mut tk: Option[i64] = Some(5i64);
    let t = tk.take();
    println(f"{t.unwrap_or(0i64)}");
    println(f"{tk.unwrap_or(0i64 - 1i64)}");
    let mut gi: Option[i64] = None;
    println(f"{gi.get_or_insert(9i64)}");
    println(f"{gi.unwrap_or(0i64 - 1i64)}");
}
"#,
    );
    assert_eq!(
        output,
        "5\n7\n9\n3\n9\n42\n42\n6\n10\n30\n6\n9\n5\n-1\n5\n-1\n9\n9\n"
    );
}

#[test]
fn test_for_iter_mut() {
    // B-2026-07-14-10 — `for x in xs.iter_mut()` yields a mutable reference to
    // each element so `*x = …` / `*x += …` write back into the Vec. The
    // interpreter binds each element to a `VecSlotRef` over the shared element
    // storage; write-throughs land in the live Vec. Covers deref-assign,
    // compound deref-assign, a second pass, and a `String` element.
    let output = run_no_errors(
        r#"
fn main() {
    let mut v: Vec[i64] = [1i64, 2i64, 3i64, 4i64];
    for x in v.iter_mut() { *x = *x * 2i64; }
    for x in v.iter_mut() { *x += 1i64; }
    let mut s: i64 = 0i64;
    for y in v { s = s + y; }
    println(f"{s}");
    let mut words: Vec[String] = [f"a", f"bb"];
    for w in words.iter_mut() { *w = f"x"; }
    for w in words { println(f"{w}"); }
}
"#,
    );
    assert_eq!(output, "24\nx\nx\n");
}

#[test]
fn test_match_arm_guard() {
    // B-2026-07-12-9 — a `match` arm guard (`pat if cond => ..`) falls through
    // to the next arm when the condition is false. The interpreter has always
    // been correct here; this is the oracle the codegen fix is verified against
    // (codegen previously ignored the guard entirely). Covers scalar-binding,
    // enum-pattern, and multi-guard cascades.
    let output = run_no_errors(
        r#"
fn classify(n: i64) -> String {
    match n { 0 => f"zero", x if x < 0i64 => f"neg", x if x < 10i64 => f"small", _ => f"big" }
}
fn g(o: Option[i64]) -> i64 { match o { Some(x) if x > 5i64 => 1i64, Some(_) => 2i64, None => 3i64 } }
fn main() {
    println(classify(0i64));
    println(classify(0i64 - 3i64));
    println(classify(5i64));
    println(classify(100i64));
    println(f"{g(Some(10i64))} {g(Some(2i64))} {g(None)}");
}
"#,
    );
    assert_eq!(output, "zero\nneg\nsmall\nbig\n1 2 3\n");
}

#[test]
fn test_mut_ref_option_shared_writeback() {
    // B-2026-07-12-3 — reassigning through a `mut ref Option[shared]` param
    // propagates to the caller. The interpreter has always been correct; this
    // is the oracle the codegen fix (writeback through the borrow pointer) is
    // verified against.
    let output = run_no_errors(
        r#"
shared struct Node { mut val: i64, mut next: Option[Node] }
fn setit(prev: mut ref Option[Node], n: Node) { prev = Some(n); }
fn main() {
    let mut cur: Option[Node] = Some(Node { val: 1i64, next: None });
    let a = Node { val: 2i64, next: None };
    setit(mut cur, a);
    let b = Node { val: 3i64, next: None };
    setit(mut cur, b);
    match cur {
        None => { println("none"); }
        Some(p) => { println(f"val: {p.val}"); }
    }
}
"#,
    );
    assert_eq!(output, "val: 3\n");
}

#[test]
fn test_match_tuple_pattern() {
    // B-2026-07-12-13 — a `match` on a tuple scrutinee discriminates on each
    // element. The interpreter has always been correct; this is the oracle for
    // the codegen fix (codegen previously always fired the first tuple arm).
    let output = run_no_errors(
        r#"
fn f(a: i64, b: i64) -> i64 { match (a, b) { (0i64, 0i64) => 10i64, (1i64, 2i64) => 20i64, _ => 30i64 } }
fn nested(a: i64, b: i64, c: i64) -> i64 {
    match (a, (b, c)) { (0i64, (1i64, 2i64)) => 1i64, (0i64, (_, _)) => 2i64, _ => 3i64 }
}
fn main() {
    println(f"{f(0i64, 0i64)} {f(1i64, 2i64)} {f(5i64, 5i64)}");
    println(f"{nested(0i64, 1i64, 2i64)} {nested(0i64, 4i64, 5i64)} {nested(8i64, 1i64, 2i64)}");
}
"#,
    );
    assert_eq!(output, "10 20 30\n1 2 3\n");
}

#[test]
fn test_iter_fold_empty_returns_init_unchanged() {
    let output = run_no_errors(
        r#"
fn main() {
    let v: Vec[i64] = Vec[];
    let s: i64 = v.iter().fold(42, |acc, x| acc + x);
    println(s);
}
"#,
    );
    assert_eq!(output, "42\n");
}

