#[test]
fn test_iter_windows_slides_by_one() {
    let output = run_no_errors(
        r#"
fn main() {
    let v = [1, 2, 3, 4, 5];
    let wins: Vec[Vec[i64]] = v.iter().windows(3).collect();
    println(wins.len());
    for w in wins {
        let mut s = "[";
        let mut first = true;
        for x in w {
            if not first { s = s + ","; }
            s = s + f"{x}";
            first = false;
        }
        s = s + "]";
        println(s);
    }
}
"#,
    );
    // 3 windows: [1,2,3], [2,3,4], [3,4,5].
    assert_eq!(output, "3\n[1,2,3]\n[2,3,4]\n[3,4,5]\n");
}

#[test]
