// ── Range pattern matching (interpreter) ────────────────────────────
//
// All five forms — `..hi`, `lo..hi`, `lo..=hi`, `..=hi`, `lo..` — must
// match the value space correctly. Previously the interpreter had a
// "simplified" RangePattern arm that always returned `true`; this test
// pins the per-form semantics.

#[test]
fn test_range_pattern_matches_correctly() {
    let output = run_no_errors(
        r#"
fn classify(n: i32) -> i32 {
    match n {
        ..0 => -1,
        0..=9 => 1,
        10..100 => 2,
        100.. => 3,
        _ => 0,
    }
}
fn main() {
    println(classify(-5));
    println(classify(0));
    println(classify(5));
    println(classify(9));
    println(classify(10));
    println(classify(50));
    println(classify(99));
    println(classify(100));
    println(classify(200));
}
"#,
    );
    assert_eq!(output, "-1\n1\n1\n1\n2\n2\n2\n3\n3\n");
}

#[test]
fn test_range_pattern_char_bounded_inclusive() {
    let output = run_no_errors(
        r#"
fn classify(c: char) -> i32 {
    match c {
        'a'..='z' => 1,
        'A'..='Z' => 2,
        _ => 0,
    }
}
fn main() {
    println(classify('m'));
    println(classify('M'));
    println(classify('1'));
}
"#,
    );
    assert_eq!(output, "1\n2\n0\n");
}

#[test]
fn test_range_pattern_char_bounded_exclusive() {
    let output = run_no_errors(
        r#"
fn main() {
    let c: char = 'g';
    let r = match c {
        'a'..'h' => 1,
        _ => 0,
    };
    println(r);
}
"#,
    );
    // 'g' is in [a, h) — should match.
    assert_eq!(output, "1\n");
}

// ── dbg() task-id tagging and structured output (item 129) ────

#[test]
fn test_dbg_terminal_no_par_omits_task_prefix() {
    // Spec: `dbg(compute(x))` reports `compute(x)` as the expr — the
    // argument's source text, not the whole dbg call.
    let src = r#"fn main() {
    let _ = dbg(7);
}
"#;
    let (_stdout, dbg) = run_program_with_dbg(src, DbgOutputMode::Terminal);
    assert_eq!(dbg.len(), 1, "expected one dbg line, got {:?}", dbg);
    let line = &dbg[0];
    assert_eq!(line, "[test.kara:2] 7 = 7\n");
    assert!(
        !line.contains("task:"),
        "outside par {{}} should not include task tag"
    );
}

#[test]
fn test_dbg_terminal_in_par_tags_each_branch() {
    let src = r#"fn main() {
    par {
        let _ = dbg(1);
        let _ = dbg(2);
    }
}
"#;
    let (_stdout, dbg) = run_program_with_dbg(src, DbgOutputMode::Terminal);
    assert_eq!(dbg.len(), 2, "expected two dbg lines, got {:?}", dbg);
    // Branch 0 → task:1, branch 1 → task:2 (assigned in source order
    // before spawn, so deterministic regardless of OS scheduling).
    assert_eq!(dbg[0], "[task:1 test.kara:3] 1 = 1\n");
    assert_eq!(dbg[1], "[task:2 test.kara:4] 2 = 2\n");
}

#[test]
fn test_dbg_json_no_par_emits_null_task_id() {
    let src = r#"fn main() {
    let _ = dbg(42);
}
"#;
    let (_stdout, dbg) = run_program_with_dbg(src, DbgOutputMode::Json);
    assert_eq!(dbg.len(), 1);
    let line = &dbg[0];
    assert!(line.starts_with("{\"kind\":\"dbg\","));
    assert!(line.contains("\"task_id\":null"), "got {:?}", line);
    assert!(line.contains("\"file\":\"test.kara\""));
    assert!(line.contains("\"line\":2"));
    assert!(line.contains("\"expr\":\"42\""), "got {:?}", line);
    // Bare integer literal infers as i64 in the typechecker; the spec
    // example uses i32 because there `compute(x)` returns explicit i32.
    // The contract is "Display of the inferred type"; i64 is correct here.
    assert!(line.contains("\"type\":\"i64\""), "got {:?}", line);
    assert!(line.contains("\"value\":\"42\""));
    assert!(line.ends_with("}\n"));
}

#[test]
fn test_dbg_json_in_par_emits_numeric_task_id() {
    let src = r#"fn main() {
    par {
        let _ = dbg(10);
        let _ = dbg(20);
    }
}
"#;
    let (_stdout, dbg) = run_program_with_dbg(src, DbgOutputMode::Json);
    assert_eq!(dbg.len(), 2, "got {:?}", dbg);
    assert!(dbg[0].contains("\"task_id\":1"), "got {:?}", dbg[0]);
    assert!(dbg[0].contains("\"value\":\"10\""));
    assert!(dbg[1].contains("\"task_id\":2"), "got {:?}", dbg[1]);
    assert!(dbg[1].contains("\"value\":\"20\""));
}

#[test]
fn test_dbg_json_value_uses_debug_fmt_quoting() {
    // The `value` field must use `Debug` formatting: strings get
    // quoted as `"hello"` not `hello`. The whole field is then JSON-
    // escaped, so the inner quotes show up as `\"`.
    let src = r#"fn main() {
    let _ = dbg("hi");
}
"#;
    let (_stdout, dbg) = run_program_with_dbg(src, DbgOutputMode::Json);
    assert_eq!(dbg.len(), 1);
    // Inner Debug form: `"hi"`. JSON-escaped: `"\"hi\""`.
    assert!(
        dbg[0].contains("\"value\":\"\\\"hi\\\"\""),
        "expected JSON-escaped quoted string, got {:?}",
        dbg[0]
    );
}

#[test]
fn test_dbg_returns_its_argument() {
    // dbg() is an identity function — the value flows through.
    let src = r#"fn main() {
    let x = dbg(3) + dbg(4);
    println(x);
}
"#;
    let (stdout, dbg) = run_program_with_dbg(src, DbgOutputMode::Terminal);
    assert_eq!(stdout.join(""), "7\n");
    assert_eq!(dbg.len(), 2);
}

// ── Range / RangeInclusive as Iterator ─────────────────────────
//
// Range and RangeInclusive evaluate to `Value::Iterator` so the adaptor
// surface (`step_by`, `map`, `filter`, `take`, `collect`, ...) dispatches
// directly without a redundant `.iter()` layer. The for-loop iterable
// path drains `Value::Iterator` via `iterator_step`, so for-loop
// semantics are preserved.

#[test]
fn test_range_iter_step_by_collect() {
    // `(0..10).step_by(2).collect()` — half-open Range as Iterator.
    let output = run_no_errors(
        r#"
fn main() {
    let xs: Vec[i64] = (0..10).step_by(2).collect();
    for x in xs {
        println(x);
    }
}
"#,
    );
    assert_eq!(output, "0\n2\n4\n6\n8\n");
}

#[test]
fn test_range_inclusive_step_by_collect() {
    // `(1..=10).step_by(2).collect()` — RangeInclusive as Iterator pins
    // the inclusive-end semantics (10 is reachable but the stride
    // skips it).
    let output = run_no_errors(
        r#"
fn main() {
    let xs: Vec[i64] = (1..=10).step_by(2).collect();
    for x in xs {
        println(x);
    }
}
"#,
    );
    assert_eq!(output, "1\n3\n5\n7\n9\n");
}

#[test]
fn test_range_redundant_iter() {
    // `(0..5).iter().collect()` — the redundant iter() call on a Range
    // is a no-op pass-through. Pins the iter/into_iter early-return
    // guard (sub-step (d)) — without it, this hits an `unreachable!`
    // because Range now produces `Value::Iterator` rather than
    // `Value::Array`.
    let output = run_no_errors(
        r#"
fn main() {
    let xs: Vec[i64] = (0..5).iter().collect();
    for x in xs {
        println(x);
    }
}
"#,
    );
    assert_eq!(output, "0\n1\n2\n3\n4\n");
}

#[test]
fn test_range_chained_adaptors() {
    // Multi-step adaptor composition through the new entry surface:
    // map doubles each element, filter keeps those > 5.
    let output = run_no_errors(
        r#"
fn main() {
    let xs: Vec[i64] = (0..10).map(|x| x * 2).filter(|x| x > 5).collect();
    for x in xs {
        println(x);
    }
}
"#,
    );
    assert_eq!(output, "6\n8\n10\n12\n14\n16\n18\n");
}

#[test]
fn test_range_for_loop_unchanged() {
    // Regression — for-loop semantics must survive the Range → Iterator
    // eval change. Sums 0+1+2+3+4 = 10.
    let output = run_no_errors(
        r#"
fn main() {
    let mut s = 0;
    for x in 0..5 {
        s = s + x;
    }
    println(s);
}
"#,
    );
    assert_eq!(output, "10\n");
}

#[test]
fn test_entry_chain_on_a_map_field_mutates_the_real_map() {
    // ORACLE for B-2026-08-18-34. `map.entry(k).or_insert(d).push(v)` is the
    // idiomatic append into a `Map[K, Vec[V]]`, and it worked only when the map
    // was a LOCAL. Rooted at a struct FIELD -- where a multimap normally lives
    // -- the interpreter reported "method 'push' not found on type 'unknown'"
    // because `Value::Entry` names its map by BINDING NAME and a field has none.
    //
    // The local leg is kept beside the field one so the two spellings are
    // asserted to agree, which is the property that actually matters: the row
    // was a check/run divergence, and `karac check` accepted both all along.
    //
    // `and_modify` is included because it is the arm that diverged AFTER the
    // rest was fixed -- codegen applied the modification on a field while the
    // interpreter silently skipped it, leaving the `or_insert` default.
    let output = run_no_errors(
        r#"
struct Holder { buckets: Map[i64, Vec[i64]], counts: Map[i64, i64] }

fn main() {
    let mut local: Map[i64, Vec[i64]] = Map.new();
    local.entry(1).or_insert(Vec.new()).push(7);
    local.entry(1).or_insert(Vec.new()).push(8);
    println(local[1].len());

    let mut h = Holder { buckets: Map.new(), counts: Map.new() };
    h.buckets.entry(1).or_insert(Vec.new()).push(7);
    h.buckets.entry(1).or_insert(Vec.new()).push(8);
    println(h.buckets[1].len());

    h.counts.entry(2).and_modify(|v| { *v = *v + 100; }).or_insert(7);
    println(h.counts[2]);
    h.counts.entry(2).and_modify(|v| { *v = *v + 100; }).or_insert(7);
    println(h.counts[2]);

    h.buckets.entry(3).or_insert_with(|| Vec.new()).push(42);
    println(h.buckets[3].len());
}
"#,
    );
    assert_eq!(output, "2\n2\n7\n107\n1\n");
}

#[test]
fn test_entry_chain_on_a_self_map_field() {
    // The `self.buckets…` spelling of B-2026-08-18-34, which is how the shape
    // actually appears: this is LeetCode 895 (Maximum Frequency Stack), the
    // kata that found the bug. `self` is a `mut ref self` receiver, and the row
    // established that the field root -- not the `self` context -- was the
    // variable, so this pins the combination that has to keep working.
    let output = run_no_errors(
        r#"
struct FreqStack { freq: Map[i64, i64], buckets: Map[i64, Vec[i64]], maxfreq: i64 }

impl FreqStack {
    fn push_val(mut ref self, v: i64) {
        let f = self.freq.get_or(v, 0) + 1;
        self.freq.insert(v, f);
        if f > self.maxfreq { self.maxfreq = f; }
        self.buckets.entry(f).or_insert(Vec.new()).push(v);
    }

    fn pop_val(mut ref self) -> i64 {
        let mut b = self.buckets.get_or(self.maxfreq, Vec.new());
        let top = b[b.len() - 1];
        b.pop();
        let blen = b.len() as i64;
        self.buckets.insert(self.maxfreq, b);
        self.freq.insert(top, self.freq.get_or(top, 0) - 1);
        if blen == 0 { self.maxfreq = self.maxfreq - 1; }
        return top;
    }
}

fn main() {
    let mut s = FreqStack { freq: Map.new(), buckets: Map.new(), maxfreq: 0 };
    s.push_val(5); s.push_val(7); s.push_val(5); s.push_val(7); s.push_val(4); s.push_val(5);
    println(s.pop_val());
    println(s.pop_val());
    println(s.pop_val());
    println(s.pop_val());
}
"#,
    );
    // The LeetCode 895 answer for this push sequence.
    assert_eq!(output, "5\n7\n5\n4\n");
}

#[test]
fn test_collect_into_every_documented_from_iterator_target() {
    // ORACLE for B-2026-08-17-36. design.md § Iterator Adaptors: "Every
    // standard collection (`Vec`, `Map`, `Set`, `VecDeque`, `TreeMap`,
    // `String`) implements `FromIterator` for its natural element type."
    // `collect()` used to produce `Vec[T]` and nothing else, so every one of
    // these annotations was rejected as a mismatch the user had caused.
    //
    // The two `String` legs are the point of the uniform lowering: the element
    // is a `char` in one and a `String` in the other, and a pre-typecheck
    // desugar cannot tell them apart -- so both go through
    // `push_str(it.to_string())`. `TreeMap`, the sixth target, cannot be named
    // at all yet (B-2026-08-17-38) and so has no leg here.
    //
    // `Vec` is included to pin the NON-rewrite: it must still take the plain
    // path, untouched by the desugar.
    let output = run_no_errors(
        r#"
fn main() {
    let s = "hi there";
    let up: String = s.chars().map(|c| c.to_uppercase()).collect();
    println(up);

    let mut words: Vec[String] = Vec.new();
    words.push("ab");
    words.push("cd");
    let joined: String = words.iter().map(|w| w.to_uppercase()).collect();
    println(joined);

    let mut raw: Vec[i64] = Vec.new();
    raw.push(1); raw.push(2); raw.push(2); raw.push(3);

    let plain: Vec[i64] = raw.iter().map(|x| x * 2).collect();
    println(plain.len());

    let st: Set[i64] = raw.iter().map(|x| x).collect();
    println(st.len());

    let dq: VecDeque[i64] = raw.iter().map(|x| x * 10).collect();
    println(dq.len());
    println(dq[0]);

    let mp: Map[i64, i64] = raw.iter().map(|x| (x, x * 100)).collect();
    println(mp.len());
    println(mp[3]);

    let empty: Vec[i64] = Vec.new();
    let es: Set[i64] = empty.iter().map(|x| x).collect();
    println(es.len());
}
"#,
    );
    // raw has 4 elements with one duplicate: Vec keeps 4, Set collapses to 3,
    // VecDeque keeps 4 in order (first = 10), Map keys collapse to 3.
    assert_eq!(output, "HI THERE\nABCD\n4\n3\n4\n10\n3\n300\n0\n");
}

#[test]
fn test_collect_desugar_leaves_a_user_defined_collect_alone() {
    // The guard on B-2026-08-17-36's desugar. `collect` is an ordinary method
    // name, so a user type may define one returning a `Set`/`Map`/`String`.
    // Rewriting that would re-iterate an ALREADY-BUILT collection into a fresh
    // one -- silently wrong rather than loudly wrong. The desugar therefore
    // fires only when the receiver is a recognized iterator source or adaptor;
    // a plain identifier receiver like `b` below is not one.
    let output = run_no_errors(
        r#"
struct Bag { n: i64 }

impl Bag {
    fn collect(self) -> Set[i64] {
        let mut s: Set[i64] = Set.new();
        s.insert(self.n);
        return s;
    }
}

fn main() {
    let b = Bag { n: 7 };
    let s: Set[i64] = b.collect();
    println(s.len());
}
"#,
    );
    assert_eq!(output, "1\n");
}

#[test]
fn test_let_bound_range_is_a_value_captured_at_the_binding() {
    // The ORACLE for B-2026-08-17-29, whose codegen twin lives in
    // tests/codegen.rs. The interpreter was already right here — the bug was
    // codegen-only — so this pins the answer codegen was made to match, not a
    // behaviour change.
    //
    // What it pins is the semantics, not just "> 0 iterations": `let r = a..6`
    // captures `a` AT THE BINDING, so mutating `a` afterwards cannot move the
    // range. design.md line 2616 types a range as a first-class `Range[T]`
    // value, which is what makes 14 (2+3+4+5) the answer instead of the 0 that
    // re-reading `a` at the loop would give. Both compiled backends now agree.
    //
    // The rest covers the forms the bug report enumerated: inclusive bounds,
    // an empty range, and reuse of one binding by two nested loops (3 x 3),
    // which pins that iterating a bound range does not consume it.
    let output = run_no_errors(
        r#"
fn main() {
    let mut a = 2;
    let r = a..6;
    a = 10;
    let mut n = 0;
    for i in r { n = n + i; }
    println(n);
    let inc = 0..=4;
    let mut b = 0;
    for i in inc { b = b + i; }
    println(b);
    let e = 5..5;
    let mut z = 0;
    for i in e { z = z + 1; }
    println(z);
    let q = 0..3;
    let mut k = 0;
    for i in q { for j in q { k = k + 1; } }
    println(k);
}
"#,
    );
    assert_eq!(output, "14\n10\n0\n9\n");
}

#[test]
fn test_range_inclusive_take() {
    // `(0..=100).take(3).collect()` pins the eager-snapshot truncation
    // under `take` — the source pre-materialises 101 items but the
    // step-layer adaptor pulls only the first three.
    let output = run_no_errors(
        r#"
fn main() {
    let xs: Vec[i64] = (0..=100).take(3).collect();
    for x in xs {
        println(x);
    }
}
"#,
    );
    assert_eq!(output, "0\n1\n2\n");
}

// ── Slice[T] Iterator impl ─────────────────────────────────────
//
// `Slice[T]` IS `Iterator[T]` — `s.iter()` and `s.into_iter()` route
// through the same Iterator dispatch as `Vec.iter()`, so chained
// adaptors compose. The for-loop iterable path drains `Value::Slice`
// directly, so `for x in s { ... }` keeps working without `.iter()`.
// Sibling to the Range / RangeInclusive Iterator entry above.

#[test]
fn test_interpreter_slice_iter_basic() {
    // `s.iter()` over a borrowed slice yields each element; sums to 6.
    let output = run_no_errors(
        r#"
fn main() {
    let v = Vec[1, 2, 3];
    let s: Slice[i64] = v.as_slice();
    let mut sum = 0;
    for x in s.iter() {
        sum = sum + x;
    }
    println(sum);
}
"#,
    );
    assert_eq!(output, "6\n");
}

#[test]
fn test_interpreter_slice_iter_chain_with_map_collect() {
    // `s.iter().map(|x| x * 2).collect()` returns [2, 4, 6].
    let output = run_no_errors(
        r#"
fn main() {
    let v = Vec[1, 2, 3];
    let s: Slice[i64] = v.as_slice();
    let xs: Vec[i64] = s.iter().map(|x| x * 2).collect();
    for x in xs {
        println(x);
    }
}
"#,
    );
    assert_eq!(output, "2\n4\n6\n");
}

#[test]
fn test_interpreter_slice_iter_chain_with_filter_sum() {
    // `s.iter().filter(|x| x % 2 == 0).fold(0, |a, b| a + b)` returns 2.
    // Sums via `fold` since `Iterator.sum` is not on the shipped terminal
    // surface (`next` / `count` / `collect` / `fold` / `any` / `all`).
    let output = run_no_errors(
        r#"
fn main() {
    let v = Vec[1, 2, 3];
    let s: Slice[i64] = v.as_slice();
    let total: i64 = s.iter().filter(|x| x % 2 == 0).fold(0, |a, b| a + b);
    println(total);
}
"#,
    );
    assert_eq!(output, "2\n");
}

#[test]
fn test_interpreter_slice_into_iter_works() {
    // `s.into_iter()` round-trips identical to `s.iter()` at the
    // tree-walk layer (the borrow-vs-consume distinction is a
    // typechecker concern; sums 1+2+3 = 6).
    let output = run_no_errors(
        r#"
fn main() {
    let v = Vec[1, 2, 3];
    let s: Slice[i64] = v.as_slice();
    let mut sum = 0;
    for x in s.into_iter() {
        sum = sum + x;
    }
    println(sum);
}
"#,
    );
    assert_eq!(output, "6\n");
}

#[test]
fn test_interpreter_slice_for_loop_without_iter() {
    // `for x in s { ... }` (no explicit `.iter()`) sums correctly via
    // the for-loop iterable path's `Value::Slice` arm. Pins (SI3).
    let output = run_no_errors(
        r#"
fn main() {
    let v = Vec[10, 20, 30];
    let s: Slice[i64] = v.as_slice();
    let mut sum = 0;
    for x in s {
        sum = sum + x;
    }
    println(sum);
}
"#,
    );
    assert_eq!(output, "60\n");
}

#[test]
fn test_interpreter_slice_iter_empty_slice() {
    // Empty slice iterator yields no elements; `.collect()` returns [].
    let output = run_no_errors(
        r#"
fn main() {
    let v: Vec[i64] = Vec.new();
    let s: Slice[i64] = v.as_slice();
    let xs: Vec[i64] = s.iter().collect();
    println(xs.len());
}
"#,
    );
    assert_eq!(output, "0\n");
}

// ── Slice / array patterns (phase-5 § Slice and array patterns — sub-item 3)

#[test]
fn test_slice_pattern_empty_matches_empty_vec() {
    // `[]` arm matches an empty Vec; non-empty falls through.
    let output = run_no_errors(
        r#"
fn label(v: Vec[i64]) -> String {
    match v {
        [] => "empty",
        _ => "non-empty",
    }
}
fn main() {
    let a: Vec[i64] = Vec.new();
    let mut b: Vec[i64] = Vec.new();
    b.push(7);
    println(label(a));
    println(label(b));
}
"#,
    );
    assert_eq!(output, "empty\nnon-empty\n");
}

#[test]
fn test_slice_pattern_single_element_fixed_arity_array() {
    // `let [x] = arr` on Array[i64, 1] binds the single element.
    let output = run_no_errors(
        r#"
fn main() {
    let a: Array[i64, 1] = [42];
    let [x] = a;
    println(x);
}
"#,
    );
    assert_eq!(output, "42\n");
}

#[test]
fn test_slice_pattern_fixed_arity_let_binds_all_elements() {
    // `let [a, b, c] = arr` on Array[i64, 3] is irrefutable; binds positionally.
    let output = run_no_errors(
        r#"
fn main() {
    let arr: Array[i64, 3] = [10, 20, 30];
    let [a, b, c] = arr;
    println(a);
    println(b);
    println(c);
}
"#,
    );
    assert_eq!(output, "10\n20\n30\n");
}

#[test]
fn test_slice_pattern_head_only_ignored_rest_on_vec() {
    // `[first, ..]` against a Vec binds head, ignores the tail.
    let output = run_no_errors(
        r#"
fn head_or(v: Vec[i64], default: i64) -> i64 {
    match v {
        [first, ..] => first,
        [] => default,
    }
}
fn main() {
    let mut v: Vec[i64] = Vec.new();
    v.push(10);
    v.push(20);
    v.push(30);
    let empty: Vec[i64] = Vec.new();
    println(head_or(v, -1));
    println(head_or(empty, -1));
}
"#,
    );
    assert_eq!(output, "10\n-1\n");
}

#[test]
fn test_slice_pattern_tail_only_ignored_rest_on_vec() {
    // `[.., last]` against a Vec binds the last element.
    let output = run_no_errors(
        r#"
fn last_or(v: Vec[i64], default: i64) -> i64 {
    match v {
        [.., last] => last,
        [] => default,
    }
}
fn main() {
    let mut v: Vec[i64] = Vec.new();
    v.push(10);
    v.push(20);
    v.push(30);
    println(last_or(v, -1));
}
"#,
    );
    assert_eq!(output, "30\n");
}

#[test]
fn test_slice_pattern_both_ends_ignored_rest_on_vec() {
    // `[first, .., last]` against a Vec of length >= 2 binds both endpoints.
    let output = run_no_errors(
        r#"
fn ends(v: Vec[i64]) -> i64 {
    match v {
        [first, .., last] => first + last,
        [only] => only,
        [] => -1,
    }
}
fn main() {
    let mut v: Vec[i64] = Vec.new();
    v.push(1);
    v.push(2);
    v.push(3);
    v.push(4);
    v.push(5);
    println(ends(v));
}
"#,
    );
    assert_eq!(output, "6\n");
}

#[test]
fn test_slice_pattern_single_bound_rest_at_tail_array() {
    // `let [first, ..rest] = arr` on Array[i64, 5] binds first and rest;
    // rest has length 4.
    let output = run_no_errors(
        r#"
fn main() {
    let arr: Array[i64, 5] = [10, 20, 30, 40, 50];
    let [first, ..rest] = arr;
    println(first);
    println(rest.len());
}
"#,
    );
    assert_eq!(output, "10\n4\n");
}

#[test]
fn test_slice_pattern_single_bound_rest_at_head_array() {
    // `let [..rest, last] = arr` on Array[i64, 4] binds rest and last;
    // rest has length 3.
    let output = run_no_errors(
        r#"
fn main() {
    let arr: Array[i64, 4] = [10, 20, 30, 40];
    let [..rest, last] = arr;
    println(rest.len());
    println(last);
}
"#,
    );
    assert_eq!(output, "3\n40\n");
}

#[test]
fn test_slice_pattern_two_bound_middle_rest_array() {
    // `let [first, ..mid, last] = arr` on Array[i64, 5] binds endpoints
    // and the bound middle rest; mid has length 3.
    let output = run_no_errors(
        r#"
fn main() {
    let arr: Array[i64, 5] = [1, 2, 3, 4, 5];
    let [first, ..mid, last] = arr;
    println(first);
    println(mid.len());
    println(last);
}
"#,
    );
    assert_eq!(output, "1\n3\n5\n");
}

#[test]
fn test_slice_pattern_multi_element_prefix_and_suffix_array() {
    // Multi-element prefix and suffix around an ignored rest:
    // `let [a, b, .., y, z] = arr` on Array[i64, 6].
    let output = run_no_errors(
        r#"
fn main() {
    let arr: Array[i64, 6] = [10, 20, 30, 40, 50, 60];
    let [a, b, .., y, z] = arr;
    println(a);
    println(b);
    println(y);
    println(z);
}
"#,
    );
    assert_eq!(output, "10\n20\n50\n60\n");
}

#[test]
fn test_slice_pattern_vec_bound_rest_sum_via_iter() {
    // Bound rest on a Vec scrutinee is a Slice[T] over the source storage;
    // iteration over it yields the middle elements in order.
    let output = run_no_errors(
        r#"
fn middle_sum(v: Vec[i64]) -> i64 {
    match v {
        [_, ..mid, _] => {
            let mut acc = 0;
            for x in mid { acc = acc + x; }
            acc
        },
        _ => 0,
    }
}
fn main() {
    let mut v: Vec[i64] = Vec.new();
    v.push(100);
    v.push(2);
    v.push(3);
    v.push(4);
    v.push(200);
    println(middle_sum(v));
}
"#,
    );
    assert_eq!(output, "9\n");
}

#[test]
fn test_slice_pattern_match_dispatches_on_length_for_vec() {
    // Different arms select on length classes; vectors of varying length
    // each route to the right arm.
    let output = run_no_errors(
        r#"
fn classify(v: Vec[i64]) -> String {
    match v {
        [] => "0",
        [_] => "1",
        [_, _] => "2",
        [_, .., _] => "3+",
    }
}
fn main() {
    let a: Vec[i64] = Vec.new();
    let mut b: Vec[i64] = Vec.new();
    b.push(1);
    let mut c: Vec[i64] = Vec.new();
    c.push(1); c.push(2);
    let mut d: Vec[i64] = Vec.new();
    d.push(1); d.push(2); d.push(3); d.push(4);
    println(classify(a));
    println(classify(b));
    println(classify(c));
    println(classify(d));
}
"#,
    );
    assert_eq!(output, "0\n1\n2\n3+\n");
}

#[test]
fn test_slice_pattern_rest_binding_preserves_element_values_on_vec() {
    // Bound rest on a Vec scrutinee exposes the middle elements in order
    // and indexes correctly.
    let output = run_no_errors(
        r#"
fn main() {
    let mut v: Vec[i64] = Vec.new();
    v.push(7);
    v.push(8);
    v.push(9);
    v.push(10);
    match v {
        [_, ..rest] => {
            println(rest.len());
            println(rest[0]);
            println(rest[1]);
            println(rest[2]);
        },
        [] => println(-1),
    }
}
"#,
    );
    assert_eq!(output, "3\n8\n9\n10\n");
}

// `c as i32` used to be a no-op in the interpreter (codegen lowered it
// correctly via LLVM `int_cast`). The downstream subtraction then panicked
// in `eval_ops` with "type mismatch in binary operation Sub". The fix
// mirrors `check_cast_pair`'s accepted shapes (char → wide-int).
// Surfaced while writing kata #8 (string-to-integer atoi).
#[test]
fn test_interp_char_as_i32_digit_subtraction() {
    let output = run(r#"
fn main() {
    let s = "0123";
    for c in s.chars() {
        let n: i32 = c as i32;
        let d: i32 = n - 48i32;
        println(d);
    }
}
"#);
    assert_eq!(output, "0\n1\n2\n3\n");
}

#[test]
fn test_interp_int_widening_narrowing_casts() {
    let output = run(r#"
fn main() {
    let a: i32 = 1000i32;
    let b: i64 = a as i64;
    println(b);
    let c: i8 = a as i8;
    let d: i32 = c as i32;
    println(d);
}
"#);
    // 1000 widens to i64 unchanged; truncating to i8 keeps the low 8 bits
    // (1000 & 0xff = 0xe8 = -24 as signed i8), then widens back as -24.
    assert_eq!(output, "1000\n-24\n");
}

#[test]
fn test_interp_int_to_float_cast() {
    let output = run(r#"
fn main() {
    let n: i64 = 7;
    let f: f64 = n as f64;
    println(f);
}
"#);
    assert_eq!(output.trim(), "7");
}

// ── Refinement types: runtime predicate enforcement (phase-9 step 5b) ──

#[test]
fn test_interp_refinement_try_from_ok() {
    // `Even.try_from(4)` evaluates the predicate `self % 2 == 0` against 4,
    // which holds, so the construction returns `Ok(4)`.
    let output = run_no_errors(
        r#"
type Even = i64 where self % 2 == 0;
fn main() {
    match Even.try_from(4) {
        Ok(v) => println(v),
        Err(e) => println(e),
    }
}
"#,
    );
    assert_eq!(output.trim(), "4");
}

#[test]
fn test_interp_refinement_try_from_err() {
    // 3 fails `self % 2 == 0`, so `try_from` returns `Err(<message>)` — the
    // recoverable construction surface. No runtime fault is raised.
    let output = run_no_errors(
        r#"
type Even = i64 where self % 2 == 0;
fn main() {
    match Even.try_from(3) {
        Ok(v) => println(v),
        Err(e) => println(e),
    }
}
"#,
    );
    assert!(
        output.contains("refinement `Even`"),
        "expected an Err message naming the refinement, got: {output:?}"
    );
}

#[test]
fn test_interp_refinement_as_cast_ok() {
    // `4 as Even` passes the predicate; the (layout-identical) base value
    // flows through and prints, with no runtime fault.
    let output = run_no_errors(
        r#"
type Even = i64 where self % 2 == 0;
fn main() {
    let e = 4 as Even;
    println(e);
}
"#,
    );
    assert_eq!(output.trim(), "4");
}

#[test]
fn test_interp_refinement_as_cast_violation_faults() {
    // `3 as Even` is the asserting construction form: a false predicate is a
    // contract violation, surfaced as a runtime fault (not a recoverable Err).
    let errors = runtime_errors(
        r#"
type Even = i64 where self % 2 == 0;
fn main() {
    let e = 3 as Even;
    println(e);
}
"#,
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("contract violated") && e.message.contains("Even")),
        "expected a contract-violation fault naming `Even`, got: {errors:?}"
    );
}

#[test]
fn test_interp_refinement_string_try_from_uses_method_predicate() {
    // A refinement over String with a zero-arg method predicate
    // (`self.len() > 0`): `try_from("")` fails, `try_from("hi")` succeeds.
    let output = run_no_errors(
        r#"
type NonEmpty = String where self.len() > 0;
fn main() {
    match NonEmpty.try_from("") {
        Ok(s) => println(s),
        Err(_) => println("rejected-empty"),
    }
    match NonEmpty.try_from("hi") {
        Ok(s) => println(s),
        Err(_) => println("rejected"),
    }
}
"#,
    );
    assert_eq!(output.trim(), "rejected-empty\nhi");
}

#[test]
fn test_interp_generic_refinement_alias_iterates_and_reads_fields() {
    // B-2026-07-29-26 end-to-end on the tree-walk lane: a generic
    // refinement alias narrowed with `as`, then iterated, with a field
    // read and a cast-out of a second refinement inside the loop — the
    // three projection rules together, which is exactly the shape
    // `examples/weave`'s `aggregate` uses. The typechecker rejected all
    // three before the fix, so this never got to run.
    let output = run_no_errors(
        r#"
type PositiveQty = i64 where self > 0;
type NonEmpty[T] = Vec[T] where self.len() > 0;
struct Item { price: f64, qty: PositiveQty }

fn total(rows: NonEmpty[Item]) -> f64 {
    let mut t = 0.0;
    for r in rows { t = t + r.price * (r.qty as f64); }
    t
}

fn main() {
    let v = vec![Item { price: 1.5, qty: 2 }, Item { price: 0.25, qty: 4 }];
    println(total(v as NonEmpty[Item]));
}
"#,
    );
    assert_eq!(output.trim(), "4");
}

// ── Contracts — requires / ensures runtime enforcement ─────────────
//
// design.md § Contracts: `requires` predicates are checked at function
// entry and `ensures(result) …` at the return point (debug builds); a
// false predicate faults `contract violated`. v1 covers free functions.

#[test]
fn test_contract_requires_holds_runs_body() {
    let output = run_no_errors(
        "fn checked(x: i64) -> i64 requires x > 0 { x * 2 }\n\
         fn main() { println(checked(5)); }",
    );
    assert_eq!(output, "10\n");
}

#[test]
fn test_contract_requires_violation_faults() {
    let errors = runtime_errors(
        "fn checked(x: i64) -> i64 requires x > 0 { x * 2 }\n\
         fn main() { println(checked(-3)); }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("contract violated")),
        "expected a `contract violated` fault for a failed requires, got: {errors:?}"
    );
}

#[test]
fn test_contract_ensures_holds_runs() {
    // Both binding syntaxes are accepted; this uses the design `(result)`.
    let output = run_no_errors(
        "fn double(x: i64) -> i64 ensures(result) result > x { x * 2 }\n\
         fn main() { println(double(5)); }",
    );
    assert_eq!(output, "10\n");
}

#[test]
fn test_contract_ensures_violation_faults() {
    let errors = runtime_errors(
        "fn bad(x: i64) -> i64 ensures(result) result > 100 { x }\n\
         fn main() { println(bad(5)); }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("contract violated")),
        "expected a `contract violated` fault for a failed ensures, got: {errors:?}"
    );
}

#[test]
fn test_contract_requires_and_ensures_combined() {
    let output = run_no_errors(
        "fn clamp_pos(x: i64) -> i64 requires x > 0 ensures(result) result >= x { x + 1 }\n\
         fn main() { println(clamp_pos(10)); }",
    );
    assert_eq!(output, "11\n");
}

#[test]
fn test_contract_ensures_pipe_syntax_still_works() {
    // The `|result|` closure-style binding remains accepted alongside the
    // `(result)` design form.
    let output = run_no_errors(
        "fn double(x: i64) -> i64 ensures |result| result > x { x * 2 }\n\
         fn main() { println(double(5)); }",
    );
    assert_eq!(output, "10\n");
}

// ── Contracts — struct invariants at pub method exits ──────────────
//
// design.md § Contracts rule 3: a type with an `invariant` block re-checks
// it at the exit of every pub method (private methods do not check). v1
// covers pub instance methods.

#[test]
fn test_contract_invariant_holds_runs() {
    // `inc` keeps `self.n >= 0`, so the pub-method-exit check passes.
    let errors = runtime_errors(
        "struct Counter { n: i64, invariant self.n >= 0 }\n\
         impl Counter { pub fn inc(mut ref self) { self.n = self.n + 1; } }\n\
         fn main() { let mut c = Counter { n: 0 }; c.inc(); }",
    );
    assert!(
        errors.is_empty(),
        "a satisfied invariant must not fault, got: {errors:?}"
    );
}

#[test]
fn test_contract_invariant_violation_faults() {
    // `dec` drives `self.n` to -1, violating `self.n >= 0` at method exit.
    let errors = runtime_errors(
        "struct Counter { n: i64, invariant self.n >= 0 }\n\
         impl Counter { pub fn dec(mut ref self) { self.n = self.n - 1; } }\n\
         fn main() { let mut c = Counter { n: 0 }; c.dec(); }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("contract violated")),
        "expected a `contract violated` invariant fault, got: {errors:?}"
    );
}

#[test]
fn test_contract_invariant_private_method_not_checked() {
    // A private method may transiently break the invariant; only the
    // outer pub method's exit checks it. Here the pub method restores
    // nothing but never lets a violated state reach a pub exit, so no
    // fault fires (the private `break_priv` result is discarded).
    let errors = runtime_errors(
        "struct DateRange { start: i64, end: i64, invariant self.start <= self.end }\n\
         impl DateRange {\n\
             fn break_priv(self) -> DateRange { DateRange { start: 10, end: 0 } }\n\
             pub fn via(self) -> i64 { let _b = self.break_priv(); 99 }\n\
         }\n\
         fn main() { let r = DateRange { start: 1, end: 5 }; let _ = r.via(); }",
    );
    assert!(
        errors.is_empty(),
        "a private method must not trigger the invariant check, got: {errors:?}"
    );
}

// ── Contracts — constructor invariants (pub assoc fn returning Self) ──
//
// design.md § Contracts: "Constructors (pub associated functions that return
// `Self`) also check the invariant at their return point." The return value
// is bound as `self` and the type's invariants are re-checked — the
// construction boundary, alongside the pub-method-exit checks above.

#[test]
fn test_contract_constructor_invariant_holds() {
    // A pub constructor that produces a valid instance must not fault.
    let errors = runtime_errors(
        "struct Counter { n: i64, invariant self.n >= 0 }\n\
         impl Counter { pub fn make() -> Self { Counter { n: 7 } } }\n\
         fn main() { let _c = Counter.make(); }",
    );
    assert!(
        errors.is_empty(),
        "a valid constructor must not fault, got: {errors:?}"
    );
}

#[test]
fn test_contract_constructor_invariant_violation_faults() {
    // The constructor builds `n = -5`, violating `self.n >= 0` at its return
    // point — the construction boundary aborts even though no method ran.
    let errors = runtime_errors(
        "struct Counter { n: i64, invariant self.n >= 0 }\n\
         impl Counter { pub fn bad() -> Self { Counter { n: 0 - 5 } } }\n\
         fn main() { let _c = Counter.bad(); }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("contract violated")),
        "expected a `contract violated` invariant fault at construction, got: {errors:?}"
    );
}

#[test]
fn test_contract_constructor_impl_invariant_faults() {
    // `impl invariant` fires at the constructor return point too (it fires at
    // every method exit, and a constructor is a return boundary). The explicit
    // `-> Counter` return-type form (not `Self`) is also recognized.
    let errors = runtime_errors(
        "struct Counter { n: i64, impl invariant self.n >= 0 }\n\
         impl Counter { pub fn bad() -> Counter { Counter { n: 0 - 1 } } }\n\
         fn main() { let _c = Counter.bad(); }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("contract violated")),
        "an `impl invariant` must fire at the constructor return, got: {errors:?}"
    );
}

#[test]
fn test_contract_constructor_non_self_return_not_checked() {
    // A static associated function returning some *other* type (`-> i64`) is
    // not a constructor — its return value must NOT be invariant-checked,
    // even though the type has an invariant and the value would violate it.
    let errors = runtime_errors(
        "struct Counter { n: i64, invariant self.n >= 0 }\n\
         impl Counter { pub fn answer() -> i64 { 0 - 9 } }\n\
         fn main() { let _x = Counter.answer(); }",
    );
    assert!(
        errors.is_empty(),
        "a non-Self-returning assoc fn must not be invariant-checked, got: {errors:?}"
    );
}

#[test]
fn test_contract_shared_constructor_invariant_faults() {
    // Constructor invariants fire on shared (RC) structs too — construction
    // doesn't involve the shared-mutation path, so this is a clean check.
    let errors = runtime_errors(
        "shared struct Scell { n: i64, invariant self.n >= 0 }\n\
         impl Scell { pub fn bad() -> Self { Scell { n: 0 - 1 } } }\n\
         fn main() { let _c = Scell.bad(); }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("contract violated")),
        "a shared-struct constructor must check its invariant, got: {errors:?}"
    );
}

#[test]
fn test_contract_shared_method_invariant_holds() {
    // Shared-struct pub-method invariants are already plumbed (the check is
    // receiver-kind-agnostic): a non-mutating pub method with a held invariant
    // runs clean. (A *violating* shared method needs field mutation through
    // `mut ref self`, which has an orthogonal constraint tracked separately;
    // this pins that the invariant dispatch itself fires without spurious
    // faults for a shared receiver.)
    let errors = runtime_errors(
        "shared struct Scell { n: i64, invariant self.n >= 0 }\n\
         impl Scell { pub fn get(ref self) -> i64 { self.n } }\n\
         fn main() { let c = Scell { n: 5 }; let _ = c.get(); }",
    );
    assert!(
        errors.is_empty(),
        "a held shared-method invariant must not fault, got: {errors:?}"
    );
}

// ── Contracts — old(expr) pre-state + method contracts ─────────────
//
// design.md § Contracts rule 4: `old(expr)` in an `ensures` clause reads
// the value captured at function entry. Method `requires`/`ensures` are
// enforced on the method-dispatch path (same as free functions).

#[test]
fn test_contract_old_method_holds() {
    // `withdraw` reduces the balance by `amount`; the postcondition
    // `self.balance == old(self.balance) - amount` holds.
    let errors = runtime_errors(
        "struct Account { balance: i64 }\n\
         impl Account {\n\
             pub fn withdraw(mut ref self, amount: i64) -> i64\n\
                 ensures(result) self.balance == old(self.balance) - amount\n\
             { self.balance = self.balance - amount; amount }\n\
         }\n\
         fn main() { let mut a = Account { balance: 100 }; let _ = a.withdraw(30); }",
    );
    assert!(
        errors.is_empty(),
        "a satisfied old() postcondition must not fault, got: {errors:?}"
    );
}

#[test]
fn test_contract_old_method_violation_faults() {
    // The body mutates the balance wrongly, so the `old()` postcondition fails.
    let errors = runtime_errors(
        "struct Account { balance: i64 }\n\
         impl Account {\n\
             pub fn withdraw(mut ref self, amount: i64) -> i64\n\
                 ensures(result) self.balance == old(self.balance) - amount\n\
             { self.balance = self.balance - 999; amount }\n\
         }\n\
         fn main() { let mut a = Account { balance: 100 }; let _ = a.withdraw(30); }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("contract violated")),
        "expected a `contract violated` fault for the old() postcondition, got: {errors:?}"
    );
}

#[test]
fn test_contract_method_requires_violation_faults() {
    // Method `requires` is enforced on the dispatch path.
    let errors = runtime_errors(
        "struct Counter { n: i64 }\n\
         impl Counter { pub fn step(self, by: i64) -> i64 requires by > 0 { self.n + by } }\n\
         fn main() { let c = Counter { n: 5 }; let _ = c.step(-1); }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("contract violated")),
        "expected a method-requires fault, got: {errors:?}"
    );
}

#[test]
fn test_contract_old_free_function() {
    // `old(x)` in a free-function ensures evaluates to the entry value.
    let output = run_no_errors(
        "fn bump(x: i64) -> i64 ensures(result) result > old(x) { x + 1 }\n\
         fn main() { println(bump(5)); }",
    );
    assert_eq!(output, "6\n");
}

// ── Contracts — impl invariant (step 5b, all-method scope) ─────────
//
// design.md § Contracts — `impl invariant` fires at every method exit
// (pub and private); plain `invariant` only at pub method exits.

#[test]
fn test_impl_invariant_fires_at_private_method_exit() {
    let errors = runtime_errors(
        "struct Counter { n: i64, impl invariant self.n >= 0 }\n\
         impl Counter {\n\
             fn dec_priv(mut ref self) { self.n = self.n - 1; }\n\
             pub fn run(mut ref self) -> i64 { self.dec_priv(); 0 }\n\
         }\n\
         fn main() { let mut c = Counter { n: 0 }; let _ = c.run(); }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("contract violated")),
        "expected `impl invariant` to fault at the private method exit, got: {errors:?}"
    );
}

#[test]
fn test_plain_invariant_not_checked_at_private_method_exit() {
    // The private helper transiently breaks the plain invariant; the pub
    // method restores it before its own exit, so no fault fires.
    let errors = runtime_errors(
        "struct Counter { n: i64, invariant self.n >= 0 }\n\
         impl Counter {\n\
             fn dec_priv(mut ref self) { self.n = self.n - 1; }\n\
             pub fn run(mut ref self) -> i64 { self.dec_priv(); self.n = self.n + 1; 0 }\n\
         }\n\
         fn main() { let mut c = Counter { n: 0 }; let _ = c.run(); }",
    );
    assert!(
        errors.is_empty(),
        "plain invariant must not fire at a private method exit, got: {errors:?}"
    );
}

#[test]
fn test_impl_invariant_holds_runs() {
    let errors = runtime_errors(
        "struct Counter { n: i64, impl invariant self.n >= 0 }\n\
         impl Counter { fn inc_priv(mut ref self) { self.n = self.n + 1; } pub fn run(mut ref self) { self.inc_priv(); } }\n\
         fn main() { let mut c = Counter { n: 0 }; c.run(); }",
    );
    assert!(
        errors.is_empty(),
        "a satisfied impl invariant must not fault, got: {errors:?}"
    );
}

// ── Contracts — distinct "predicate panicked" fault category (step 6) ──
//
// design.md § Contracts rule 2: a predicate that *returns false* is
// `contract violated`; a predicate whose *evaluation faults* (index OOB,
// div-by-zero, unwrap) is the distinct `contract predicate panicked`.

#[test]
fn test_contract_predicate_panicked_is_distinct() {
    let errors = runtime_errors(
        "fn at(v: Vec[i64], i: i64) -> i64 requires v[i] >= 0 { 0 }\n\
         fn main() { let v: Vec[i64] = Vec[1, 2, 3]; let _ = at(v, 99); }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("contract predicate panicked")),
        "expected a `contract predicate panicked` fault, got: {errors:?}"
    );
    assert!(
        !errors
            .iter()
            .any(|e| e.message.contains("contract violated")),
        "a panicking predicate must NOT be reported as `contract violated`, got: {errors:?}"
    );
}

#[test]
fn test_contract_violated_distinct_from_panicked() {
    let errors = runtime_errors(
        "fn pos(x: i64) -> i64 requires x > 0 { x }\n\
         fn main() { let _ = pos(-5); }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("contract violated")),
        "expected `contract violated` for a false predicate, got: {errors:?}"
    );
    assert!(
        !errors
            .iter()
            .any(|e| e.message.contains("predicate panicked")),
        "a false predicate must NOT be reported as panicked, got: {errors:?}"
    );
}

#[test]
fn test_contract_predicate_panicked_in_ensures() {
    let errors = runtime_errors(
        "fn f(v: Vec[i64]) -> i64 ensures(result) v[result] >= 0 { 99 }\n\
         fn main() { let v: Vec[i64] = Vec[1, 2, 3]; let _ = f(v); }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("contract predicate panicked")),
        "expected `contract predicate panicked` in an ensures, got: {errors:?}"
    );
}

// ── par-struct field mutation persists through `ref self` ────────
// Regression: a par struct must be reference-semantic in the interpreter
// (SharedStruct, not a value-copy), and its `Atomic` / `Mutex` fields must
// be interior-mutable cells so `.fetch_add` / `lock` writes through a
// `ref self` method reach the caller. Was silently returning 0.

#[test]
fn par_struct_atomic_field_mutation_persists() {
    let out = run("par struct C { n: Atomic[i64] }
         impl C {
             fn add(ref self, v: i64) { let _ = self.n.fetch_add(v, MemoryOrdering.SeqCst); }
             fn get(ref self) -> i64 { self.n.load(MemoryOrdering.SeqCst) }
         }
         fn main() { let c = C { n: Atomic.new(0) }; c.add(5); c.add(37); println(c.get()); }");
    assert_eq!(out.trim(), "42");
}

#[test]
fn par_struct_atomic_store_through_field_persists() {
    let out = run("par struct C { n: Atomic[i64] }
         impl C {
             fn set(ref self, v: i64) { self.n.store(v, MemoryOrdering.SeqCst); }
             fn get(ref self) -> i64 { self.n.load(MemoryOrdering.SeqCst) }
         }
         fn main() { let c = C { n: Atomic.new(0) }; c.set(7); println(c.get()); }");
    assert_eq!(out.trim(), "7");
}

#[test]
fn par_struct_mutex_field_mutation_persists() {
    let out = run(
        "par struct Counter { total: Mutex[i64] }
         impl Counter {
             fn add(ref self, n: i64) { lock self.total t { t = t + n; } }
             fn get(ref self) -> i64 { lock self.total t { t } }
         }
         fn main() { let c = Counter { total: Mutex.new(0) }; c.add(5); c.add(37); println(c.get()); }",
    );
    assert_eq!(out.trim(), "42");
}

#[test]
fn shared_struct_mut_field_still_persists() {
    // Regression guard: the par/shared SharedStruct change must not break the
    // existing `shared struct` `mut`-field mutation path.
    let out = run("shared struct Box { mut v: i64 }
         impl Box { fn set(ref self, x: i64) { self.v = x; } fn get(ref self) -> i64 { self.v } }
         fn main() { let b = Box { v: 1 }; b.set(99); println(b.get()); }");
    assert_eq!(out.trim(), "99");
}

// ── Portable SIMD `Vector[T, N]` — slice 1b interpreter parity ────────
//
// design.md § Portable SIMD + "Interpreter parity scope": the tree-walk
// interpreter and codegen must produce equivalent observable output for the
// same program. These mirror the `tests/codegen.rs::test_vector_*` run-tests
// (same sources, same expected stdout) so the two backends are pinned to the
// same behaviour for construction, element-wise arithmetic, and lane read.

#[test]
fn test_vector_simd_math_transcendentals() {
    // std.simd.math (phase-11): element-wise sqrt/exp/ln/sigmoid/tanh on a
    // float vector, computed per lane. Exact/saturating oracles matching
    // tests/codegen.rs::test_e2e_vector_simd_math_transcendentals.
    let out = run_no_errors(
        r#"
fn main() {
    let v = Vector[f32, 4].from_array([4.0f32, 9.0f32, 16.0f32, 25.0f32]);
    let s = v.sqrt();
    println(s[0]);
    println(s[3]);
    let z = Vector[f32, 4].splat(0.0f32);
    let ex = z.exp();
    println(ex[0]);
    let sg = z.sigmoid();
    println(sg[0]);
    let th = z.tanh();
    println(th[0]);
    let o = Vector[f32, 4].splat(1.0f32);
    let l = o.ln();
    println(l[0]);
}
"#,
    );
    assert_eq!(out, "2\n5\n1\n0.5\n0\n0\n");
}

#[test]
fn test_vector_simd_math_rounding() {
    // std.simd.math (phase-11): element-wise floor/ceil/round/trunc on a float
    // vector, per lane. `round` is half-away-from-zero. Oracle matches
    // tests/codegen.rs::test_e2e_vector_simd_math_rounding. Lanes [2.5, -2.5]
    // pin the distinct rounding directions: floor→[2,-3], ceil→[3,-2],
    // round→[3,-3] (ties away from zero), trunc→[2,-2].
    let out = run_no_errors(
        r#"
fn main() {
    let v = Vector[f32, 4].from_array([2.5f32, -2.5f32, 2.7f32, -2.3f32]);
    let fl = v.floor();
    println(fl[0]); println(fl[1]);
    let ce = v.ceil();
    println(ce[0]); println(ce[1]);
    let ro = v.round();
    println(ro[0]); println(ro[1]);
    let tr = v.trunc();
    println(tr[0]); println(tr[1]);
}
"#,
    );
    assert_eq!(out, "2\n-3\n3\n-2\n3\n-3\n2\n-2\n");
}

#[test]
fn test_vector_simd_math_bits_roundtrip() {
    // std.simd.math (phase-11): element-wise IEEE-754 bitcast between a float
    // vector and a same-width integer vector. Known patterns: 1.0f32 =
    // 0x3F800000 = 1065353216; 1.0f64 = 0x3FF0000000000000 =
    // 4607182418800017408. to_bits -> bits_as_f* round-trips recover the
    // original value. Matches tests/codegen.rs::test_e2e_vector_simd_math_bits.
    let out = run_no_errors(
        r#"
fn main() {
    let v = Vector[f32, 4].from_array([1.0f32, 2.0f32, 0.0f32, -1.0f32]);
    let b = v.to_bits();
    println(b[0]);
    let r = b.bits_as_f32();
    println(r[3]);
    let w = Vector[f64, 2].from_array([1.0, 2.0]);
    let wb = w.to_bits();
    println(wb[0]);
    let wr = wb.bits_as_f64();
    println(wr[1]);
}
"#,
    );
    assert_eq!(out, "1065353216\n-1\n4607182418800017408\n2\n");
}

#[test]
fn test_autograd_reverse_mode_scalar() {
    // std.autograd (phase-11) reverse-mode scalar AD — interpreter parity with
    // tests/codegen.rs::test_e2e_autograd_scalar_arithmetic /
    // test_e2e_autograd_activations. Exercises the shared-struct tape,
    // interior-mutability node recording, and the backward sweep on the
    // tree-walk backend. f(x)=x²+3x at x=2 → 10, grad 7; sigmoid(0)=0.5,
    // grad 0.25; relu(-2) grad 0; tanh(0)=0, grad 1.
    let out = run_no_errors(
        r#"
import std.autograd.{Tape, Var};
fn main() {
    let t = Tape.new();
    let x = Var.leaf(t, 2.0);
    let three = Var.leaf(t, 3.0);
    let f = x.mul(x).add(three.mul(x));
    println(f.value()); f.backward(); println(x.grad());

    let t2 = Tape.new();
    let z = Var.leaf(t2, 0.0);
    let s = z.sigmoid();
    println(s.value()); s.backward(); println(z.grad());

    let t3 = Tape.new();
    let n = Var.leaf(t3, -2.0);
    let rn = n.relu();
    rn.backward(); println(n.grad());

    let t4 = Tape.new();
    let w = Var.leaf(t4, 0.0);
    let y = w.tanh();
    println(y.value()); y.backward(); println(w.grad());
}
"#,
    );
    assert_eq!(out, "10\n7\n0.5\n0.25\n0\n0\n1\n");
}

#[test]
fn test_autograd_grad_value_and_grad() {
    // std.autograd (phase-11) higher-order API `Tape.grad` / `Tape.value_and_grad`
    // — interpreter parity with tests/codegen.rs::test_e2e_autograd_grad_value_and_grad.
    // A closure `Fn(Var) -> Var` is differentiated with no user tape bookkeeping.
    //   value_and_grad(x²+3x, 2) = (10, 7); grad(x²+x, 2) = 5; grad(x³, 2) = 12;
    //   grad(sigmoid, 0) = 0.25; grad(relu, 3) = 1; grad(relu, -1) = 0.
    let out = run_no_errors(
        r#"
import std.autograd.{Tape, Var};
fn main() {
    let vg = Tape.value_and_grad(|x| x.mul(x).add(x.add(x).add(x)), 2.0);
    println(vg.0);
    println(vg.1);
    println(Tape.grad(|x| x.mul(x).add(x), 2.0));
    println(Tape.grad(|x| x.mul(x).mul(x), 2.0));
    println(Tape.grad(|x| x.sigmoid(), 0.0));
    println(Tape.grad(|x| x.relu(), 3.0));
    println(Tape.grad(|x| x.relu(), 0.0 - 1.0));
}
"#,
    );
    assert_eq!(out, "10\n7\n5\n12\n0.25\n1\n0\n");
}

#[test]
fn test_cpu_supports_intrinsic() {
    // `cpu.supports("...") -> bool` — interpreter twin of the codegen probe
    // (parity with tests/codegen.rs::test_e2e_cpu_supports_intrinsic). Assert
    // only host-independent facts: an unknown feature is false; a real feature
    // yields a usable bool.
    let out = run_no_errors(
        r#"
fn main() {
    println(cpu.supports("not-a-real-feature-xyz"));
    let a = cpu.supports("avx2");
    println(a == a);
}
"#,
    );
    assert_eq!(out, "false\ntrue\n");
}

#[test]
fn test_multiversion_dispatches_correctly() {
    // `#[multiversion(...)]` desugars to per-feature variants + a cpu.supports
    // dispatch thunk; every variant computes the same result, so a correct output
    // proves the thunk dispatched. Interpreter parity with
    // tests/codegen.rs::test_e2e_multiversion_dispatches_correctly.
    let out = run_no_errors(
        r#"
#[multiversion(baseline, "avx2", "avx512f")]
fn addup(a: i64, b: i64) -> i64 { a + b }

#[multiversion(baseline, "avx2")]
fn scale(v: i64) -> i64 { v * 3 }

fn main() {
    println(addup(20, 22));
    println(scale(14));
}
"#,
    );
    assert_eq!(out, "42\n42\n");
}

#[test]
fn test_multiversion_method_and_generic_dispatch() {
    // `#[multiversion]` follow-on: `self`-receiver methods (ref / mut ref /
    // owned) and generic free functions. Every variant computes the same result,
    // so correct output proves the thunk dispatched. Interpreter parity with
    // tests/codegen.rs::test_e2e_multiversion_method_and_generic_dispatch.
    let out = run_no_errors(
        r#"
struct Acc { base: i64 }
impl Acc {
    #[multiversion(baseline, "avx2", "avx512f")]
    fn dot(ref self, x: i64) -> i64 { self.base + x }

    #[multiversion(baseline, "avx2")]
    fn scale(mut ref self, k: i64) -> i64 {
        self.base = self.base * k;
        self.base
    }

    #[multiversion(baseline, "avx2")]
    fn consume(self, y: i64) -> i64 { self.base + y }
}

#[multiversion(baseline, "avx2", "avx512f")]
fn gadd[T: Add](a: T, b: T) -> T { a + b }

fn main() {
    let a = Acc { base: 100 };
    println(a.dot(5));
    let mut b = Acc { base: 3 };
    println(b.scale(4));
    let c = Acc { base: 7 };
    println(c.consume(1));
    println(gadd(20, 22));
}
"#,
    );
    assert_eq!(out, "105\n12\n8\n42\n");
}

#[test]
fn test_autograd_reverse_mode_tensor_valued() {
    // std.autograd (phase-11) tensor-valued surface — interpreter parity with
    // tests/codegen.rs::test_e2e_autograd_tensor_valued. Element-wise
    // Tensor[f32, [?]] nodes with gradient accumulation across a fanned-out
    // input: z = x*y + x at x=[2,3], y=[4,5] → dz/dx = y+1 = [5,6],
    // dz/dy = x = [2,3]. Exercises the shared-struct tensor tape, the
    // fresh-local value/grad pushes, and the tensor backward sweep.
    let out = run_no_errors(
        r#"
import std.autograd.{TensorTape, TensorVar};
fn main() {
    let t = TensorTape.new();
    let x0: Tensor[f32, [?]] = Tensor.from([2.0, 3.0]);
    let y0: Tensor[f32, [?]] = Tensor.from([4.0, 5.0]);
    let x = TensorVar.leaf(t, x0);
    let y = TensorVar.leaf(t, y0);
    let z = x.mul(y).add(x);
    z.backward();
    println(x.grad_at(0));
    println(x.grad_at(1));
    println(y.grad_at(0));
    println(y.grad_at(1));
}
"#,
    );
    assert_eq!(out, "5\n6\n2\n3\n");
}

#[test]
fn test_autograd_reverse_mode_tensor_activations() {
    // std.autograd tensor-valued activations — interpreter parity with
    // tests/codegen.rs::test_e2e_autograd_tensor_activations. relu gates the
    // gradient on the input sign ([0,1] for x=[-1,2]); sigmoid'(0)=0.25;
    // tanh'(0)=1.
    let out = run_no_errors(
        r#"
import std.autograd.{TensorTape, TensorVar};
fn main() {
    let t = TensorTape.new();
    let x0: Tensor[f32, [?]] = Tensor.from([-1.0, 2.0]);
    let x = TensorVar.leaf(t, x0);
    let r = x.relu();
    r.backward();
    println(x.grad_at(0));
    println(x.grad_at(1));

    let t2 = TensorTape.new();
    let z0: Tensor[f32, [?]] = Tensor.from([0.0]);
    let z = TensorVar.leaf(t2, z0);
    let s = z.sigmoid();
    s.backward();
    println(z.grad_at(0));

    let t3 = TensorTape.new();
    let w0: Tensor[f32, [?]] = Tensor.from([0.0]);
    let w = TensorVar.leaf(t3, w0);
    let y = w.tanh();
    y.backward();
    println(w.grad_at(0));
}
"#,
    );
    assert_eq!(out, "0\n1\n0.25\n1\n");
}

#[test]
fn test_autograd_reverse_mode_activations_and_losses() {
    // Phase-11 autograd `silu`/`softmax`/`gelu` activations + `bce`/
    // `cross_entropy` losses — interpreter parity with
    // tests/codegen.rs::test_e2e_autograd_activations_and_losses (f32-exact
    // gradients: silu'(0)=0.5, softmax([0,0]) weighted grad [0.25,-0.25],
    // gelu'(0)=0.5, bce(0.8,1) grad -0.625, softmax-CE grad [-0.5,0.5]).
    let out = run_no_errors(
        r#"
import std.autograd.{TensorTape, TensorVar};
fn main() {
    let t1 = TensorTape.new();
    let a = TensorVar.leaf(t1, Tensor.from([0.0, 1.0]));
    let y = a.silu(); let s = y.sum(); s.backward();
    println(a.grad_at(0));

    let t2 = TensorTape.new();
    let x = TensorVar.leaf(t2, Tensor.from([0.0, 0.0]));
    let c = TensorVar.leaf(t2, Tensor.from([1.0, 0.0]));
    let sm = x.softmax(); let l = sm.mul(c).sum(); l.backward();
    println(x.grad_at(0)); println(x.grad_at(1));

    let t3 = TensorTape.new();
    let g = TensorVar.leaf(t3, Tensor.from([0.0]));
    let gy = g.gelu(); let gs = gy.sum(); gs.backward();
    println(g.grad_at(0));

    let t4 = TensorTape.new();
    let p = TensorVar.leaf(t4, Tensor.from([0.8, 0.3]));
    let tg = TensorVar.leaf(t4, Tensor.from([1.0, 0.0]));
    let lb = p.bce(tg); lb.backward();
    println(p.grad_at(0));

    let t5 = TensorTape.new();
    let xc = TensorVar.leaf(t5, Tensor.from([0.0, 0.0]));
    let oh = TensorVar.leaf(t5, Tensor.from([1.0, 0.0]));
    let lc = xc.cross_entropy(oh); lc.backward();
    println(xc.grad_at(0)); println(xc.grad_at(1));
}
"#,
    );
    assert_eq!(out, "0.5\n0.25\n-0.25\n0.5\n-0.625\n-0.5\n0.5\n");
}

#[test]
fn test_autograd_reverse_mode_tensor_scalar_loss() {
    // std.autograd tensor-valued `sum` reduction — interpreter parity with
    // tests/codegen.rs::test_e2e_autograd_tensor_scalar_loss. L = sum(x²) at
    // x=[1,2,3] → 14; dL/dx = 2x = [2,4,6].
    let out = run_no_errors(
        r#"
import std.autograd.{TensorTape, TensorVar};
fn main() {
    let t = TensorTape.new();
    let x0: Tensor[f32, [?]] = Tensor.from([1.0, 2.0, 3.0]);
    let x = TensorVar.leaf(t, x0);
    let sq = x.mul(x);
    let loss = sq.sum();
    let lv = loss.value();
    println(f"{lv[0]}");
    loss.backward();
    println(x.grad_at(0));
    println(x.grad_at(1));
    println(x.grad_at(2));
}
"#,
    );
    assert_eq!(out, "14\n2\n4\n6\n");
}

#[test]
fn test_autograd_reverse_mode_tensor_mean_loss() {
    // std.autograd tensor-valued `mean` reduction — interpreter parity with
    // tests/codegen.rs::test_e2e_autograd_tensor_mean_loss. L = mean(x²) at
    // x=[2,4] (N=2) → 10; dL/dx = 2x/N = x = [2,4].
    let out = run_no_errors(
        r#"
import std.autograd.{TensorTape, TensorVar};
fn main() {
    let t = TensorTape.new();
    let x0: Tensor[f32, [?]] = Tensor.from([2.0, 4.0]);
    let x = TensorVar.leaf(t, x0);
    let sq = x.mul(x);
    let loss = sq.mean();
    let lv = loss.value();
    println(f"{lv[0]}");
    loss.backward();
    println(x.grad_at(0));
    println(x.grad_at(1));
}
"#,
    );
    assert_eq!(out, "10\n2\n4\n");
}

#[test]
fn test_autograd_reverse_mode_matmul() {
    // std.autograd rank-2 matrix surface (MatTape / MatVar) — interpreter parity
    // with tests/codegen.rs::test_e2e_autograd_matmul. Y = A·B, A=[[1,2],[3,4]],
    // B=I; grad_A = [[1,1],[1,1]], grad_B = [[4,4],[6,6]].
    let out = run_no_errors(
        r#"
import std.autograd.{MatTape, MatVar};
fn main() {
    let t = MatTape.new();
    let a0: Tensor[f32, [?, ?]] = Tensor.from([[1.0, 2.0], [3.0, 4.0]]);
    let b0: Tensor[f32, [?, ?]] = Tensor.from([[1.0, 0.0], [0.0, 1.0]]);
    let a = MatVar.leaf(t, a0);
    let b = MatVar.leaf(t, b0);
    let y = a.matmul(b);
    y.backward();
    println(a.grad_at(0, 0));
    println(a.grad_at(1, 1));
    println(b.grad_at(0, 0));
    println(b.grad_at(1, 0));
}
"#,
    );
    assert_eq!(out, "1\n1\n4\n6\n");
}

#[test]
fn test_autograd_reverse_mode_mse_loss() {
    // std.autograd MSE loss — interpreter parity with
    // tests/codegen.rs::test_e2e_autograd_mse_loss. pred=[3,5], target=[1,1] →
    // mse 10, dL/dpred = 2d/N = [2,4].
    let out = run_no_errors(
        r#"
import std.autograd.{TensorTape, TensorVar};
fn main() {
    let t = TensorTape.new();
    let p0: Tensor[f32, [?]] = Tensor.from([3.0, 5.0]);
    let g0: Tensor[f32, [?]] = Tensor.from([1.0, 1.0]);
    let pred = TensorVar.leaf(t, p0);
    let target = TensorVar.leaf(t, g0);
    let loss = pred.mse(target);
    let lv = loss.value();
    println(f"{lv[0]}");
    loss.backward();
    println(pred.grad_at(0));
    println(pred.grad_at(1));
}
"#,
    );
    assert_eq!(out, "10\n2\n4\n");
}

#[test]
fn test_autograd_reverse_mode_gradient_descent_training() {
    // End-to-end training loop — interpreter parity with
    // tests/codegen.rs::test_e2e_autograd_gradient_descent_training. Gradient
    // descent minimizing MSE learns target=[3,5,7]: loss 28 → 0, w → [3,5,7]
    // (rounded, so both backends agree despite f64-vs-f32 precision).
    let out = run_no_errors(
        r#"
import std.autograd.{TensorTape, TensorVar};
fn loss_of(w: ref Tensor[f32, [?]], target: ref Tensor[f32, [?]]) -> f32 {
    let tape = TensorTape.new();
    let wv = TensorVar.leaf(tape, w);
    let tv = TensorVar.leaf(tape, target);
    let loss = wv.mse(tv);
    let lv = loss.value();
    lv[0]
}
fn main() {
    let target: Tensor[f32, [?]] = Tensor.from([3.0, 5.0, 7.0]);
    let mut w: Tensor[f32, [?]] = Tensor.from([0.0, 0.0, 0.0]);
    // B-2026-08-14-14: annotated at the tensors' element type. Unannotated the
    // literal is f64, and `grad * lr` below narrowed it silently into an f32
    // element-wise op. 0.75 is exact in both widths, so no printed value moves.
    let lr: f32 = 0.75;
    let l0 = loss_of(w, target);
    println(f"{l0.round()}");
    let mut step = 0;
    while step < 40 {
        let tape = TensorTape.new();
        let wv = TensorVar.leaf(tape, w);
        let tv = TensorVar.leaf(tape, target);
        let loss = wv.mse(tv);
        loss.backward();
        let grad: Tensor[f32, [?]] = wv.grad();
        let step_dir: Tensor[f32, [?]] = grad * lr;
        w = w - step_dir;
        step = step + 1;
    }
    let lf = loss_of(w, target);
    println(f"{lf.round()}");
    let w0 = w[0];
    let w1 = w[1];
    let w2 = w[2];
    println(f"{w0.round()}");
    println(f"{w1.round()}");
    println(f"{w2.round()}");
}
"#,
    );
    assert_eq!(out, "28\n0\n3\n5\n7\n");
}

// B-2026-08-06-7 — an out-of-range shift AMOUNT is a structured diagnostic,
// not a process panic. Reaching the assertions at all proves the no-panic
// half: before the fix this exact program aborted the interpreter with
// "attempt to shift left with overflow" from Rust's own shift operator, so
// the test binary would have died before it could inspect `errors`.
//
// Both directions and both a narrow and a 64-bit width, because the amount
// is checked against the DECLARED width — 32 for `i32`, 64 for `i64` — and a
// single hard-coded 64 would silently let every narrow over-shift through.
#[test]
fn test_shift_amount_out_of_range_is_runtime_error_not_panic() {
    for (src, what) in [
        (
            "let a: i32 = 1i32; let s: i32 = 32i32; println(a << s);",
            "i32 <<",
        ),
        (
            "let a: i32 = 1i32; let s: i32 = 32i32; println(a >> s);",
            "i32 >>",
        ),
        (
            "let a: i64 = 1i64; let s: i64 = 64i64; println(a << s);",
            "i64 <<",
        ),
        (
            "let a: i64 = 1i64; let s: i64 = -1i64; println(a << s);",
            "i64 << negative",
        ),
    ] {
        let errors = runtime_errors(&format!("fn main() {{\n    {src}\n}}\n"));
        assert!(
            errors
                .iter()
                .any(|e| e.message.contains("shift amount out of range")),
            "{what}: expected a `shift amount out of range` runtime error, got: {errors:?}"
        );
    }
}

// B-2026-08-06-7, the negation leg: `-iN::MIN` traps at the DECLARED width.
//
// The Neg arm used `checked_neg` on the i64 carrier, which only catches
// `-i64::MIN` — so `-(-2147483648i32)` produced 2147483648, a value the
// declared `i32` cannot hold, while the i64 twin trapped correctly. Every
// narrow width, plus the i64 control that was already right, because the check
// keys off the type recorded at the expression's span.
#[test]
fn test_narrow_negation_of_min_is_runtime_error() {
    for (src, what) in [
        ("let a: i8 = -128i8; println(-a);", "i8"),
        ("let a: i16 = -32768i16; println(-a);", "i16"),
        ("let a: i32 = -2147483648i32; println(-a);", "i32"),
        // i64::MIN is built by subtraction rather than written as a literal:
        // a negative literal parses as `Neg(Integer(n))`, so the POSITIVE half
        // must fit i64 — and i64::MIN's does not, making `-9223372036854775808i64`
        // a parse error (`Invalid integer literal`). Filed as B-2026-08-06-13.
        (
            "let a: i64 = -9223372036854775807i64 - 1i64; println(-a);",
            "i64 control",
        ),
    ] {
        let errors = runtime_errors(&format!("fn main() {{\n    {src}\n}}\n"));
        assert!(
            errors
                .iter()
                .any(|e| e.message.contains("integer overflow")),
            "{what}: negating the minimum must raise `integer overflow`, got: {errors:?}"
        );
    }
}

// B-2026-08-06-13: the i64::MIN literal evaluates to i64::MIN — the value, not
// a trap. It reaches the interpreter as a plain already-negative `Integer` node
// (the parser folds it), so the Neg arm's range check never sees it; the
// arithmetic identity is the check that the fold produced the RIGHT value
// rather than merely a parseable one.
#[test]
fn test_i64_min_literal_evaluates_to_i64_min() {
    let out = run_no_errors(
        "fn main() {\n\
         \x20   let a: i64 = -9223372036854775808i64;\n\
         \x20   println(a);\n\
         \x20   println(a == -9223372036854775807i64 - 1i64);\n\
         \x20   println(a + 1i64);\n\
         }\n",
    );
    assert_eq!(
        out.trim(),
        "-9223372036854775808\ntrue\n-9223372036854775807"
    );
}

// …and the guard must not over-trap: `-(iN::MIN + 1)` is representable at
// every width and must stay legal.
#[test]
fn test_narrow_negation_inside_range_is_legal() {
    let out = run_no_errors(
        "fn main() {\n\
         \x20   let a: i8 = -127i8; println(-a);\n\
         \x20   let b: i16 = -32767i16; println(-b);\n\
         \x20   let c: i32 = -2147483647i32; println(-c);\n\
         \x20   let d: i32 = 5i32; println(-d);\n\
         }\n",
    );
    assert_eq!(out.trim(), "127\n32767\n2147483647\n-5");
}

// A shift amount BELOW the width stays legal at every width — the guard must
// not over-trap. `31` on an i32 and `63` on an i64 are the boundary values the
// spec explicitly calls legal.
#[test]
fn test_shift_amount_at_width_minus_one_is_legal() {
    assert_eq!(
        run("fn main() {\n\
             \x20   let a: i32 = 1i32; let s: i32 = 31i32; println(a << s);\n\
             \x20   let b: i64 = 1i64; let t: i64 = 63i64; println(b << t);\n\
             }\n"),
        "-2147483648\n-9223372036854775808\n"
    );
}

// B-2026-08-06-7 — the interpreter half of the shift rules (design.md
// § 2141-2142). Kept in step with the codegen twin
// `e2e_shift_runs_at_declared_width` (same arms, same expected output).
//
// Before the fix, both arms of the interpreter's shift dispatch were a bare
// Rust `a << b` / `a >> b` on the i64 carrier. That gave the same
// out-of-declared-width results codegen gave — `1i32 << 31` was 2147483648 —
// and, for an amount >= 64, PANICKED THE INTERPRETER PROCESS outright
// ("attempt to shift left with overflow" from eval_ops.rs), which is both a
// crash and a violation of the repo standard that every phase emits a
// structured diagnostic rather than panicking.
#[test]
fn test_shift_runs_at_declared_width() {
    assert_eq!(
        run("fn main() {\n\
             \x20   let a: i32 = 1i32;\n\
             \x20   println(a << 31i32);\n\
             \x20   let b: i32 = 1000000i32;\n\
             \x20   let s: i32 = b << 20i32;\n\
             \x20   println(s);\n\
             \x20   println(s > 2147483647i32);\n\
             \x20   let u: u8 = 200u8;\n\
             \x20   println(u << 4u8);\n\
             \x20   let n: i32 = -8i32;\n\
             \x20   println(n >> 1i32);\n\
             }\n"),
        "-2147483648\n603979776\nfalse\n128\n-4\n"
    );
}

// The interpreter half of "`~` complements at the DECLARED width", kept in
// step with the codegen twin `e2e_bitwise_not_runs_at_declared_width` (same
// arms, same expected output).
//
// The interpreter stores every integer in an i128 `Value::Int`, so `!i` on
// the carrier is only the declared answer when the declared type IS the
// carrier width. `~5u8` is 250; the carrier flip gave -6 — not merely wrong
// but unrepresentable in a `u8` — and codegen's i64 twin gave 2^64-6, so the
// backends disagreed with each other as well as with the spec.
//
// Unlike codegen, the interpreter was wrong for BOTH literal spellings
// (suffixed and not), because the carrier has no notion of the local's
// storage width at all. Both are kept so the two backends' tests stay
// arm-for-arm comparable.
#[test]
fn test_bitwise_not_runs_at_declared_width() {
    assert_eq!(
        run("fn main() {\n\
             \x20   let a: u8 = 5;\n\
             \x20   println(~a);\n\
             \x20   let b: u16 = 5;\n\
             \x20   println(~b);\n\
             \x20   let c: u32 = 5;\n\
             \x20   println(~c);\n\
             \x20   let d: u8 = 5;\n\
             \x20   let rd: u8 = ~d;\n\
             \x20   println(rd);\n\
             \x20   let e: u8 = 5u8;\n\
             \x20   println(~e);\n\
             \x20   let f: u8 = 5u8;\n\
             \x20   let rf: u8 = ~f;\n\
             \x20   println(rf);\n\
             \x20   let g: i8 = 5;\n\
             \x20   println(~g);\n\
             \x20   let h: i32 = 5;\n\
             \x20   println(~h);\n\
             \x20   let i: u64 = 5;\n\
             \x20   println(~i);\n\
             \x20   let z: u8 = 0;\n\
             \x20   println(~z);\n\
             \x20   let m: u8 = 255;\n\
             \x20   println(~m);\n\
             \x20   let lo: i8 = -128;\n\
             \x20   println(~lo);\n\
             \x20   let n: u8 = 250;\n\
             \x20   println(~n == 5);\n\
             }\n"),
        "250\n65530\n4294967290\n250\n250\n250\n\
         -6\n-6\n18446744073709551610\n255\n0\n127\ntrue\n"
    );
}

// `~` on an integer-lane `Vector[T, N]` complements EACH LANE at the lane
// width. The interpreter recurses into lanes carrying the CONTAINER's span,
// so the width lookup has to peel `Vector` to reach the lane type — without
// that peel it fell back to a signed 64 and `~Vector[u8, 4](5,…)` gave -6 per
// lane while codegen, whose lanes are a real `<4 x i8>`, gave 250.
#[test]
fn test_bitwise_not_on_vector_lanes_uses_lane_width() {
    assert_eq!(
        run("fn main() {\n\
             \x20   let a: u8 = 5;\n\
             \x20   let v: Vector[u8, 4] = Vector[u8, 4](a, a, a, a);\n\
             \x20   let w: Vector[u8, 4] = ~v;\n\
             \x20   println(w[0]);\n\
             \x20   println(w[3]);\n\
             }\n"),
        "250\n250\n"
    );
}

#[test]
fn test_vector_integer_shift() {
    // std.simd.math (phase-11): element-wise `<<` / `>>` on integer vectors
    // (the last Sleef building block). `>>` is logical on unsigned lanes and
    // arithmetic on signed lanes. The final line exercises the Sleef 2^n
    // idiom: bits_as_f32((n + 127) << 23) with n=3 → 8.0. Matches
    // tests/codegen.rs::test_e2e_vector_integer_shift.
    let out = run_no_errors(
        r#"
fn main() {
    let v = Vector[u32, 4].from_array([1u32, 2u32, 3u32, 4u32]);
    let l = v << Vector[u32, 4].splat(3u32);
    println(l[0]);
    println(l[3]);
    let r = Vector[u32, 4].splat(2147483648u32) >> Vector[u32, 4].splat(4u32);
    println(r[0]);
    let ar = Vector[i32, 4].splat(-16) >> Vector[i32, 4].splat(2);
    println(ar[0]);
    let expo = (Vector[u32, 4].splat(3u32) + Vector[u32, 4].splat(127u32))
        << Vector[u32, 4].splat(23u32);
    let pow = expo.bits_as_f32();
    println(pow[0]);
}
"#,
    );
    assert_eq!(out, "8\n32\n134217728\n-4\n8\n");
}

