// ── Module-level `let` / `let mut` bindings in the interpreter ──────
//
// Codegen emits these as globals and `run_program` (build+run) covered
// them, but the interpreter never evaluated/bound them — a module-level
// `let COUNT = 42` read from any function panicked ("variable not found;
// should be caught by resolver"), a run-vs-build divergence. These pin the
// run side; the codegen tests (tests/codegen.rs `test_e2e_modbind_*`) pin
// the identical build output.

#[test]
fn test_module_binding_immutable_read() {
    let out = run_no_errors(
        "let COUNT: i64 = 42i64;\n\
         let FLAG: bool = true;\n\
         fn main() {\n\
             println(COUNT);\n\
             if FLAG { println(1i64); } else { println(0i64); }\n\
         }",
    );
    assert_eq!(out, "42\n1\n");
}

#[test]
fn test_module_binding_mut_reassignment_from_fn() {
    // A `let mut` module binding accumulates across function calls — the
    // reassignment resolves against the global slot.
    let out = run_no_errors(
        "let mut TOTAL: i64 = 0i64;\n\
         fn add(n: i64) { TOTAL = TOTAL + n; }\n\
         fn main() {\n\
             add(10i64);\n\
             add(5i64);\n\
             println(TOTAL);\n\
         }",
    );
    assert_eq!(out, "15\n");
}

#[test]
fn test_module_binding_local_shadow_takes_precedence() {
    // Parity with tests/codegen.rs::test_e2e_modbind_local_shadow_takes_precedence
    // — a function-local binding shadows the module binding for its scope.
    let out = run_no_errors(
        "let mut COUNTER: i64 = 100i64;\n\
         fn local_shadows() -> i64 {\n\
             let COUNTER: i64 = 7i64;\n\
             COUNTER\n\
         }\n\
         fn main() {\n\
             println(local_shadows());\n\
             println(COUNTER);\n\
         }",
    );
    assert_eq!(out, "7\n100\n");
}

#[test]
fn test_module_binding_computed_cross_referencing() {
    // Parity with tests/codegen.rs::test_e2e_modbind_computed_cross_referencing_initializer
    // (B-2026-07-11-16). A computed initializer referencing another binding.
    let out = run_no_errors(
        "let COUNT: i64 = 42i64;\n\
         let DOUBLED: i64 = COUNT * 2i64;\n\
         let TRIPLED: i64 = DOUBLED + COUNT;\n\
         fn main() {\n\
             println(COUNT);\n\
             println(DOUBLED);\n\
             println(TRIPLED);\n\
         }",
    );
    assert_eq!(out, "42\n84\n126\n");
}

#[test]
fn test_module_binding_computed_unannotated() {
    // Parity with tests/codegen.rs::test_e2e_modbind_computed_unannotated_initializer
    // (B-2026-07-11-16 residual). Computed bindings with NO `: TYPE`
    // annotation — the interpreter evaluates the value expr regardless of
    // annotation, so this always worked on the run side; the codegen side now
    // matches by sizing the global from the inferred type.
    let out = run_no_errors(
        "let COUNT: i64 = 42i64;\n\
         let DOUBLED = COUNT * 2i64;\n\
         let TRIPLED = DOUBLED + COUNT;\n\
         let SMALL: i32 = 7i32;\n\
         let SMALL2 = SMALL + 3i32;\n\
         fn main() {\n\
             println(DOUBLED);\n\
             println(TRIPLED);\n\
             println(SMALL2);\n\
         }",
    );
    assert_eq!(out, "84\n126\n10\n");
}

#[test]
fn test_priority_queue_min_and_max_at_scalar_and_heap_t() {
    // Phase-11 `PriorityQueue[T: Ord]` on the tree-walk backend. The compiled
    // twin is `tests/codegen.rs`'s
    // `e2e_stdlib_priority_queue_min_and_max_at_scalar_and_heap_t`, and the two
    // assert the SAME expected string on purpose: this module's bodies are real
    // Kāra compiled through the baked-stdlib path, so interpreter/codegen
    // parity is the property that keeps one source honest across two backends.
    // No `import` — `PriorityQueue` is prelude-visible like `SortedSet`.
    let out = run(r#"
fn main() {
    let mut q: PriorityQueue[i64] = PriorityQueue.new();
    q.push(5); q.push(1); q.push(4); q.push(2); q.push(3);
    println(q.len());
    println(q.is_empty());
    let a = q.into_sorted_vec();
    let mut i = 0;
    while i < a.len() { println(a[i]); i = i + 1; }
    let mut m: PriorityQueue[i64] = PriorityQueue.max_first();
    m.push(5); m.push(1); m.push(4);
    let b = m.into_sorted_vec();
    let mut j = 0;
    while j < b.len() { println(b[j]); j = j + 1; }
    let v: Vec[i64] = [9, 7, 8, 1, 3];
    let c = PriorityQueue.from(v).into_sorted_vec();
    let mut k = 0;
    while k < c.len() { println(c[k]); k = k + 1; }
    let mut s: PriorityQueue[String] = PriorityQueue.new();
    s.push("pear"); s.push("apple"); s.push("fig");
    let d = s.into_sorted_vec();
    let mut z = 0;
    while z < d.len() { println(d[z]); z = z + 1; }
    let e = PriorityQueue.max_first_from(["pear", "apple", "fig"]).into_sorted_vec();
    let mut w = 0;
    while w < e.len() { println(e[w]); w = w + 1; }
    let mut f: PriorityQueue[i64] = PriorityQueue.new();
    println(f.is_empty());
    match f.pop() { Some(x) => { println(x); } None => { println("none"); } }
    let empty: Vec[i64] = [];
    let g = PriorityQueue.from(empty).into_sorted_vec();
    println(g.len());
}
"#);
    assert_eq!(
        out,
        "5\nfalse\n1\n2\n3\n4\n5\n5\n4\n1\n1\n3\n7\n8\n9\n\
         apple\nfig\npear\npear\nfig\napple\ntrue\nnone\n0\n"
    );
}

/// B-2026-08-25-32 — `PriorityQueue.peek`: read the root WITHOUT removing it.
///
/// `peek` returns `Option[T]`, not the `Option[ref T]` Rust's
/// `BinaryHeap::peek` hands back, because a Kāra body cannot construct a
/// borrow-carrying `Option` — see the method's own note in
/// `runtime/stdlib/priority_queue.kara`. The root is therefore COPIED, and
/// the properties worth pinning are that the copy is faithful and that the
/// queue is left alone.
///
/// Both element classes appear for the reason the sibling
/// `..._min_and_max_at_scalar_and_heap_t` states: a scalar `T` rides the
/// all-`i64` base layout, so a `String` failure hides completely behind an
/// `i64`-only fixture (B-2026-08-25-7 looked correct at `T = i64` while every
/// `String` came back empty). Both DIRECTIONS appear because `outranks` is the
/// one branch that differs, and a `peek` that read index 0 without the heap
/// property holding would still look right on a min-first queue.
///
/// The non-disturbance assertions are the load-bearing ones: peek twice and
/// the same element must come back, `len` must not move, and the following
/// `pop` must return exactly what `peek` promised. A `peek` that moved the
/// root out would satisfy the first read and fail all three.
///
/// Twin of `tests/codegen.rs`'s `e2e_stdlib_priority_queue_peek_reads_the_root`,
/// asserting the SAME string: this module's bodies are real Kāra compiled
/// through the baked-stdlib path, so interpreter/codegen parity is what keeps
/// one source honest across two backends.
#[test]
fn test_priority_queue_peek_reads_the_root_without_removing_it() {
    let out = run(r#"
fn main() {
    let e: PriorityQueue[i64] = PriorityQueue.new();
    match e.peek() { Some(v) => { println(v); } None => { println("none"); } }
    let mut q: PriorityQueue[i64] = PriorityQueue.new();
    q.push(5); q.push(1); q.push(4); q.push(9);
    match q.peek() { Some(v) => { println(v); } None => {} }
    match q.peek() { Some(v) => { println(v); } None => {} }
    println(q.len());
    match q.pop() { Some(v) => { println(v); } None => {} }
    match q.peek() { Some(v) => { println(v); } None => {} }
    println(q.len());
    let mut m: PriorityQueue[i64] = PriorityQueue.max_first();
    m.push(5); m.push(1); m.push(4); m.push(9);
    match m.peek() { Some(v) => { println(v); } None => {} }
    let h = PriorityQueue.from([9, 7, 8, 1, 3]);
    match h.peek() { Some(v) => { println(v); } None => {} }
    let hm = PriorityQueue.max_first_from([9, 7, 8, 1, 3]);
    match hm.peek() { Some(v) => { println(v); } None => {} }
    let mut s: PriorityQueue[String] = PriorityQueue.new();
    s.push("pear"); s.push("apple"); s.push("fig");
    match s.peek() { Some(v) => { println(v); } None => {} }
    match s.peek() { Some(v) => { println(v); } None => {} }
    println(s.len());
    match s.pop() { Some(v) => { println(v); } None => {} }
    match s.peek() { Some(v) => { println(v); } None => {} }
}
"#);
    assert_eq!(
        out,
        "none\n1\n1\n4\n1\n4\n3\n9\n1\n9\napple\napple\n3\napple\nfig\n"
    );
}

/// B-2026-08-25-32 — the streaming median over two queues, which is the use
/// case the row was filed from (LeetCode 295, kata 295) and the reason `peek`
/// is worth having at all.
///
/// Hold a max-first queue over the lower half and a min-first queue over the
/// upper half; the median is THE TWO ROOTS. That query is O(1) only because
/// reading a root is O(1) — without `peek` the textbook algorithm has to
/// `pop` and `push` back (O(log n) twice, and mutating where a reader wants
/// `ref`), so it cannot be written at its textbook cost.
///
/// The medians are cross-checked against an independent oracle (Python
/// `bisect.insort` + midpoint over the same feed): 5, 10, 5, 4, 5, 6, 7, 7,
/// 8, 7. The trailing `lo.len() + hi.len()` is the non-disturbance assertion
/// that matters most here — after ten iterations each calling `peek` up to
/// twice, all ten elements must still be in the queues. A `peek` that removed
/// what it read would print a number below 10 while every median above it
/// stayed plausible.
///
/// Twin of `tests/codegen.rs`'s
/// `e2e_stdlib_priority_queue_peek_drives_a_streaming_median`.
#[test]
fn test_priority_queue_peek_drives_a_streaming_median() {
    let out = run(r#"
fn main() {
    let mut lo: PriorityQueue[i64] = PriorityQueue.max_first();
    let mut hi: PriorityQueue[i64] = PriorityQueue.new();
    let feed: Vec[i64] = [5, 15, 1, 3, 8, 7, 9, 10, 20, 2];
    let mut k = 0;
    while k < feed.len() {
        lo.push(feed[k]);
        match lo.pop() { Some(t) => { hi.push(t); } None => {} }
        if hi.len() > lo.len() {
            match hi.pop() { Some(t) => { lo.push(t); } None => {} }
        }
        if lo.len() == hi.len() {
            match lo.peek() {
                Some(a) => {
                    match hi.peek() { Some(b) => { println((a + b) / 2); } None => {} }
                }
                None => {}
            }
        } else {
            match lo.peek() { Some(a) => { println(a); } None => {} }
        }
        k = k + 1;
    }
    println(lo.len() + hi.len());
}
"#);
    assert_eq!(out, "5\n10\n5\n4\n5\n6\n7\n7\n8\n7\n10\n");
}

/// B-2026-08-25-35 — a `#[derive(Ord)]` user type satisfies a `T: Ord` bound on
/// a GENERIC IMPL's method, not only on a free generic fn.
///
/// Two gates discharge bounds and they had different powers. `type_satisfies_bound`
/// (typechecker layer) recognizes `#[derive]` on a named type; `Env::bound_satisfied`
/// (the gate method resolution uses for a bound on a generic impl) did not, and its
/// own comment asserted the derive tables were unreachable from there — they are not,
/// `TypeEnv` owns `structs`/`enums`. So the SAME type against the SAME bound got two
/// answers depending on which side of the call the bound was written on: `fn
/// free[T: Ord](..)` accepted it, `impl[T: Ord] Holder[T] { fn tag(..) }` rejected it
/// with "`Item` does not implement `Ord`; trait `Ord` is implemented by: <primitives>".
///
/// `PriorityQueue[T]`'s whole surface is the second kind, which is why no derived
/// user type could be put in one — the point of the sibling test below.
///
/// Twin of `tests/codegen.rs`'s `e2e_derived_ord_satisfies_a_generic_impl_bound`.
/// PARITY test, NOT the regression oracle: this harness's `run()` executes and
/// joins output without asserting the typecheck is clean, and `karac run`
/// demotes typecheck errors to warnings, so this passes on the UNFIXED tree
/// too — the tree-walker never enforced the bound. The oracles that go red are
/// `tests/typechecker.rs`'s `derived_ord_satisfies_a_bound_on_a_generic_impl_method`
/// and the codegen twin. What this pins is that the two backends agree once the
/// program is accepted.
#[test]
fn test_derived_ord_satisfies_a_generic_impl_bound() {
    let out = run(r#"
#[derive(PartialEq, Eq, PartialOrd, Ord)]
struct Item { id: i64 }
struct Holder[=T] { v: T }
impl[T: Ord] Holder[T] {
    fn tag(ref self) -> i64 { 7 }
}
fn free[T: Ord](a: T) -> i64 { 9 }
fn main() {
    let h = Holder { v: Item { id: 1 } };
    println(h.tag());
    println(free(Item { id: 1 }));
}
"#);
    assert_eq!(out, "7\n9\n");
}

/// B-2026-08-25-35 — the end-to-end payoff: a user struct in a `PriorityQueue`.
///
/// Needs BOTH halves of that row's fix. The bound gate above lets `Task` in at
/// all; then `outranks` compares two INDEXED elements (`self.xs[i] > self.xs[j]`),
/// and resolving that element's type name walked the DECLARED field type — `Vec[T]`
/// on `struct PriorityQueue[=T]` — yielding `T`, the impl's type PARAMETER rather
/// than the monomorph's argument. `T` names no struct, so the ordered-comparison
/// dispatch declined and codegen failed with "Unsupported struct binary op: Gt".
/// Same class as B-2026-08-25-28: a type expr left in terms of the impl's parameter
/// inside a monomorph.
///
/// Both directions and `peek`/`pop`/`len` appear because `outranks` is the one
/// branch that differs between them, and because a comparison that silently read
/// index 0 without the heap property holding would still look right on a min-first
/// queue of three.
///
/// Twin of `tests/codegen.rs`'s `e2e_priority_queue_of_a_derived_ord_struct`.
/// PARITY test, not the regression oracle — see the sibling above for why the
/// tree-walk harness cannot fail on a bound rejection. Its codegen twin and
/// `tests/typechecker.rs`'s `derived_ord_struct_is_accepted_by_priority_queue`
/// are the ones that go red on the unfixed tree.
#[test]
fn test_priority_queue_of_a_derived_ord_struct() {
    let out = run(r#"
#[derive(PartialEq, Eq, PartialOrd, Ord)]
struct Task { pri: i64, id: i64 }
fn main() {
    let mut q: PriorityQueue[Task] = PriorityQueue.new();
    q.push(Task { pri: 3, id: 30 });
    q.push(Task { pri: 1, id: 10 });
    q.push(Task { pri: 2, id: 20 });
    match q.peek() { Some(t) => { println(t.id); } None => {} }
    println(q.len());
    while q.len() > 0 {
        match q.pop() { Some(t) => { println(t.id); } None => {} }
    }
    let mut m: PriorityQueue[Task] = PriorityQueue.max_first();
    m.push(Task { pri: 3, id: 30 });
    m.push(Task { pri: 1, id: 10 });
    match m.peek() { Some(t) => { println(t.id); } None => {} }
}
"#);
    assert_eq!(out, "10\n3\n10\n20\n30\n30\n");
}

#[test]
fn test_secret_expose_reads_inner() {
    // `std.secret.Secret[T]` — `Secret.new(v)` wraps a sensitive value and
    // `.expose()` reads the inner value back (both Copy `i64` and non-Copy
    // `String`). The `import` is required — `Secret` is a gated module, not
    // in the prelude.
    let out = run(r#"
import std.secret.{Secret};
fn main() {
    let s = Secret.new(42);
    let v = s.expose();
    println(v);
    let t = Secret.new("hunter2");
    let w = t.expose();
    println(w);
}
"#);
    assert_eq!(out, "42\nhunter2\n");
}

#[test]
fn test_secret_field_redacted_in_display() {
    // A struct containing a `Secret[T]` field renders the field as
    // `<redacted>` in the built-in / derived Display across every position
    // (println, .to_string(), f-string) — never leaking the wrapped value.
    // Matches codegen's `test_e2e_secret_field_redacted_in_display`.
    let out = run_no_errors(
        r#"
import std.secret.{Secret};
#[derive(Display)]
struct Config { name: String, token: Secret[String] }
fn main() {
    let c = Config { name: "alice", token: Secret.new("hunter2") };
    println(c);
    println(c.to_string());
    println(f"cfg={c}");
}
"#,
    );
    let expected = "Config { name: alice, token: <redacted> }\n".repeat(2)
        + "cfg=Config { name: alice, token: <redacted> }\n";
    assert_eq!(out, expected);
}

#[test]
fn test_secret_ct_eq() {
    // `std.secret.Secret[String].ct_eq(other)` — constant-time equality. The
    // interpreter upholds the boolean contract (constant time has no observable
    // effect in a tree-walk); the runtime helper `karac_secret_ct_eq` provides
    // the timing guarantee under codegen. Matches codegen's
    // `test_e2e_secret_ct_eq`. Equal contents → true; differing contents of the
    // same OR different length → false.
    let out = run(r#"
import std.secret.{Secret};
fn main() {
    let a = Secret.new("s3cr3t-token-01");
    let b = Secret.new("s3cr3t-token-01");
    let c = Secret.new("s3cr3t-token-99");
    let d = Secret.new("short");
    println(a.ct_eq(b));
    println(a.ct_eq(c));
    println(a.ct_eq(d));
}
"#);
    assert_eq!(out, "true\nfalse\nfalse\n");
}

#[test]
fn test_secret_string_zeroize_on_drop_runs() {
    // std.secret Zeroize-on-drop (design.md § Clone/Drop/Zeroize): the compiled
    // path overwrites a `Secret[String]`'s buffer with zeros before freeing it;
    // the tree-walk interpreter has no observable heap after drop, so zeroize is
    // a no-op there (same posture as `ct_eq`'s constant-time). This asserts the
    // interpreter runs construction / use / drop of `Secret[String]` identically
    // to codegen (`test_e2e_secret_string_zeroize_runs_all_backends`).
    let out = run(r#"
import std.secret.{Secret};
fn check(tok: ref Secret[String]) -> bool {
    let ref_val: Secret[String] = Secret.new("hunter2-token-01");
    return tok.ct_eq(ref_val)
}
fn main() {
    let a: Secret[String] = Secret.new("hunter2-token-01");
    let b: Secret[String] = Secret.new("different-secret1");
    println(check(a));
    println(check(b));
}
"#);
    assert_eq!(out, "true\nfalse\n");
}

// ── VolatileCell (MMIO wrapper) ─────────────────────────────────

#[test]
fn test_volatile_cell_rejected_under_tree_walk_interpreter() {
    // `VolatileCell[T]` is a compiled-mode primitive: its `.read()` / `.write(v)`
    // execute the baked method bodies, which call the `volatile_read` /
    // `volatile_write` intrinsics — and the tree-walk interpreter has no
    // raw-pointer representation, so it rejects loudly with a "compile with
    // `karac build`" hint (same posture as the raw volatile intrinsics and the
    // `ptr.*` surface). AOT `karac build` and the default JIT `karac run` both
    // lower it correctly (see the codegen E2E
    // `test_e2e_volatile_cell_read_write_roundtrip`); only the pure tree-walk
    // path (this `run_program` API / `KARAC_RUN_JIT=0`) rejects.
    let errors = runtime_errors(
        "fn main() {\n\
             let mut reg: VolatileCell[i32] = VolatileCell.new(7);\n\
             reg.write(42);\n\
             println(reg.read());\n\
         }\n",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("volatile") && e.message.contains("karac build")),
        "expected a volatile compiled-mode rejection, got: {:?}",
        errors.iter().map(|e| e.message.clone()).collect::<Vec<_>>()
    );
}

// ── f16 / bf16 primitives ───────────────────────────────────────

#[test]
fn test_f16_bf16_arithmetic_tree_walk() {
    // f16 / bf16 run under the tree-walk interpreter (computed at f64 and
    // rounded back to the declared width after each operator — B-2026-08-14-7).
    // Uses values exactly representable in f16/bf16 (halves), so these lines
    // matched the compiled backends even before that rounding existed; the
    // non-exact values it fixed (`1.0bf16 + 0.01bf16` read 1.010009765625 here
    // against 1.0078125 compiled) are pinned in
    // `narrow_float_arithmetic_rounds_to_declared_width` below.
    let out = run_no_errors(
        "fn main() {\n\
             let x: f16 = 1.5f16;\n\
             let y: f16 = 2.25f16;\n\
             println(x + y);\n\
             let a: bf16 = 3.0bf16;\n\
             let b: bf16 = 0.5bf16;\n\
             println(a * b);\n\
         }\n",
    );
    assert_eq!(out, "3.75\n1.5\n");
}

/// B-2026-08-14-7 — an `f32` / `f16` / `bf16` operator must produce a value of
/// that width, not the f64 the interpreter computes it in.
///
/// `Value::Float` is an f64 and carries no width tag, so every narrow-float
/// operator computed AND STORED at double precision and kept bits no compiled
/// backend has. The narrowing CASTS were given explicit rounding in
/// B-2026-07-22-4 and the TENSOR element-wise path in B-2026-08-05-31; scalar
/// arithmetic was the third site and never got it. Each line below printed a
/// different number under `--interp` than from the built binary, with `karac
/// check` silent — the expectations here are the compiled values.
///
/// Rounding once at the end is exact, not an approximation: a single IEEE
/// `+`/`-`/`*`/`/` is correctly rounded when the intermediate carries `2p+2`
/// bits, and f64's 53 cover f32 (50), f16 (24) and bf16 (18).
///
/// The `bf16` line is why the row's "only `+` on f32 was measured" note
/// mattered — 8 mantissa bits means `1.0 + 0.01` already diverges, where f32
/// needs a value engineered past its ULP. The `sqrt` line is the second site
/// the fix had to reach: the float-math methods compute at f64 too, and
/// codegen calls `sqrtf`. The f64 lines are controls that must not move, and
/// the `-t` line pins that negation is exact at any width and needs no
/// rounding.
#[test]
fn narrow_float_arithmetic_rounds_to_declared_width() {
    let out = run_no_errors(
        r#"
fn main() {
    let a: f32 = 4000000000u32 as f32;
    let one: f32 = 1 as f32;
    println(f"01 {a + one}");
    println(f"02 {a - one}");
    println(f"03 {a / (3 as f32)}");
    let t: f32 = 0.1 as f32;
    println(f"04 {t * (3 as f32)}");
    println(f"05 {t + t + t}");
    let mut m: f32 = 4000000000 as f32;
    m += one;
    println(f"06 {m}");
    println(f"07 {-t}");
    println(f"08 {t.sqrt()}");
    let bh: bf16 = 1.0bf16;
    println(f"09 {bh + 0.01bf16}");
    let hh: f16 = 1.0f16;
    println(f"10 {hh + 0.0005f16}");
    let d: f64 = 0.1;
    println(f"11 {d * 3.0}");
    println(f"12 {d.sqrt()}");
}
"#,
    );
    assert_eq!(
        out,
        "01 4000000000\n\
         02 4000000000\n\
         03 1333333376\n\
         04 0.30000001192092896\n\
         05 0.30000001192092896\n\
         06 4000000000\n\
         07 -0.10000000149011612\n\
         08 0.3162277638912201\n\
         09 1.0078125\n\
         10 1.0009765625\n\
         11 0.30000000000000004\n\
         12 0.31622776601683794\n"
    );
}

/// B-2026-08-14-7, storage half — a value ENTERING a narrow-float slot must be
/// rounded into it, before any operator runs.
///
/// The row was filed as an arithmetic bug and its scope was corrected once
/// B-2026-08-14-6's sweep showed the identical divergence at `field_assign`,
/// `vec_push` and `vec_idx_assign`, none of which computes anything. 4294967295
/// is not representable in f32 — it rounds to 4294967296, which is what every
/// compiled backend stores — so an interpreter that widened the `u32` to f64
/// and stopped was holding a value the slot's own declared type cannot express.
/// Fixing only the operators would have left all three of these wrong.
///
/// B-2026-08-14-6 built the channel this needs: the typechecker flags every
/// integer expression sitting in a float slot. It recorded presence only; the
/// declared WIDTH now rides along, which is the whole change on this half.
///
/// The `f64` lines are the controls — the same values are exact there, so a
/// rounding applied indiscriminately would show up as a wrong answer on them.
#[test]
fn int_to_narrow_float_store_rounds_into_the_slot() {
    let out = run_no_errors(
        r#"
struct H { mut f: f32 }
struct G { mut f: f64 }

fn main() {
    let big = 4294967295u32;
    let mid = 2147483647i32;
    let mut h = H { f: 0 as f32 };
    h.f = big;
    println(f"01 {h.f}");
    h.f = mid;
    println(f"02 {h.f}");
    let mut vf: Vec[f32] = Vec.new();
    vf.push(big);
    println(f"03 {vf[0i64]}");
    vf[0i64] = mid;
    println(f"04 {vf[0i64]}");
    let mut g = G { f: 0.0 };
    g.f = big;
    println(f"05 {g.f}");
    let mut vd: Vec[f64] = Vec.new();
    vd.push(big);
    println(f"06 {vd[0i64]}");
}
"#,
    );
    assert_eq!(
        out,
        "01 4294967296\n\
         02 2147483648\n\
         03 4294967296\n\
         04 2147483648\n\
         05 4294967295\n\
         06 4294967295\n"
    );
}

/// B-2026-08-14-9, interpreter half — a `mut Slice[T]` mutator must write
/// through to the collection it borrows.
///
/// `swap` was the ONLY method behind the mut-Slice fence in `method_call.rs`;
/// `fill`, `reverse`, `sort`, `sort_by` and `sort_by_key` fell through to the
/// Slice→Array normalization, ran against that fresh snapshot, and had their
/// results discarded. The row that filed this called all eight
/// "interp-correct" — for these five that was not true, and the failure was
/// strictly worse than the codegen gap it was filed for: a build error is
/// loud, `xs.sort()` doing nothing is not.
///
/// The PARTIAL-WINDOW line is the one that pins the fix rather than just the
/// symptom. Writing back a whole snapshot over `storage[0..len]` would look
/// right for a slice of the entire collection and silently corrupt one that
/// starts at an offset; here the receiver is the second half of a
/// `split_at_mut`, so the first half must come back untouched.
#[test]
fn mut_slice_mutators_write_through_to_the_collection() {
    let out = run_no_errors(
        r#"
fn msort(xs: mut Slice[i64]) { xs.sort(); }
fn mrev(xs: mut Slice[i64]) { xs.reverse(); }
fn mfill(xs: mut Slice[i64]) { xs.fill(9i64); }
fn mkey(xs: mut Slice[i64]) { xs.sort_by_key(|x| 0i64 - x); }
fn mby(xs: mut Slice[i64]) { xs.sort_by(|a, b| b.cmp(a)); }
fn mswap(xs: mut Slice[i64]) { xs.swap(0i64, 3i64); }

fn main() {
    let mut a: Vec[i64] = Vec.new();
    a.push(3i64); a.push(1i64); a.push(2i64); a.push(5i64);
    msort(a.as_slice_mut());
    println(f"01 {a[0i64]} {a[1i64]} {a[2i64]} {a[3i64]}");
    mrev(a.as_slice_mut());
    println(f"02 {a[0i64]} {a[1i64]} {a[2i64]} {a[3i64]}");
    mkey(a.as_slice_mut());
    println(f"03 {a[0i64]} {a[1i64]} {a[2i64]} {a[3i64]}");
    mby(a.as_slice_mut());
    println(f"04 {a[0i64]} {a[1i64]} {a[2i64]} {a[3i64]}");
    mswap(a.as_slice_mut());
    println(f"05 {a[0i64]} {a[1i64]} {a[2i64]} {a[3i64]}");
    mfill(a.as_slice_mut());
    println(f"06 {a[0i64]} {a[1i64]} {a[2i64]} {a[3i64]}");

    let mut b: Vec[i64] = Vec.new();
    b.push(9i64); b.push(8i64); b.push(3i64); b.push(1i64); b.push(2i64);
    let mut bs = b.as_slice_mut();
    let h = bs.split_at_mut(2i64);
    msort(h.1);
    println(f"07 {b[0i64]} {b[1i64]} {b[2i64]} {b[3i64]} {b[4i64]}");
}
"#,
    );
    assert_eq!(
        out,
        "01 1 2 3 5\n\
         02 5 3 2 1\n\
         03 5 3 2 1\n\
         04 5 3 2 1\n\
         05 1 3 2 5\n\
         06 9 9 9 9\n\
         07 9 8 1 2 3\n"
    );
}

/// B-2026-08-14-20 — `Slice[T].to_vec()` returns an INDEPENDENT owned
/// container, and `String.from_utf8` accepts a borrowed view.
///
/// Both halves are interpreter-specific traps rather than restatements of the
/// codegen test. `Value::Array` is an `Arc`-shared cell, so the obvious
/// implementation — hand back the receiver, or `.clone()` it — makes the
/// result an ALIAS of its source: lines 03 and 04 write the copy and read the
/// SOURCE, which is the only way that failure shows up (04 is the nested case,
/// where a one-level copy still shares every row). And a `Slice[T]` SLOT is
/// type-erased here: line 05's `Slice` parameter and line 06's `chunks`
/// element both arrive as `Value::Array`, not `Value::Slice`, so a
/// `Value::Slice`-only arm answers `no method 'to_vec' on type 'Vec'` for two
/// shapes the typechecker accepts.
#[test]
fn slice_to_vec_copies_and_from_utf8_takes_a_view() {
    let out = run_no_errors(
        r#"
fn sum_slice(xs: Slice[i64]) -> i64 {
    let v = xs.to_vec();
    let mut t = 0i64;
    let mut i = 0i64;
    while i < v.len() { t = t + v[i]; i = i + 1i64; }
    t
}

fn main() {
    let s = "café";
    match String.from_utf8(s.bytes()) { Ok(t) => println(f"01 {t}"), Err(_) => println("01 bad") }
    match String.from_utf8(s.bytes().to_vec()) { Ok(t) => println(f"02 {t}"), Err(_) => println("02 bad") }

    let nums: Vec[i64] = [10i64, 20i64, 30i64];
    let mut copy = nums.as_slice().to_vec();
    copy[0i64] = 99i64;
    println(f"03 {copy[0i64]} {nums[0i64]}");

    let rows: Vec[Vec[i64]] = [[1i64, 2i64], [3i64, 4i64]];
    let mut rc = rows.as_slice().to_vec();
    rc[0i64][0i64] = 77i64;
    println(f"04 {rc[0i64][0i64]} {rows[0i64][0i64]}");

    println(f"05 {sum_slice(nums)}");

    let cs = nums.as_slice().chunks(2i64);
    let c0 = cs[0i64];
    println(f"06 {c0.to_vec().len()}");

    let words: Vec[String] = ["alpha", "beta"];
    let wc = words[0..2].to_vec();
    println(f"07 {wc.len()} {wc[1i64]}");
}
"#,
    );
    assert_eq!(
        out,
        "01 café\n\
         02 café\n\
         03 99 10\n\
         04 77 1\n\
         05 60\n\
         06 2\n\
         07 2 beta\n"
    );
}

// ── critical_section (interrupt-mask RAII guard) ────────────────

#[test]
fn test_critical_section_inert_under_tree_walk_interpreter() {
    // Unlike the raw MMIO surface, `critical_section.acquire()` runs under the
    // tree-walk interpreter: a single-threaded tree-walk has no real
    // interrupts, so acquire is inert (returns the guard) and the guard's Drop
    // is a no-op (`try_eval_builtin_drop`) — the same posture the memory
    // `fence` intrinsics take. The program runs to completion, guard-drop and
    // all, with no runtime error. (AOT/JIT lower it to the runtime mask calls;
    // see `test_e2e_critical_section_run`.)
    let out = run_no_errors(
        "fn work() writes(Hardware) {\n\
             let _guard = critical_section.acquire();\n\
             println(42);\n\
         }\n\
         fn main() {\n\
             work();\n\
             println(99);\n\
         }\n",
    );
    assert_eq!(out, "42\n99\n");
}

#[test]
fn gpu_upload_download_get_clean_compiled_only_diagnostic() {
    // GPU-SLIP-4h sibling: `gpu.upload` / `gpu.download` are compiled-only
    // (the tree-walk interpreter has no device-buffer model). They must
    // produce a clean runtime diagnostic — the previous fall-through hit the
    // `unreachable!("variable 'gpu' not found")` ICE.
    let errors = runtime_errors(
        "struct P { a: f32 }\n\
         #[gpu]\n\
         fn step(p: P) -> P { p }\n\
         fn main() {\n\
             let mut v: Vec[P] = Vec.new();\n\
             v.push(P { a: 1.0 });\n\
             let buf = gpu.upload(v);\n\
             println(1);\n\
         }",
    );
    assert!(
        !errors.is_empty(),
        "gpu.upload under the interpreter must produce a runtime error"
    );
    assert!(
        errors[0].message.contains("compiled path"),
        "expected the compiled-only diagnostic, got: {:?}",
        errors[0].message
    );
}

#[test]
fn gpu_reduce_over_a_temporary_buffer_field_diagnoses_rather_than_panics() {
    // GPU-SLIP-4b-3b. A resident field reduction is compiled-only like the
    // `gpu.upload` that made the buffer, and it must SAY so on every receiver
    // shape.
    //
    // The temporary receiver is the one that had no statement boundary to stop
    // at: the nested `gpu.upload` records its error and yields `Unit`, then the
    // field access lands on a non-struct receiver and trips the invariant
    // assert there — an ICE, not a diagnostic. The `let`-bound form only looked
    // fine because evaluation halted at its own statement first.
    for receiver in ["gpu.upload(v)", "gpu.dispatch(step, gpu.upload(v))"] {
        let errors = runtime_errors(&format!(
            "struct P {{ a: f32 }}\n\
             #[gpu]\n\
             fn step(p: P) -> P {{ p }}\n\
             fn main() {{\n\
                 let mut v: Vec[P] = Vec.new();\n\
                 v.push(P {{ a: 1.0 }});\n\
                 println(f\"{{gpu.sum(({receiver}).a)}}\");\n\
             }}"
        ));
        assert!(
            !errors.is_empty(),
            "a resident field reduction over `{receiver}` must produce a runtime error"
        );
        assert!(
            errors[0].message.contains("compiled path"),
            "expected the compiled-only diagnostic for `{receiver}`, got: {:?}",
            errors[0].message
        );
    }
}

#[test]
fn gpu_reduce_over_an_ordinary_struct_field_still_runs_on_the_host() {
    // The guard above keys on the typechecker's resident-field table, not on
    // "the argument is a field access" — so a field that holds a host
    // `Vec[f32]` is an ordinary reduction and must still compute. Reducing
    // `gpu.sum(rec.values)` to a compiled-only error would be the obvious way
    // to get this wrong.
    let out = run("struct Rec { values: Vec[f32] }\n\
         fn main() {\n\
             let r = Rec { values: [1.0, 2.0, 3.5] };\n\
             println(f\"{gpu.sum(r.values)}\");\n\
         }");
    assert_eq!(out.trim(), "6.5", "host field reduction must still run");
}

#[test]
fn test_dataframe_read_csv_round_trips_types_nulls_and_quoting() {
    // `DataFrame.read_csv` (phase-11 CSV leg, slice 2) inverts `write_csv`:
    // header → names, per-column inference (all-i64 → Column[i64], else
    // all-f64 → Column[f64], else String), unquoted-empty → NULL, quoted
    // cells unescape (comma kept, doubled quotes → one). Round-trip a mixed
    // table and read back values, types, and the null.
    let tmp = std::env::temp_dir().join("kara_interp_df_read_csv_rt.csv");
    let _ = std::fs::remove_file(&tmp);
    let path = tmp.to_str().unwrap().replace('\\', "\\\\");
    let src = format!(
        "fn main() with writes(FileSystem) reads(FileSystem) {{\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"age\", Column.from_vec([30i64, 25i64, 41i64]));\n\
             df.insert(\"score\", Column.from_vec([91.5, 78.25, 88.0]));\n\
             df.insert(\"name\", Column.from_vec([\"ada\", \"bob, jr.\", \"eve \\\"the\\\" grey\"]));\n\
             let nn: Vec[Option[i64]] = vec![Some(1i64), None, Some(3i64)];\n\
             df.insert(\"nullable\", Column.from_iter_nullable(nn));\n\
             let _ = df.write_csv(\"{path}\");\n\
             match DataFrame.read_csv(\"{path}\") {{\n\
                 Ok(back) => {{\n\
                     println(back.width()); println(back.height());\n\
                     let ages: Column[i64] = back.column(\"age\");\n\
                     match ages[2] {{ Some(v) => println(v), None => println(-1i64) }}\n\
                     let scores: Column[f64] = back.column(\"score\");\n\
                     match scores[1] {{ Some(v) => println(v), None => println(-1.0) }}\n\
                     let names: Column[String] = back.column(\"name\");\n\
                     match names[1] {{ Some(v) => println(v), None => println(\"null\") }}\n\
                     match names[2] {{ Some(v) => println(v), None => println(\"null\") }}\n\
                     let nulls: Column[i64] = back.column(\"nullable\");\n\
                     println(nulls.null_count());\n\
                     match nulls[1] {{ Some(v) => println(v), None => println(\"null-ok\") }}\n\
                 }}\n\
                 Err(_) => println(\"read failed\"),\n\
             }}\n\
         }}"
    );
    let out = run_no_errors(&src);
    let _ = std::fs::remove_file(&tmp);
    assert_eq!(
        out, "4\n3\n41\n78.25\nbob, jr.\neve \"the\" grey\n1\nnull-ok\n",
        "read_csv must invert write_csv: types inferred, quoting unescaped, nulls kept",
    );
}

#[test]
fn test_dataframe_read_csv_missing_file_and_ragged_rows_err() {
    // A missing file surfaces the mapped IoError; a ragged row (cell count
    // ≠ header count) is IoError.Other with the parser's message.
    let tmp = std::env::temp_dir().join("kara_interp_df_read_csv_ragged.csv");
    std::fs::write(&tmp, "a,b\n1,2\n3\n").unwrap();
    let path = tmp.to_str().unwrap().replace('\\', "\\\\");
    let src = format!(
        "fn main() with reads(FileSystem) {{\n\
             match DataFrame.read_csv(\"/definitely-missing-kara.csv\") {{\n\
                 Ok(_) => println(\"bad\"),\n\
                 Err(_) => println(\"missing-err\"),\n\
             }}\n\
             match DataFrame.read_csv(\"{path}\") {{\n\
                 Ok(_) => println(\"bad\"),\n\
                 Err(_) => println(\"ragged-err\"),\n\
             }}\n\
         }}"
    );
    let out = run_no_errors(&src);
    let _ = std::fs::remove_file(&tmp);
    assert_eq!(out, "missing-err\nragged-err\n");
}

#[test]
fn test_lazyframe_explain_and_collect_with_pushdown() {
    // Phase-11 LazyDataFrame slice 1: `df.lazy().select(..).limit(..)`
    // records a plan; `explain()` renders the logical plan (innermost
    // SCAN) plus the optimized single-scan form (consecutive limits fuse
    // to the min, the projection pushes into the scan); `collect()` runs
    // the optimized plan (subset + reorder + truncate, typed reads).
    let out = run_no_errors(
        "fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"a\", Column.from_vec([1i64, 2i64, 3i64, 4i64]));\n\
             df.insert(\"b\", Column.from_vec([10.5, 20.5, 30.5, 40.5]));\n\
             df.insert(\"c\", Column.from_vec([\"x\", \"y\", \"z\", \"w\"]));\n\
             let plan = df.lazy().select(vec![\"b\", \"a\"]).limit(7).limit(2);\n\
             println(plan.explain());\n\
             let out = plan.collect();\n\
             println(out.width()); println(out.height());\n\
             for n in out.column_names() { println(n); }\n\
             let b: Column[f64] = out.column(\"b\");\n\
             match b[1] { Some(v) => println(v), None => println(-1.0) }\n\
         }",
    );
    assert_eq!(
        out,
        "== logical plan ==\n\
         LIMIT 2\n\
         \x20 LIMIT 7\n\
         \x20   SELECT [b, a]\n\
         \x20     SCAN [a, b, c]\n\
         == optimized ==\n\
         SCAN cols=[b, a] limit=2\n\
         2\n2\nb\na\n20.5\n",
        "explain must render logical + fused optimized plan; collect must run it",
    );
}

#[test]
fn test_lazyframe_collect_validates_at_run_not_build() {
    // A select naming a missing column BUILDS fine (plans validate when
    // they run); `explain()` renders INVALID PLAN; `collect()` is the
    // runtime error.
    let out = run_no_errors(
        "fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"a\", Column.from_vec([1i64]));\n\
             let bad = df.lazy().select(vec![\"nope\"]);\n\
             println(\"built-ok\");\n\
             println(bad.explain());\n\
         }",
    );
    assert!(
        out.contains("built-ok")
            && out.contains("INVALID PLAN: LazyFrame.select: no column named 'nope'"),
        "got: {out}",
    );
    let errors = runtime_errors(
        "fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"a\", Column.from_vec([1i64]));\n\
             let _ = df.lazy().select(vec![\"nope\"]).collect();\n\
         }",
    );
    assert!(
        errors
            .iter()
            .any(|e| e.message.contains("no column named 'nope'")),
        "{errors:?}",
    );
}

#[test]
fn test_lazyframe_limit_clamps_and_no_select_keeps_all_columns() {
    // A negative limit clamps to 0; a limit past the height keeps every
    // row; with no select the collect keeps every source column (`*`).
    let out = run_no_errors(
        "fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"a\", Column.from_vec([1i64, 2i64]));\n\
             let zero = df.lazy().limit(-3).collect();\n\
             println(zero.height());\n\
             let all = df.lazy().limit(99).collect();\n\
             println(all.height()); println(all.width());\n\
             println(df.lazy().explain());\n\
         }",
    );
    assert_eq!(
        out,
        "0\n2\n1\n\
         == logical plan ==\n\
         SCAN [a]\n\
         == optimized ==\n\
         SCAN cols=[*]\n",
        "limit must clamp; empty plan must scan everything",
    );
}

#[test]
fn test_lazyframe_filter_expression_pipeline() {
    // Phase-11 LazyDataFrame slice 2: `filter` takes an inspectable
    // `LazyExpr` predicate (built by `col(..)` + comparison/boolean
    // methods). explain renders the FILTER step in both plans — the
    // optimized pipeline keeps filter/limit relative order (they do not
    // commute), lifts the projection to the top, and scan-projects the
    // union of needed columns in source order. collect evaluates per row.
    let out = run_no_errors(
        "import std.lazy.{col};\n\
         fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"age\", Column.from_vec([30i64, 15i64, 41i64, 8i64]));\n\
             df.insert(\"name\", Column.from_vec([\"ada\", \"bob\", \"eve\", \"kid\"]));\n\
             df.insert(\"score\", Column.from_vec([9.5, 3.5, 7.0, 1.0]));\n\
             let plan = df.lazy()\n\
                 .filter(col(\"age\").gt(10).and_(col(\"score\").ge(3.5)))\n\
                 .select(vec![\"name\", \"age\"])\n\
                 .limit(2);\n\
             println(plan.explain());\n\
             let out = plan.collect();\n\
             println(out.height());\n\
             let names: Column[String] = out.column(\"name\");\n\
             match names[0] { Some(v) => println(v), None => println(\"null\") }\n\
             match names[1] { Some(v) => println(v), None => println(\"null\") }\n\
         }",
    );
    assert_eq!(
        out,
        "== logical plan ==\n\
         LIMIT 2\n\
         \x20 SELECT [name, age]\n\
         \x20   FILTER ((age > 10) and (score >= 3.5))\n\
         \x20     SCAN [age, name, score]\n\
         == optimized ==\n\
         SELECT [name, age]\n\
         \x20 LIMIT 2\n\
         \x20   FILTER ((age > 10) and (score >= 3.5))\n\
         \x20     SCAN cols=[age, name, score]\n\
         2\nada\nbob\n",
        "filter must render in both plans and evaluate per row",
    );
}

#[test]
fn test_lazyframe_filter_nulls_col_vs_col_and_combinators() {
    // NULL slots fail comparisons (rows dropped); col-vs-col comparisons;
    // eq/ne + not_ + or_; adjacent filters fuse with `and` in the
    // optimized plan; LazyExpr.col is the canonical (import-free) spelling.
    let out = run_no_errors(
        "fn main() {\n\
             let mut df: DataFrame = DataFrame.new();\n\
             df.insert(\"age\", Column.from_vec([30i64, 15i64, 41i64, 8i64]));\n\
             df.insert(\"name\", Column.from_vec([\"ada\", \"bob\", \"eve\", \"kid\"]));\n\
             let nn: Vec[Option[i64]] = vec![Some(30i64), None, Some(41i64), Some(8i64)];\n\
             df.insert(\"opt\", Column.from_iter_nullable(nn));\n\
             println(df.lazy().filter(LazyExpr.col(\"opt\").eq(LazyExpr.col(\"age\"))).collect().height());\n\
             println(df.lazy().filter(LazyExpr.col(\"name\").ne(\"bob\").not_()).collect().height());\n\
             println(df.lazy().filter(LazyExpr.col(\"age\").lt(10).or_(LazyExpr.col(\"age\").gt(40))).collect().height());\n\
             let fused = df.lazy().filter(LazyExpr.col(\"age\").gt(10)).filter(LazyExpr.col(\"age\").lt(40));\n\
             println(fused.collect().height());\n\
             println(fused.explain());\n\
         }",
    );
    assert_eq!(
        out,
        "3\n1\n2\n2\n\
         == logical plan ==\n\
         FILTER (age < 40)\n\
         \x20 FILTER (age > 10)\n\
         \x20   SCAN [age, name, opt]\n\
         == optimized ==\n\
         FILTER ((age > 10) and (age < 40))\n\
         \x20 SCAN cols=[age]\n",
        "nulls drop, col-vs-col compares, adjacent filters fuse",
    );
}

